local config = {
  ui_story_5079_50790100_1_dialog_content = "<color=#e8d9bb>Klikety-klak, klikety-klak—</color>",
  ui_story_5079_50790100_2_dialog_content = "Pact?",
  ui_story_5079_50790100_3_dialog_content = "<color=#e8d9bb>Klikety-klak, klikety-klak—</color>",
  ui_story_5079_50790100_4_dialog_content = "…Hah?",
  ui_story_5079_50790100_5_dialog_content = "\"Hmm\"? Di saat-saat seperti ini, itu saja yang bisa kamu katakan? Tolong jelaskan sekarang juga.",
  ui_story_5079_50790100_6_dialog_content = "Ah...",
  ui_story_5079_50790100_7_dialog_content = "Jangan salah paham—saya tidak di sini untuk mencuri Koper Putih Anda. Saya hanya datang untuk mengambil sejumlah uang yang saya tinggalkan di dalamnya.",
  ui_story_5079_50790100_8_dialog_content = "... Berapa kali aku harus bilang kepadamu untuk tidak menaruh barang di dalam White Suitcase-ku? Apakah kamu tahu betapa sulitnya membuatnya memuntahkan barang-barang itu kembali?",
  ui_story_5079_50790100_9_dialog_content = "Jika kamu datang untuk memeras uang dariku, setidaknya kamu bisa berpikir tentang alasan yang lebih baik.",
  ui_story_5079_50790100_10_dialog_content = "\"Memeras\"? Saya tidak akan pernah melakukan sesuatu yang tidak pantas! Saya hanya tidak bisa memikirkan tempat yang lebih aman untuk menyimpan uang saya, itu saja...",
  ui_story_5079_50790100_11_dialog_content = "Tanya saja pada White Suitcase-mu jika kamu tidak percaya padaku! Kau bisa berkomunikasi dengannya, 'kan?",
  ui_story_5079_50790100_12_dialog_content = "... Lupakan saja. Sekarang bukan waktu yang tepat untuk kamu melakukan \"penarikan\" dari Koper Putih.",
  ui_story_5079_50790100_13_dialog_content = "Di sini, apakah ini cukup untuk kamu?",
  ui_story_5079_50790100_14_dialog_content = "Apakah Anda mencoba menghina saya? Apa ini, upah yang sedikit sekali?",
  ui_story_5079_50790100_15_dialog_content = "Lalu bagaimana dengan ini? Masih berpikir itu sejumlah kecil?",
  ui_story_5079_50790100_16_dialog_content = "Itu masih belum cukup.",
  ui_story_5079_50790100_17_dialog_content = "Lalu di sini, tapi ini yang terakhir. Jika ada lebih banyak lagi, saya akan mulai meragukan niatmu.",
  ui_story_5079_50790100_18_dialog_content = "Bisakah kita berhenti berbelit-belit? Berikan saja semua uang yang kamu bawa sekarang, dan kita bisa selesai di sini.",
  ui_story_5079_50790100_19_dialog_content = "Semuanya? Akhirnya kau dibutakan oleh kejahatan dan membutuhkan jumlah uang yang sangat besar untuk melakukan perbuatan jahatmu?",
  ui_story_5079_50790100_20_dialog_content = "Apa yang kamu bicarakan? Saya hanya butuh uang untuk membeli bahan-bahan untuk <color=#FFB400>jamuan makan</color> kita!",
  ui_story_5079_50790100_21_dialog_content = "Jarang sekali saya mendapatkan kesempatan untuk bertanggung jawab atas sesuatu seperti ini. Ini adalah kesempatan yang sempurna...",
  ui_story_5079_50790100_22_dialog_content = "Aku bisa menunjukkan kepada kalian semua apa artinya menjalankan misi dengan sempurna. Dengan begitu, orang-orang akan berhenti memperlakukanku seperti karakter sampingan.",
  ui_story_5079_50790100_23_dialog_content = "Kamu sedang mencari bahan-bahan untuk <color=#FFB400>jamuan makan</color> kita? Dan kamu pikir kamu bisa menyelesaikan tugas penting semacam itu dengan tabungan minimmu?",
  ui_story_5079_50790100_24_dialog_content = "Humph! Percayalah, aku punya beberapa trik di lengan bajuku. Sekarang serahkan semua uangmu!",
  ui_story_5079_50790100_25_dialog_content = "Baiklah, tapi jika saya gagal mendapatkan jumlah yang sama dari dalam White Suitcase saya, saya akan—",
  ui_story_5079_50790100_26_dialog_content = "Ya, ya, saya tahu!",
  ui_story_5079_50790100_27_dialog_content = "Heheheh, tunggu saja! Perjamuan berikutnya ini akan membuat semua orang terpukau!",
  ui_story_5079_50790100_28_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790100_29_dialog_content = "Argh... Kepalaku...",
  ui_story_5079_50790100_30_dialog_content = "Apakah aku tanpa sengaja tertidur? Mimpiku terasa sangat panjang juga... Tapi tentang apa ya?",
  ui_story_5079_50790100_31_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790100_32_dialog_content = "Tunggu... Apakah saya di kereta?",
  ui_story_5079_50790100_33_dialog_content = "Sial! Saya rasa saya tidak punya cukup waktu untuk membeli pakaian baru—",
  ui_story_5079_50790100_34_dialog_content = "Hah? Tunggu, pakaianku...",
  ui_story_5079_50790100_35_dialog_content = "Heh, sepertinya aku belum sepenuhnya bangun tadi. Sepertinya aku sudah ganti pakaian.",
  ui_story_5079_50790100_36_dialog_content = "Sebelum melakukan jenis bisnis apa pun, membuat diri Anda terlihat bermartabat dan menarik adalah hal paling penting yang bisa Anda lakukan.",
  ui_story_5079_50790100_37_dialog_content = "Hanya dengan melakukan hal tersebut, pelanggan kaya akan memberikan waktu dan dukungan mereka kepada Anda.",
  ui_story_5079_50790100_38_dialog_content = "Itulah yang dia katakan... bertahun-tahun yang lalu.",
  ui_story_5079_50790100_39_dialog_content = "Meskipun aku hampir tidak bisa mengingat wajahnya, omelannya masih berdengung di kepalaku...",
  ui_story_5079_50790100_40_dialog_content = "Ngomong-ngomong, aku tidak bisa tidak mempercayainya dalam urusan bisnis.",
  ui_story_5079_50790100_41_dialog_content = "Bagaimanapun juga, dia mungkin bisa menjadi pedagang yang kuat saat itu jika bukan karena aku... Heh.",
  ui_story_5079_50790100_42_dialog_content = "<color=#e8d9bb>Kereta sekarang tiba di <color=#FFB400>Kota Folta</color>.</color>",
  ui_story_5079_50790100_43_dialog_content = "Folta... sebuah kota yang terkenal dengan pasar makanan grosirnya. Akhirnya, saya hampir sampai di sana, ya?",
  ui_story_5079_50790100_44_dialog_content = "Saya yakin orang-orang malas itu tidak pernah repot-repot datang ke sini untuk mencari bahan-bahan!",
  ui_story_5079_50790100_45_dialog_content = "Namun, aku harus berterima kasih kepada mereka karena telah menetapkan standar yang begitu rendah. Ini hanya berarti aku akan lebih bersinar saat aku menyelesaikan ini.",
  ui_story_5079_50790100_46_dialog_content = "Mungkin saja saya bisa mendapatkan keinginan saya jika saya melakukan ini dengan benar, dan saya tidak perlu bekerja untuk hal itu lagi...",
  ui_story_5079_50790100_47_dialog_content = "Kamu telah melakukan dengan baik, Pact. Sebagai hadiah, saya akan mengabulkan satu permintaanmu.",
  ui_story_5079_50790100_48_dialog_content = "Jika saya tidak salah ingat, keinginan aslimu... adalah untuk menyingkirkan Hunting Stone, benar?",
  ui_story_5079_50790100_49_dialog_content = "Ketika kamu telah mengambil keputusan, temuilah aku.",
  ui_story_5079_50790100_50_dialog_content = "Astaga, Pact! Saya terkejut kamu bisa mengumpulkan bahan-bahan pilihan untuk pesta kita.",
  ui_story_5079_50790100_51_dialog_content = "Sebenarnya... Aku tidak pernah bisa mencapai prestasi seperti itu untuk diriku sendiri.",
  ui_story_5079_50790100_52_dialog_content = "Tolong, kamu harus mengajari aku cara-caramu.",
  ui_story_5079_50790100_53_dialog_content = "Heheh... Heheheheh...",
  ui_story_5079_50790100_54_dialog_content = "Maafkan saya, nona, tapi sepertinya Anda lupa barang bawaan Anda.",
  ui_story_5079_50790100_55_dialog_content = "Hah? Kayaknya kamu salah orang. Aku bukan tipe orang yang suka salah letak barang.",
  ui_story_5079_50790100_56_dialog_content = "Maaf, hanya saja koper ini sangat cocok dengan pakaianmu, jadi saya asumsikan itu milikmu.",
  ui_story_5079_50790100_57_dialog_content = "...",
  ui_story_5079_50790100_58_dialog_content = "Oh, kamu maksud Hunting Stone? Jangan khawatir, itu mengikutiku ke mana pun aku pergi. Aku tidak bisa menyingkirkannya meski aku ingin.",
  ui_story_5079_50790100_59_dialog_content = "Aku kaget kamu tidak takut padanya. Itu cukup jarang.",
  ui_story_5079_50790100_60_dialog_content = "Takut? Tentu saja tidak! Saya justru merasa itu cukup menarik.",
  ui_story_5079_50790100_61_dialog_content = "(Sepertinya konduktor ini cukup berpikiran terbuka. Saya tidak bisa menghitung berapa kali orang-orang menjauhiku karena Hunting Stone.)",
  ui_story_5079_50790100_62_dialog_content = "(Bahkan toko-toko pakaian yang mengklaim \"pelanggan adalah nomor satu\" pun tidak memberi saya waktu...)",
  ui_story_5079_50790100_63_dialog_content = "E-Excuse me, tapi... a-apa itu di belakangmu?",
  ui_story_5079_50790100_64_dialog_content = "Mungkin lebih baik jika Anda mencoba toko lain, nona. Meskipun Anda pasti mampu membeli pakaian kami, saya khawatir kami tidak mampu kehilangan pelanggan karena... teman Anda.",
  ui_story_5079_50790100_65_dialog_content = "Tidak perlu menawarkan lebih banyak uang, nona...",
  ui_story_5079_50790100_66_dialog_content = "Bolehkah saya memberikan saran? Jika kamu tidak keberatan, bagaimana kalau membeli sesuatu untuk membuat temanmu terlihat... sedikit kurang menakutkan?",
  ui_story_5079_50790100_67_dialog_content = "Kalau tidak, aku takut itu akan merusak penampilan pakaianmu, dan uangmu akan terbuang sia-sia...",
  ui_story_5079_50790100_68_dialog_content = "Kamu bilang namanya Hunting Stone? Sungguh nama yang megah! Kereta saya, Other End, juga memiliki nama yang sama megahnya.",
  ui_story_5079_50790100_69_dialog_content = "Saya tidak ingat meminta nama kereta apimu...",
  ui_story_5079_50790100_70_dialog_content = "Saya bisa melihat bahwa Hunting Stone-mu sangat mirip dengan Other End-ku, dalam hal mereka menempati tempat yang serupa di hati kita.",
  ui_story_5079_50790100_71_dialog_content = "Maka kamu mungkin harus memeriksa mata kamu, kecuali jika kamu ingin meninggalkan kereta ini juga. Bagiku, Hunting Stone... hanyalah sebuah beban.",
  ui_story_5079_50790100_72_dialog_content = "Hahaha! Saya tidak akan pernah meninggalkan teman lama saya, dan sesuatu memberitahu saya... begitu juga dengan Anda. Sampai jumpa lagi, nyonya.",
  ui_story_5079_50790100_73_dialog_content = "Apa sih yang sedang dia omongkan?",
  ui_story_5079_50790100_74_dialog_content = "Dengar, Hunting Stone. Aku tahu kamu tidak mengerti berapa banyak uang yang telah aku habiskan untuk dekorasi ini untukmu...",
  ui_story_5079_50790100_75_dialog_content = "Tapi kamu harus berjanji untuk tidak menakuti siapa pun. Misi ini sangat berarti bagi saya!",
  ui_story_5079_50790100_76_dialog_content = "!",
  ui_story_5079_50790100_77_dialog_content = "Bagus! Karena kita sekarang sejalan, kamu bisa berhenti bergerak lebih cepat dariku—",
  ui_story_5079_50790100_78_dialog_content = "A-Apa ini?",
  ui_story_5079_50790100_79_dialog_content = "... Bagus. Kami bahkan belum turun dari kereta, dan kami sudah membuat orang ketakutan.",
  ui_story_5079_50790100_80_dialog_content = "Sesuatu yang begitu elegan pasti milik orang yang cukup penting...",
  ui_story_5079_50790100_81_dialog_content = "Ehem... Maaf tentang itu. Aku akan menghilangkannya sekarang juga.",
  ui_story_5079_50790100_82_dialog_content = "Kamu? Katakan padaku, apakah kamu salah satu dari elit kaya di Lumopolis, atau mungkin Umbraton?",
  ui_story_5079_50790100_83_dialog_content = "Mohon maafkan ketidak sopananku barusan! Aku tidak bermaksud apa-apa...",
  ui_story_5079_50790100_84_dialog_content = "Kenapa kamu minta maaf? Justru aku yang menghalangi jalanmu, bukan?",
  ui_story_5079_50790100_85_dialog_content = "Saya merasa terhormat bisa berbagi kereta ini dengan Anda hari ini, Nyonya. Selamat berperjalanan...",
  ui_story_5079_50790100_86_dialog_content = "T-Terima kasih.",
  ui_story_5079_50790100_87_dialog_content = "Sangat aneh... Apa yang salah dengan pria itu barusan? Apakah pakaian ini ajaib atau apa?",
  ui_story_5079_50790100_88_dialog_content = "Dan mengapa rasanya aku pernah melihatnya di suatu tempat sebelumnya?",
  ui_story_5079_50790100_89_dialog_content = "Ah, lupakan saja. Sekarang bukan waktunya untuk mengkhawatirkan hal-hal ini...",
  ui_story_5079_50790100_90_dialog_content = "*mengendus*",
  ui_story_5079_50790100_91_dialog_content = "Wow, bau-bauan itu... Daging sapi dan tomat! Kue krim dan roti yang baru dipanggang! Dan masih banyak lagi...",
  ui_story_5079_50790100_92_dialog_content = "Itu Folta untukmu! Kita bahkan belum meninggalkan kereta, dan aku sudah bisa mencium begitu banyak makanan yang enak!",
  ui_story_5079_50790100_93_dialog_content = "Sepertinya kita harus mencicipi beberapa hidangan lokal sebelum mulai berbisnis!",
  ui_story_5079_50790100_94_dialog_content = "!",
  ui_story_5079_50790200_1_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5079_50790200_2_dialog_content = "Jadi ini Folta!",
  ui_story_5079_50790200_3_dialog_content = "Arsitekturnya sangat unik. Tempat ini tampaknya lebih terobsesi dengan makanan daripada Umbraton!",
  ui_story_5079_50790200_4_dialog_content = "Hah? Apakah mungkin rumah-rumah ini dibuat dari bahan-bahan asli?",
  ui_story_5079_50790200_5_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790200_6_dialog_content = "Ah... Aku akan ketinggalan kereta! Permisi!",
  ui_story_5079_50790200_7_dialog_content = "Eh?",
  ui_story_5079_50790200_8_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5079_50790200_9_dialog_content = "Aduh…",
  ui_story_5079_50790200_10_dialog_content = "Baru saja aku beli pakaian ini! Pasti sekarang sudah kotor!",
  ui_story_5079_50790200_11_dialog_content = "Hah? Mereka sama sekali tidak kotor. Bahkan, mereka mengeluarkan aroma manis... Tunggu, apakah batu-batu ini di tanah terbuat dari permen?",
  ui_story_5079_50790200_12_dialog_content = "...",
  ui_story_5079_50790200_13_dialog_content = "Saya penasaran rasanya seperti apa? Biasanya saya makan batu Lumopolis untuk membantu pencernaan, jadi satu gigitan kecil tidak akan menyakiti...",
  ui_story_5079_50790200_14_dialog_content = "Ah!",
  ui_story_5079_50790200_15_dialog_content = "Ha?",
  ui_story_5079_50790200_16_dialog_content = "Apa yang sedang kamu lakukan, nona? Batu-batu ini bukan untuk dimakan!",
  ui_story_5079_50790200_17_dialog_content = "Heh, katakanlah kamu... Lagipula, siapa kamu untuk bilang aku tidak boleh memakannya?",
  ui_story_5079_50790200_18_dialog_content = "Sepertinya kamu tidak mengerti, yang berarti kamu mungkin bukan dari sekitar sini.",
  ui_story_5079_50790200_19_dialog_content = "Batu-batu ini adalah makanan untuk <color=#FFB400>sparrow permen</color>. Berkat bantuan mereka, kita bisa membangun gedung dari makanan!",
  ui_story_5079_50790200_20_dialog_content = "Bagaimana Anda bisa berpikir untuk mencabut makanan dari makhluk yang bekerja keras seperti itu?",
  ui_story_5079_50790200_21_dialog_content = "Jadi, kamu bilang semua bangunan di sini benar-benar terbuat dari makanan?",
  ui_story_5079_50790200_22_dialog_content = "Uh-huh! Lihat saja sekeliling—lantai dibuat dari biji kakao, dan lampu jalannya adalah lolipop yang bercahaya, dan...",
  ui_story_5079_50790200_23_dialog_content = "Hei! Apa yang sedang kamu lakukan pada lampu jalan itu?",
  ui_story_5079_50790200_24_dialog_content = "Hukuman untuk merusak properti umum itu serius! Mereka akan menggantungmu di jalan dan membiarkan burung gereja permen mematukmu hingga hancur...",
  ui_story_5079_50790200_25_dialog_content = "Tidak tahukah kamu apa-apa tentang tempat ini?",
  ui_story_5079_50790200_26_dialog_content = "Kedengarannya seperti omong kosong bagi saya. Apakah kamu yakin kamu tidak hanya mengarang semuanya?",
  ui_story_5079_50790200_27_dialog_content = "Apa kamu bercanda? Itulah alasan utama jalan-jalan di Folta begitu bersih dan rapi!",
  ui_story_5079_50790200_28_dialog_content = "Tahu tidak, Nona... Meskipun kamu mengenakan pakaian yang begitu mewah, sikapmu tidak berbeda dengan anak kecil.",
  ui_story_5079_50790200_29_dialog_content = "Tebak ayahku berbohong ketika dia mengatakan bahwa orang yang berpakaian rapi berperilaku lebih baik daripada orang lain!",
  ui_story_5079_50790200_30_dialog_content = "Katakanlah... Kamu tidak mencuri pakaian itu, bukan? Kamu tidak mencuri, bukan?",
  ui_story_5079_50790200_31_dialog_content = "Hah? Harus kamu tahu, aku menghabiskan banyak uang untuk pakaian ini...",
  ui_story_5079_50790200_32_dialog_content = "(Humph, aku tidak perlu duduk di sini dan mendengarkan omelan dari seorang gadis kecil.)",
  ui_story_5079_50790200_33_dialog_content = "(Dia tidak menghormati orang yang lebih tua, atau batasan apapun... Tapi entah mengapa, sikap menjengkelkannya itu anehnya familiar.)",
  ui_story_5079_50790200_34_dialog_content = "Hmm... Aku merasa seperti bertemu dengan wanita aneh ini membuatku lupa sesuatu...",
  ui_story_5079_50790200_35_dialog_content = "<color=#e8d9bb>Choooooo—</color>",
  ui_story_5079_50790200_36_dialog_content = "Oh sial, kereta itu! Sudah berangkat!",
  ui_story_5079_50790200_37_dialog_content = "Ini semua salahmu! Pertama, kamu menabrakku, lalu kamu membuang-buang waktuku dengan ulahmu, dan akhirnya aku ketinggalan kereta!",
  ui_story_5079_50790200_38_dialog_content = "Rencana saya untuk kabur dari rumah gagal! Saya harap kamu siap untuk menebusnya kepada saya!",
  ui_story_5079_50790200_39_dialog_content = "Hah? Kamu lari? Dan apa maksudmu dengan \"menebusnya padaku\"?",
  ui_story_5079_50790200_40_dialog_content = "Kamu yang menabrakku... Jika ada yang harus menebus, seharusnya itu adalah kamu!",
  ui_story_5079_50790200_41_dialog_content = "Lagi pula, aku baru saja membantumu dengan menggagalkan rencanamu untuk kabur. Sedikit ucapan terima kasih sepertinya pantas, bukan?",
  ui_story_5079_50790200_42_dialog_content = "Hah? Kau sedang bermimpi jika kau pikir aku harus berterima kasih padamu! Lagipula, kau pasti akan dicabik-cabik jika bukan karena aku!",
  ui_story_5079_50790200_43_dialog_content = "Jika ada yang harus berterima kasih di sini, itu adalah kamu!",
  ui_story_5079_50790200_44_dialog_content = "Jangan salah paham, anak! Aku hanya melakukan itu karena aku sedang meneliti bahan-bahan!",
  ui_story_5079_50790200_45_dialog_content = "Kamu tidak berpikir aku akan makan batu hanya karena aku lapar, kan? Kan?",
  ui_story_5079_50790200_46_dialog_content = "Dan sekarang kau meniruku! Urgh... Kau benar-benar belum dewasa, tahu itu?",
  ui_story_5079_50790200_47_dialog_content = "Aku sudah selesai berdebat dengan anak ini. Aku punya banyak belanjaan untuk dilakukan, dan aku masih perlu mengunjungi banyak toko dan membandingkan harga mereka.",
  ui_story_5079_50790200_48_dialog_content = "... T-Tunggu!",
  ui_story_5079_50790200_49_dialog_content = "Apa sekarang?",
  ui_story_5079_50790200_50_dialog_content = "Kamu di sini untuk membeli bahan makanan, 'kan? Itulah bisnis keluarga kami! Mau datang ke toko kami?",
  ui_story_5079_50790200_51_dialog_content = "Sekarang kamu menginginkan bisnisku setelah semua pertengkaran itu? Maaf, tapi aku tidak tertarik.",
  ui_story_5079_50790200_52_dialog_content = "<size=30>*huft* Gagal lagi...</size>",
  ui_story_5079_50790200_53_dialog_content = "(Ayah selalu bilang kita tidak boleh melewatkan kesempatan untuk membuat kesepakatan dengan pelanggan kaya seperti dia...)",
  ui_story_5079_50790200_54_dialog_content = "(Jika aku bisa membujuknya untuk datang ke toko kita... Aku yakin ayah akan memujiku banyak! Mungkin dia akan melupakan semua yang terjadi beberapa hari terakhir ini juga.)",
  ui_story_5079_50790200_55_dialog_content = "(Tapi yang paling penting, aku bisa menggunakan ini sebagai kesempatan untuk menghilangkan semua makanan yang tidak aku suka... Heeheehee!)",
  ui_story_5079_50790200_56_dialog_content = "A-Aku bisa meminta ayahku untuk memberimu diskon yang luar biasa! Anggap saja sebagai caraku untuk menebus kesalahanku padamu!",
  ui_story_5079_50790200_57_dialog_content = "Bukankah kamu mencoba untuk kabur dari rumah? Kenapa kamu malah membawa orang asing ke rumah dan meminta diskon?",
  ui_story_5079_50790200_58_dialog_content = "Jika aku adalah ayahmu, aku tidak akan pernah menyetujui hal seperti itu.",
  ui_story_5079_50790200_59_dialog_content = "*Tersedu* A-Apa yang harus kulakukan?",
  ui_story_5079_50790200_60_dialog_content = "Mengerti! Aku akan memberitahunya bahwa kamu khawatir tentang keselamatanku, jadi kamu membawaku pulang! Dia akan sangat berterima kasih sehingga dia akan menawarkanmu kesepakatan seumur hidup!",
  ui_story_5079_50790200_61_dialog_content = "Memang masuk akal... Saya kira satu perbuatan baik tidak akan merugikan.",
  ui_story_5079_50790200_62_dialog_content = "Ingat, aku tidak bisa berjanji akan berbisnis dengan keluargamu. Tunjukkan jalannya, Nak.",
  ui_story_5079_50790200_63_dialog_content = "Hah? Apa itu di belakangmu?",
  ui_story_5079_50790200_64_dialog_content = "Akhirnya kamu sadar juga, ya? Tidak terlambat untuk merasa takut, tahu! Terutama sekarang kamu tahu apa yang akan terjadi jika kamu membuatku marah...",
  ui_story_5079_50790200_65_dialog_content = "Wow, ini sangat lucu! Dan lihat, dia bisa bergerak sendiri! Bolehkah saya membelainya? Bolehkah saya?",
  ui_story_5079_50790200_66_dialog_content = "Hei, hentikan itu! Ini bukan mainan!",
  ui_story_5079_50790200_67_dialog_content = "Kenapa kamu jadi marah begitu? Aku hanya ingin membelai teman kecilmu...",
  ui_story_5079_50790200_68_dialog_content = "\"Teman kecilku\"? Kamu pikir Hunting Stone itu... Urgh, lupakan saja.",
  ui_story_5079_50790200_69_dialog_content = "Hancurkan dirimu, nak, tapi kamu harus memberiku diskon yang lebih besar setiap kali kamu mengelusnya.",
  ui_story_5079_50790200_70_dialog_content = "O-Oke kalau begitu... Aku hanya akan membelainya sekali...",
  ui_story_5079_50790200_71_dialog_content = "!",
  ui_story_5079_50790200_72_dialog_content = "Wow, dia sangat menggemaskan! Dia merapat kepadaku, jadi belaian terakhir itu tidak dihitung!",
  ui_story_5079_50790200_73_dialog_content = "!",
  ui_story_5079_50790200_74_dialog_content = "(Hunting Stone membiarkannya menyentuhnya? Kenapa, roda yang tidak berguna ini!)",
  ui_story_5079_50790200_75_dialog_content = "Baiklah, itu sudah cukup! Ayo kita pergi!",
  ui_story_5079_50790300_1_dialog_content = "Hmm, hmm, hmm!",
  ui_story_5079_50790300_2_dialog_content = "... Apa yang membuatmu sangat senang?",
  ui_story_5079_50790300_3_dialog_content = "Kamu adalah pelanggan besar pertama yang pernah aku bawa pulang, jadi tentu saja aku senang! Ayah pasti akan sangat senang padaku!",
  ui_story_5079_50790300_4_dialog_content = "Apakah kamu biasanya membantu bisnis keluargamu?",
  ui_story_5079_50790300_5_dialog_content = "Ya... Tapi biasanya aku hanya menghalangi. Bahkan, aku pikir aku adalah alasan toko kita berjalan buruk akhir-akhir ini.",
  ui_story_5079_50790300_6_dialog_content = "Tapi sekarang setelah kamu di sini, mungkin keadaan akhirnya bisa berbalik untuk kita!",
  ui_story_5079_50790300_7_dialog_content = "... Aku bahkan tidak tahu namamu, Anak.",
  ui_story_5079_50790300_8_dialog_content = "Hah? Aku?",
  ui_story_5079_50790300_9_dialog_content = "Ha?",
  ui_story_5079_50790300_10_dialog_content = "Namaku... <color=#FFB400>Popo</color>.",
  ui_story_5079_50790300_11_dialog_content = "Ah, jangan berpikiran aneh! Itu hanya sebuah nama! Nama yang benar-benar normal!",
  ui_story_5079_50790300_12_dialog_content = "Sebenarnya aku tidak akan memikirkannya lagi, tapi karena kamu membuatnya menjadi masalah besar, sekarang aku jadi ingin bertanya...",
  ui_story_5079_50790300_13_dialog_content = "Ini nama yang cukup lucu, kamu tahu.",
  ui_story_5079_50790300_14_dialog_content = "Baiklah, cukup sudah! Kita di sini bukan untuk membahas keimutan nama, ayo kita pergi sekarang!",
  ui_story_5079_50790300_15_dialog_content = "Ini tempatnya!",
  ui_story_5079_50790300_16_dialog_content = "Benarkah? Rasanya tidak terlalu seperti bisnis...",
  ui_story_5079_50790300_17_dialog_content = "Hmm... Ayah? Apakah kamu di rumah?",
  ui_story_5079_50790300_18_dialog_content = "Nah, saya tidak bermaksud untuk tidak sopan, tetapi ada tanda \"tutup\" yang dipasang di pintu.",
  ui_story_5079_50790300_19_dialog_content = "Sepertinya toko kamu sudah lama tidak buka. Kamu tidak sadar akan hal itu?",
  ui_story_5079_50790300_20_dialog_content = "?",
  ui_story_5079_50790300_21_dialog_content = "Aku sama sekali tak paham maksudmu!",
  ui_story_5079_50790300_22_dialog_content = "Ayahku sangat mencintai tokonya, dan dia selalu membukanya setiap hari sepanjang tahun! Bagaimana mungkin bisa tutup?",
  ui_story_5079_50790300_23_dialog_content = "Mengapa kamu tidak melihat sendiri? Di sini tertulis, \"Toko tutup karena alasan keluarga.\"",
  ui_story_5079_50790300_24_dialog_content = "(Aku tahu seharusnya aku tidak terlibat dengan anak ini. Aku sudah membuang begitu banyak waktu.)",
  ui_story_5079_50790300_25_dialog_content = "(Jika aku tidak melakukan ini dengan sempurna, siapa tahu seberapa buruk mereka akan mengejekku...)",
  ui_story_5079_50790300_26_dialog_content = "Maaf, Popo, tapi aku tidak bisa berbisnis dengan keluarga kamu jika tidak ada bisnis sama sekali. Aku harus pergi—",
  ui_story_5079_50790300_27_dialog_content = "*menangis*... <size=45>Waaaaaaaaahhh!</size>",
  ui_story_5079_50790300_28_dialog_content = "Hei, jangan menangis! Orang-orang akan berpikir aku membulimu!",
  ui_story_5079_50790300_29_dialog_content = "Itu karena kamu MEMANG sedang mengolok-olokku!",
  ui_story_5079_50790300_30_dialog_content = "Kalau saja aku tidak ketinggalan kereta, sekarang ini aku pasti sudah pergi jauh! Lalu aku tidak akan pernah tahu bahwa ayahku sebenarnya tidak menginginkanku lagi!",
  ui_story_5079_50790300_31_dialog_content = "Tapi tetap saja, menangis tidak akan menyelesaikan apa pun. Apakah kamu memiliki orang lain untuk diandalkan selain ayahmu?",
  ui_story_5079_50790300_32_dialog_content = "Tidak... Ibu saya sudah lama meninggal. Sejak itu, Ayah dan saya saling merawat satu sama lain...",
  ui_story_5079_50790300_33_dialog_content = "Tapi kami selalu bertengkaran... Dan selama pertengkaran terakhir kami, dia bilang dia tidak butuh anak perempuan yang tidak patuh seperti saya.",
  ui_story_5079_50790300_34_dialog_content = "Aku juga sangat marah padanya! Marah sekali sampai-sampai aku kabur dari rumah...",
  ui_story_5079_50790300_35_dialog_content = "Aku tidak menyangka dia benar-benar akan pergi... Ayah sepertinya tidak mencintaiku lagi... Huaaaa!",
  ui_story_5079_50790300_36_dialog_content = "Tapi, berdebat dengan ayahmu itu normal, bukan?",
  ui_story_5079_50790300_37_dialog_content = "*mengendus*... Apakah itu berarti kamu juga bertengkar dengan ayahmu?",
  ui_story_5079_50790300_38_dialog_content = "Aku memang melakukannya, dan itu cukup buruk juga. Dia menolak untuk menerima aku atau Hunting Stone-ku di sini—yang menurutmu sangat lucu.",
  ui_story_5079_50790300_39_dialog_content = "...",
  ui_story_5079_50790300_40_dialog_content = "Jadi dia meninggalkan beberapa uang untukku, dan kemudian aku tidak pernah melihatnya lagi...",
  ui_story_5079_50790300_41_dialog_content = "Hah? Maksudmu ayahmu benar-benar meninggalkan uang untukmu?",
  ui_story_5079_50790300_42_dialog_content = "Tapi ayahku tidak meninggalkan apa pun sebelum meninggalkan saya!",
  ui_story_5079_50790300_43_dialog_content = "<size=50>Waaaaaaaaaah!</size>",
  ui_story_5079_50790300_44_dialog_content = "Jangan bilang begitu, Popo! Ayahmu mewariskan toko ini padamu, bukan?",
  ui_story_5079_50790300_45_dialog_content = "Aku cukup yakin itu membuatmu menjadi bos di sini, 'kan? Jika iya, bisakah aku membeli meja cokelat ini darimu? Aku cukup lapar!",
  ui_story_5079_50790300_46_dialog_content = "Terlihat sedikit keras, tapi aku yakin rasanya enak. Lihat, ada lapisan frosting di atasnya!",
  ui_story_5079_50790300_47_dialog_content = "Oh? Apakah kaca pada lemari itu terbuat dari gula merah yang dikaramelisasi?",
  ui_story_5079_50790300_48_dialog_content = "Dan vas itu sebenarnya adalah guci madu! Bolehkah saya mencelupkan ini ke dalam madu? Vasnya juga terlihat cukup lezat...",
  ui_story_5079_50790300_49_dialog_content = "Ahhhh! Berhenti mencoba memakan perabotan! Ini masih rumahku, tahu!",
  ui_story_5079_50790300_50_dialog_content = "Kamu benar-benar tidak punya tata krama sama sekali, apalagi selera!",
  ui_story_5079_50790300_51_dialog_content = "Maksudku, apa jenis orang yang mencelupkan permen keras ke dalam madu? Apakah kamu mencoba merusak gigimu?",
  ui_story_5079_50790300_52_dialog_content = "Oh bagus, kamu tidak menangis lagi.",
  ui_story_5079_50790300_53_dialog_content = "Hah? Kamu mencoba menghiburku?",
  ui_story_5079_50790300_54_dialog_content = "Tidak, aku hanya benar-benar, benar-benar lapar.",
  ui_story_5079_50790300_55_dialog_content = "Yah... Itu tetap bukan alasan bagi kamu untuk memakan furnitur kami!",
  ui_story_5079_50790300_56_dialog_content = "Kami masih punya banyak wortel di stok, jadi silakan ambil sesuka hati.",
  ui_story_5079_50790300_57_dialog_content = "Wortel? Ih...",
  ui_story_5079_50790300_58_dialog_content = "Apa? Kamu juga tidak suka wortel?",
  ui_story_5079_50790300_59_dialog_content = "Itu bahkan tidak mendekati deskripsi kebencian saya terhadap mereka... Wortel adalah makanan paling menakutkan di dunia!",
  ui_story_5079_50790300_60_dialog_content = "Iya, iya, aku tahu!",
  ui_story_5079_50790300_61_dialog_content = "Wortel seharusnya tidak ada di dunia ini! Mereka adalah alasan utama saya berkelahi dengan ayah saya!",
  ui_story_5079_50790300_62_dialog_content = "Dia berkata bahwa sangat tidak dapat diterima jika seorang anak perempuan penjual wortel membenci makan wortel, dan bahwa saya telah membuat bisnis keluarga kami malu...",
  ui_story_5079_50790300_63_dialog_content = "Tapi tidak ada aturan yang mengatakan bahwa saya harus menyukai wortel hanya karena ayah saya menjualnya untuk mencari nafkah!",
  ui_story_5079_50790300_64_dialog_content = "Heh, aku tidak menyangka akan sepenuhnya setuju denganmu tentang apa pun, tapi inilah kita sekarang.",
  ui_story_5079_50790300_65_dialog_content = "Kamu berencana menjual semua wortel keluargamu kepadaku, jadi kamu tidak perlu memakannya, 'kan?",
  ui_story_5079_50790300_66_dialog_content = "Sebenarnya tidak... Aku hanya akan menjual setengah dari mereka dan menyisakan sisanya untuk ayahku, karena dia sangat menyukainya.",
  ui_story_5079_50790300_67_dialog_content = "Dia begitu, ya... Tidak heran dia menamaimu \"Popo\"! Saya yakin itu karena dia ingin kamu juga menyukai wortel!",
  ui_story_5079_50790300_68_dialog_content = "Humph! Tidak ada yang salah dengan tidak suka wortel! Dia bisa saja menamai saya \"Wortel,\" dan saya masih akan berpikir mereka menjijikan!",
  ui_story_5079_50790300_69_dialog_content = "Jadi bahkan setelah segala yang terjadi, kau masih ingin meninggalkan beberapa wortel untuk ayahmu makan?",
  ui_story_5079_50790300_70_dialog_content = "Ah... Itu ideku sebelumnya, tapi bukan lagi! Saya akan membuang semua wortel busuk ini sekarang!",
  ui_story_5079_50790300_71_dialog_content = "Masihkah kamu mencintai ayahmu?",
  ui_story_5079_50790300_72_dialog_content = "T-Tentu saja tidak! Mengapa aku harus peduli padanya setelah dia menelantarkanku seperti ini? Humph!",
  ui_story_5079_50790300_73_dialog_content = "Tapi bagaimana jika dia sebenarnya tidak meninggalkanmu?",
  ui_story_5079_50790300_74_dialog_content = "Yah, uh... Kita tunggu dan lihat saja!",
  ui_story_5079_50790300_75_dialog_content = "(Anak-anak kecil itu terlalu mudah ditebak... Saya tidak berpikir ayahnya sejahat yang dia katakan.)",
  ui_story_5079_50790300_76_dialog_content = "(Dia mungkin hanya mencoba memaksakan preferensinya pada putrinya, itulah sebabnya mereka sering bertengkar. Itu adalah kesalahan, tetapi kesalahan yang dia lakukan karena cinta.)",
  ui_story_5079_50790300_77_dialog_content = "(Sebuah celah kecil seperti itu cukup mudah untuk ditutupi.)",
  ui_story_5079_50790300_78_dialog_content = "Sepertinya masalahmu dengan ayahmu cukup kecil, setidaknya dibandingkan dengan masalahku sendiri.",
  ui_story_5079_50790300_79_dialog_content = "Suatu kali, ketika ayahku mencoba memaksaku untuk makan wortel, aku malah memakan segenggam batu hanya untuk membalasnya...",
  ui_story_5079_50790300_80_dialog_content = "Oh! Jadi itu sebabnya kamu begitu siap untuk memakan batu-batu itu tadi!",
  ui_story_5079_50790300_81_dialog_content = "Tidak ada hubungannya dengan kamu yang belum dewasa atau tidak memiliki selera sama sekali!",
  ui_story_5079_50790300_82_dialog_content = "... Apakah sulit bagimu untuk bersikap lebih sopan sesekali? Ingat, kau yang berutang padaku!",
  ui_story_5079_50790400_1_dialog_content = "Merasa lebih baik? Seharusnya, setelah semua obrolan itu...",
  ui_story_5079_50790400_2_dialog_content = "Ingatlah, setiap awan gelap memiliki kilauan perak. Kita mungkin telah ditinggalkan, tapi setidaknya kita bebas sekarang.",
  ui_story_5079_50790400_3_dialog_content = "Dan jika ayahku tidak meninggalkan aku, aku tidak akan pernah bertemu... Tidak apa-apa, kamu masih terlalu muda untuk tahu tentang itu.",
  ui_story_5079_50790400_4_dialog_content = "Saya tidak peduli tentang itu!",
  ui_story_5079_50790400_5_dialog_content = "Aku tidak akan diam saja! Aku akan membalas dendam pada Ayah!",
  ui_story_5079_50790400_6_dialog_content = "Pikirkan aku bisa meminjam rodamu sebentar? Aku ingin menggunakannya untuk menabraknya beberapa kali!",
  ui_story_5079_50790400_7_dialog_content = "...",
  ui_story_5079_50790400_8_dialog_content = "... Sudah kubilang, itu disebut Hunting Stone.",
  ui_story_5079_50790400_9_dialog_content = "Dan meski aku ingin meminjamkannya padamu... dia menolak untuk meninggalkan sisiku, selamanya.",
  ui_story_5079_50790400_10_dialog_content = "Lagipula, kamu tidak seharusnya terlalu marah tentang ini, Popo. Sesuatu mengatakan padaku bahwa ayahmu sebenarnya tidak meninggalkanmu.",
  ui_story_5079_50790400_11_dialog_content = "Tapi aku sudah menceritakan semua yang terjadi padamu...",
  ui_story_5079_50790400_12_dialog_content = "Ya, setelah melihat toko dan memikirkannya, saya pikir saya memiliki ide yang baik tentang apa yang terjadi.",
  ui_story_5079_50790400_13_dialog_content = "Lihat? Wortel dalam tumpukan ini jelas masih segar. Itu menunjukkan bahwa mereka baru saja datang, dan dia sedang bersiap untuk menjualnya.",
  ui_story_5079_50790400_14_dialog_content = "Juga, tidak ada barang berharga di rumah Anda yang hilang. Itu bukan sesuatu yang akan saya lakukan jika saya berencana untuk pergi.",
  ui_story_5079_50790400_15_dialog_content = "Dia tidak akan meninggalkan semua barang miliknya tersebar seperti ini kecuali...",
  ui_story_5079_50790400_16_dialog_content = "Kecuali?",
  ui_story_5079_50790400_17_dialog_content = "Kecuali jika dia memiliki hutang begitu banyak sehingga dia tidak bisa membayar semuanya kembali. Dia dapat menghindari kecurigaan dan melarikan diri dengan lebih mudah jika dia meninggalkan segalanya persis seperti adanya.",
  ui_story_5079_50790400_18_dialog_content = "Oh…",
  ui_story_5079_50790400_19_dialog_content = "A-Apa maksud tatapan itu?",
  ui_story_5079_50790400_20_dialog_content = "Untuk seseorang yang seimatur kamu, saya tidak menyangka kamu bisa begitu rasional!",
  ui_story_5079_50790400_21_dialog_content = "Masih menyebutku tidak dewasa, huh...",
  ui_story_5079_50790400_22_dialog_content = "Ayo kita berhenti membahasnya. Berdebat tentang hal itu hanya membuat kita berdua tampak tidak dewasa.",
  ui_story_5079_50790400_23_dialog_content = "Tapi sekarang setelah kamu menyebutkannya...",
  ui_story_5079_50790400_24_dialog_content = "Saya cukup yakin ayahku sebenarnya meminjam uang dari... <color=#FFB400>Keluarga Ketchup</color>!",
  ui_story_5079_50790400_25_dialog_content = "Tapi hutang itu seharusnya sudah dibayar lama waktu lalu! Apakah ayah telah meminjam lebih banyak uang tanpa memberi tahu saya?",
  ui_story_5079_50790400_26_dialog_content = "Saya hampir yakin ayahmu tidak perlu memberitahumu tentang utang-utangnya...",
  ui_story_5079_50790400_27_dialog_content = "Itu dia! Aku sudah mengambil keputusan!",
  ui_story_5079_50790400_28_dialog_content = "Bagus... Dan keputusan brilian apa itu?",
  ui_story_5079_50790400_29_dialog_content = "Aku akan menjenguk Keluarga Ketchup! Mereka bahkan mungkin tahu di mana ayahku sekarang!",
  ui_story_5079_50790400_30_dialog_content = "Oh? Itu sebenarnya ide yang cukup bagus.",
  ui_story_5079_50790400_31_dialog_content = "(Akhirnya saya bisa berhenti mengasuh anak ini sekarang...)",
  ui_story_5079_50790400_32_dialog_content = "Semoga Keluarga Ketchup memiliki jawaban yang kamu cari, anak. Nah, sekarang, saya seharusnya benar-benar...",
  ui_story_5079_50790400_33_dialog_content = "T-Tunggu! Kamu belum bisa pergi!",
  ui_story_5079_50790400_34_dialog_content = "Ha?",
  ui_story_5079_50790400_35_dialog_content = "Heheh, ada alasan kenapa aku terus menyebutmu kekanak-kanakan, tahu?",
  ui_story_5079_50790400_36_dialog_content = "Jika kamu pergi sekarang, kamu akan menyesal seumur hidupmu!",
  ui_story_5079_50790400_37_dialog_content = "Dan mengapa demikian?",
  ui_story_5079_50790400_38_dialog_content = "Keluarga Ketchup selalu mengendalikan kota ini. Mereka juga menjalankan toko tomat terbesar di seluruh Astra!",
  ui_story_5079_50790400_39_dialog_content = "Jika kamu mencari bahan terbaik, kamu tidak boleh melewatkannya!",
  ui_story_5079_50790400_40_dialog_content = "Kamu pasti sudah melakukan penelitian sebelum datang ke Folta, bukan? Bukan?",
  ui_story_5079_50790400_41_dialog_content = "Kami memiliki pepatah lama di sini: \"Siapa saja yang datang ke Folta tanpa berbisnis dengan Keluarga Ketchup adalah seorang bodoh!\"",
  ui_story_5079_50790400_42_dialog_content = "Kamu yakin kamu tidak hanya mengarang \"peribahasa lama\" itu, Nak?",
  ui_story_5079_50790400_43_dialog_content = "Pokoknya, saya sedang cukup murah hati hari ini! Ikutlah denganku, dan saya akan memperkenalkanmu secara pribadi ke Keluarga Ketchup!",
  ui_story_5079_50790400_44_dialog_content = "\"Murah hati,\" eh? Kamu hanya terlalu takut untuk melihat mereka sendiri, bukan?",
  ui_story_5079_50790400_45_dialog_content = "Bagaimanapun juga, saya yakin keluarga kaya seperti itu tidak punya waktu untuk anak-anak kecil seperti kamu...",
  ui_story_5079_50790400_46_dialog_content = "Dan kau pikir kau sudah siap untuk kabur dari rumah...",
  ui_story_5079_50790400_47_dialog_content = "I-Itu sama sekali bukan itu! A-Aku hanya melakukan ini demi kebaikanmu...",
  ui_story_5079_50790400_48_dialog_content = "Humph, baiklah, kamu bisa lupakan semuanya sekarang! Nikmati menjadi bodoh, lady, dan aku akan pergi melihat mereka semua sendirian!",
  ui_story_5079_50790400_49_dialog_content = "Jadi sekarang aku dianggap tidak dewasa DAN bodoh...",
  ui_story_5079_50790400_50_dialog_content = "Tsk! Anak-anak nakal seperti dia harus belajar dengan cara yang sulit.",
  ui_story_5079_50790400_51_dialog_content = "Urgh, tapi kenapa aku merasa begitu tidak nyaman?",
  ui_story_5079_50790400_52_dialog_content = "Jika dia tidak berbohong tentang Keluarga Ketchup, maka saya pasti harus mengunjungi mereka.",
  ui_story_5079_50790400_53_dialog_content = "Selain itu, saya tidak yakin Popo akan bisa berjalan jauh dengan sifatnya yang seperti itu. Jika ada yang terjadi padanya...",
  ui_story_5079_50790400_54_dialog_content = "Sebenarnya aku tidak khawatir tentang dia atau apa pun... tapi banyak orang yang melihat kita bersama sebelumnya.",
  ui_story_5079_50790400_55_dialog_content = "Jika sesuatu terjadi padanya, setiap orang di kota kecil ini akan mengejarku, karena aku orang luar...",
  ui_story_5079_50790400_56_dialog_content = "Hei Popo! Tunggu!",
  ui_story_5079_50790400_57_dialog_content = "Huh! Apa aku mengenalmu?",
  ui_story_5079_50790400_58_dialog_content = "Aku kebetulan juga akan pergi ke arah ini. Mau jalan-jalan bersama?",
  ui_story_5079_50790400_59_dialog_content = "Bukan!",
  ui_story_5079_50790400_60_dialog_content = "Meski... Jika kamu memohon padaku untuk mengizinkanmu berjalan bersamaku, mungkin aku akan mempertimbangkan ulang.",
  ui_story_5079_50790400_61_dialog_content = "Seperti yang saya katakan, saya hanya kebetulan menuju ke arah yang sama...",
  ui_story_5079_50790400_62_dialog_content = "Bagaimana kalau begini? Kamu berjalan bersama denganku, dan aku akan membantumu bertanya kepada Keluarga Ketchup tentang ayahmu.",
  ui_story_5079_50790400_63_dialog_content = "Kamu gadis yang cukup pintar, jadi saya yakin kamu akan membuat pilihan yang tepat.",
  ui_story_5079_50790400_64_dialog_content = "… Hmm…",
  ui_story_5079_50790400_65_dialog_content = "Baiklah, tapi kamu harus berjalan di belakangku sepanjang waktu!",
  ui_story_5079_50790400_66_dialog_content = "Dan jangan sampai tersesat! Aku tidak ingin mencarimu jika kamu tersesat!",
  ui_story_5079_50790400_67_dialog_content = "(Anak-anak benar-benar menyebalkan...)",
  ui_story_5079_50790400_68_dialog_content = "Baik, ayo pergi.",
  ui_story_5079_50790500_1_dialog_content = "Y-Ya... D-Disini kita! A-Ayo masuk ke dalam!",
  ui_story_5079_50790500_2_dialog_content = "Kamu baik-baik saja? Kamu banyak tergagap... Kamu tidak gugup, bukan?",
  ui_story_5079_50790500_3_dialog_content = "T-Tentu saja tidak! A-Aku hanya sedikit bersemangat, itu saja.",
  ui_story_5079_50790500_4_dialog_content = "Bagaimanapun, kita akan bertemu dengan kepala Keluarga Ketchup... S-saya kebetulan sangat menghormatinya!",
  ui_story_5079_50790500_5_dialog_content = "Tapi datang ke rumahnya tanpa diundang dan berpakaian seperti ini... K-Kamu pikir aku akan memberikan kesan buruk padanya?",
  ui_story_5079_50790500_6_dialog_content = "Kamu terlalu banyak khawatir untuk seseorang seumurmu, Popo.",
  ui_story_5079_50790500_7_dialog_content = "Tapi kamu akan baik-baik saja. Cukup berdiri di belakangku dan biarkan aku yang berbicara untukmu.",
  ui_story_5079_50790500_8_dialog_content = "Ah, saya lihat kita memiliki tamu dari jauh. Selamat datang, nona.",
  ui_story_5079_50790500_9_dialog_content = "Aku lihat kamu membawa seseorang... seorang kecil yang terlihat akrab.",
  ui_story_5079_50790500_10_dialog_content = "Harus kuakui, kalian berdua adalah pasangan yang cukup menarik. Katakan padaku, apa yang membawa kalian ke sini hari ini?",
  ui_story_5079_50790500_11_dialog_content = "Aku datang karena... Tunggu sebentar, apa kita pernah bertemu sebelumnya?",
  ui_story_5079_50790500_12_dialog_content = "Saya percaya Anda salah paham, Nyonya. Meskipun sejauh ini saya telah menyambut banyak tamu...",
  ui_story_5079_50790500_13_dialog_content = "Aku yakin aku pasti akan ingat seorang wanita muda yang cantik dan berwibawa seperti dirimu.",
  ui_story_5079_50790500_14_dialog_content = "I-Begitukah...",
  ui_story_5079_50790500_15_dialog_content = "(Aku tahu membeli pakaian ini adalah hal yang tepat untuk dilakukan! Saatnya mencoba peruntunganku sedikit...)",
  ui_story_5079_50790500_16_dialog_content = "*memandang*",
  ui_story_5079_50790500_17_dialog_content = "<size=30>Aku tahu, aku tahu! Aku sudah berjanji, sekarang berhentilah menatapku seperti itu!</size>",
  ui_story_5079_50790500_18_dialog_content = "Ahem... Alasan saya datang ke sini ada dua...",
  ui_story_5079_50790500_19_dialog_content = "Salah satu alasan tersebut adalah gadis ini mengklaim bahwa ayahnya telah meninggalkannya. Kami menduga bahwa keluargamu somehow terhubung dengan masalah ini, jadi kami datang untuk menanyakan.",
  ui_story_5079_50790500_20_dialog_content = "... Hei! Jangan terus terang begitu!",
  ui_story_5079_50790500_21_dialog_content = "Ini adalah kesalahpahaman yang cukup aneh.",
  ui_story_5079_50790500_22_dialog_content = "Apakah kamu maksudkan ayahmu belum juga menemukanmu, Popo?",
  ui_story_5079_50790500_23_dialog_content = "Menemukanku?",
  ui_story_5079_50790500_24_dialog_content = "Ya. Setelah mencari kamu di mana-mana, dia menyimpulkan bahwa kamu sudah pergi naik kereta, jadi dia membeli tiket untuk perjalanan ke luar berikutnya.",
  ui_story_5079_50790500_25_dialog_content = "Dan di sinilah kamu. Sebuah lelucon takdir yang menghibur, bukan begitu?",
  ui_story_5079_50790500_26_dialog_content = "Benarkah? Benarkah? Ayah hanya menutup toko hanya untuk mencariku?",
  ui_story_5079_50790500_27_dialog_content = "Tentu saja. Memangnya siapa lagi yang akan menjaga toko saat dia tidak ada?",
  ui_story_5079_50790500_28_dialog_content = "T-T-Tapi kemudian...",
  ui_story_5079_50790500_29_dialog_content = "Bagaimana saya bisa menemukannya? Siapa yang tahu sejauh mana dia naik kereta... Saya tidak akan pernah mencoba melarikan diri jika saya tahu ini akan terjadi...",
  ui_story_5079_50790500_30_dialog_content = "Jangan khawatir, Popo.",
  ui_story_5079_50790500_31_dialog_content = "Konduktor kereta ini adalah bagian dari Keluarga Ketchup. Aku akan menyuruhnya memberi tahu ayahmu untuk pulang secepat mungkin.",
  ui_story_5079_50790500_32_dialog_content = "Benarkah? Benarkah? Oh, terima kasih banyak!",
  ui_story_5079_50790500_33_dialog_content = "(Fiuh... Itu satu hal yang kurang perlu dikhawatirkan.)",
  ui_story_5079_50790500_34_dialog_content = "(Ayah Popo rela menutup bisnis yang telah susah payah dia bangun hanya untuk mencari putrinya.)",
  ui_story_5079_50790500_35_dialog_content = "(Jika itu ayahku, hm, dia mungkin akan merasa lega.)",
  ui_story_5079_50790500_36_dialog_content = "Itu mengingatkan saya, Ma'am! Gadis muda yang belum dewasa... Maksud saya wanita muda yang berpendidikan ini datang ke Folta dalam urusan penting!",
  ui_story_5079_50790500_37_dialog_content = "Hei, tidak ada yang memintamu untuk ikut campur...",
  ui_story_5079_50790500_38_dialog_content = "Dia perlu membeli banyak bahan berkualitas tinggi, jadi saya pikir saya harus membawanya untuk bertemu dengan Anda terlebih dahulu!",
  ui_story_5079_50790500_39_dialog_content = "Kamu pasti bisa membantunya, 'kan?",
  ui_story_5079_50790500_40_dialog_content = "(Oh... Apakah ini cara Popo berterima kasih padaku? Aku akan biarkan dia selesaikan omongannya...)",
  ui_story_5079_50790500_41_dialog_content = "(Selain itu... Aku bisa terbiasa dipanggil \"wanita bangsawan yang canggih.\")",
  ui_story_5079_50790500_42_dialog_content = "Terima kasih, Popo. Aku dengan senang hati akan mengatur sesuatu.",
  ui_story_5079_50790500_43_dialog_content = "Dengan kedudukan Keluarga Ketchup di Folta, saya bisa membuat setiap toko mengirimkan bahan-bahan terbaik mereka ke sini untuk pilihanmu.",
  ui_story_5079_50790500_44_dialog_content = "Setelah perjalanan yang begitu panjang, saya ragu kamu ingin berlarian di sekitar kota mencari mereka.",
  ui_story_5079_50790500_45_dialog_content = "Dan karena kamu cukup baik untuk membantu Popo kecil, saya bisa membantu kamu membelinya dengan harga terendah yang mungkin. Apakah itu memuaskan?",
  ui_story_5079_50790500_46_dialog_content = "Jika tidak terlalu banyak bertanya, maka ya, tentu saja!",
  ui_story_5079_50790500_47_dialog_content = "Saya akan meninggalkan daftar belanjaan saya dengan Anda, ahem, terima kasih banyak atas bantuan Anda.",
  ui_story_5079_50790500_48_dialog_content = "Tidak masalah. Aku akan mulai mengumpulkan barang-barang ini segera.",
  ui_story_5079_50790500_49_dialog_content = "Heheh!",
  ui_story_5079_50790500_50_dialog_content = "Kamu terlihat sangat sombong, Popo.",
  ui_story_5079_50790500_51_dialog_content = "Nah, saya baru saja membantu kamu mendapatkan kesepakatan yang manis. Semoga kamu siap untuk menebusnya padaku nanti!",
  ui_story_5079_50790500_52_dialog_content = "Saya cukup yakin saya bisa melakukannya sendiri... tidak apa-apa.",
  ui_story_5079_50790500_53_dialog_content = "Sebenarnya, kau benar-benar telah membantuku. Bagaimana kau ingin aku membalasmu?",
  ui_story_5079_50790500_54_dialog_content = "Bagaimana jika kamu menemani sampai saya menemukan ayah saya?",
  ui_story_5079_50790500_55_dialog_content = "Huh... Maksudmu mengasuhmu lebih banyak lagi? Tentu saja, nak.",
  ui_story_5079_50790500_56_dialog_content = "K-Kamu tidak \"menjaga\" saya! Kita saling membantu, oke?",
  ui_story_5079_50790500_57_dialog_content = "Dan saya telah membantu Anda secara besar-besaran, ingat? Anda setidaknya harus membuatnya seimbang!",
  ui_story_5079_50790500_58_dialog_content = "Lalu, biarkan aku membuat tawaran yang tak bisa kamu tolak untuk mempermanis kesepakatan ini.",
  ui_story_5079_50790500_59_dialog_content = "Ketika ayahmu kembali, aku akan meyakinkannya untuk berhenti membuatmu makan wortel.",
  ui_story_5079_50790500_60_dialog_content = "Saya cukup familiar dengan hal semacam ini, terutama ketika berbicara tentang membujuk dan mengganggu. Juga membantu bahwa saya memiliki tujuh puluh empat alasan mengapa wortel tidak seharusnya dimakan.",
  ui_story_5079_50790500_61_dialog_content = "Benarkah? Itu luar biasa! Sejauh ini saya hanya bisa menemukan tiga puluh tiga alasan saja...",
  ui_story_5079_50790500_62_dialog_content = "Jika kamu benar-benar berhasil melakukan ini... Aku akan menjadi pengikutmu seumur hidup!",
  ui_story_5079_50790500_63_dialog_content = "Maafkan saya, tapi nyonya rumah telah menyiapkan hidangan yang lezat untuk dua tamu terhormat kami. Silakan ikuti saya ke ruang makan, jika Anda mau.",
  ui_story_5079_50790500_64_dialog_content = "Ini akan menjadi kesempatan yang sempurna bagi Anda untuk mencicipi berbagai makanan khas kota kami juga, Nyonya. Jika Anda memiliki saran tentang makanan, mohon berbagi dengan kami dengan cara yang sopan.",
  ui_story_5079_50790500_65_dialog_content = "Jika Anda gagal menunjukkan tingkat penghormatan yang tepat kepada rakyat kami, terutama kepala Keluarga Ketchup...",
  ui_story_5079_50790500_66_dialog_content = "Saya mungkin harus mengambil tindakan terhadap Anda.",
  ui_story_5079_50790500_67_dialog_content = "Saya tidak berpikir kamu perlu pergi sejauh itu, bukan?",
  ui_story_5079_50790500_68_dialog_content = "Aku memilih untuk berbisnis dengan Keluarga Ketchup berdasarkan rasa saling percaya.",
  ui_story_5079_50790500_69_dialog_content = "Maka mohon maafkan saya atas insinuasi yang tidak berperasaan ini... Namun ada rasa tidak nyaman di dalam hati saya yang tidak bisa hilang...",
  ui_story_5079_50790500_70_dialog_content = "Bagaimanapun, silakan lewat sini.",
  ui_story_5079_50790500_71_dialog_content = "Akhirnya aku bisa makan! Selama ini aku penasaran rasanya makanan buatan Folta...",
  ui_story_5079_50790500_72_dialog_content = "Heheh!",
  ui_story_5079_50790500_73_dialog_content = "Kamu benar-benar tidak tahu cara menyembunyikan emosimu, ya? Ingat, kita akan makan malam dengan kepala keluarga Ketchup.",
  ui_story_5079_50790500_74_dialog_content = "Coba bersikap sedikit lebih seperti wanita bangsawan, maukah kamu?",
  ui_story_5079_50790500_75_dialog_content = "Sekarang kau juga menggurui aku? Suaramu sama menjengkelkannya seperti ayahku...",
  ui_story_5079_50790500_76_dialog_content = "Bagaimanapun, kamu tahu apa arti makan malam dengan Keluarga Ketchup, bukan?",
  ui_story_5079_50790500_77_dialog_content = "Ini berarti semuanya dibuat dengan tomat! Yang juga berarti tidak akan ada satu wortel pun yang berbau!",
  ui_story_5079_50790500_78_dialog_content = "Itu pasti sesuatu yang dinanti-nantikan, tapi... apakah aku benar-benar terdengar seperti ayahmu barusan?",
  ui_story_5079_50790500_79_dialog_content = "Benar. Dia selalu memberitahuku bagaimana bersikap di meja makan, meski aku tidak pernah mendengarkannya!",
  ui_story_5079_50790500_80_dialog_content = "Kamu seharusnya senang karena kita akhirnya bisa makan, jadi jangan berpikir berlebihan!",
  ui_story_5079_50790500_81_dialog_content = "Aku tahu, hanya saja...",
  ui_story_5079_50790500_82_dialog_content = "(Aku hanya tidak ingin berubah menjadi orang dewasa yang keras kepala seperti itu...)",
  ui_story_5079_50790500_83_dialog_content = "Mohon maaf jika hidangan tidak sehebat yang diharapkan. Koki kami telah membuat sebanyak mungkin secepat mungkin.",
  ui_story_5079_50790500_84_dialog_content = "Tidak perlu khawatir, semua hidangan merah ini cukup untuk membangkitkan nafsu makanku!",
  ui_story_5079_50790500_85_dialog_content = "Bisa kita makan sekarang? Bisa?",
  ui_story_5079_50790500_86_dialog_content = "Tolong bantu dirimu sendiri.",
  ui_story_5079_50790500_87_dialog_content = "Aku ingin mencoba bisque tomat terlebih dahulu! Hanya memikirkan rasa manis dan asamnya saja sudah membuat mulutku berair!",
  ui_story_5079_50790500_88_dialog_content = "Tunggu, ayo kita lakukan bersama! Tiga, dua, satu, ayo!",
  ui_story_5079_50790500_89_dialog_content = "Tolong jangan suruh aku melakukan sesuatu yang begitu membosankan...",
  ui_story_5079_50790500_90_dialog_content = "Ayo! Kumohon?",
  ui_story_5079_50790500_91_dialog_content = "Baik... Tiga, dua...",
  ui_story_5079_50790500_92_dialog_content = "Satu!",
  ui_story_5079_50790500_93_dialog_content = "*Sroot*",
  ui_story_5079_50790500_94_dialog_content = "...",
  ui_story_5079_50790500_95_dialog_content = "...",
  ui_story_5079_50790500_96_dialog_content = "<size=45>Pfffffffft!</size>",
  ui_story_5079_50790500_97_dialog_content = "Ini diracuni! Supnya diracuni! Ada yang mencoba membunuh kita!",
  ui_story_5079_50790500_98_dialog_content = "Ini benar-benar tidak dapat diterima! Apakah orang-orangmu melakukan ini dengan sengaja?",
  ui_story_5079_50790500_99_dialog_content = "Saya menolak untuk percaya bahwa masakan Keluarga Ketchup itu tidak enak sampai-sampai tidak bisa dimakan.",
  ui_story_5079_50790500_100_dialog_content = "Apakah Anda yakin Anda berdua tidak bereaksi berlebihan?",
  ui_story_5079_50790500_101_dialog_content = "Ini bukan masalah selera sama sekali! Kenapa kalian malah memasukkan wortel ke dalam sup tomat?",
  ui_story_5079_50790500_102_dialog_content = "Wortel? Mustahil. Kami tidak menyimpan bahan seperti itu di lemari makanan kami.",
  ui_story_5079_50790500_103_dialog_content = "Saya juga saksi di sini! Coba sendiri, Nyonya!",
  ui_story_5079_50790500_104_dialog_content = "...",
  ui_story_5079_50790500_105_dialog_content = "Baiklah, kalau begitu...",
  ui_story_5079_50790500_106_dialog_content = "*menyesap*",
  ui_story_5079_50790500_107_dialog_content = "...",
  ui_story_5079_50790500_108_dialog_content = "Mohon terima permintaan maaf saya yang tulus. Ini bukan hanya sup tomat dengan wortel di dalamnya.",
  ui_story_5079_50790500_109_dialog_content = "Faktanya, sup ini rasanya seolah-olah dibuat sepenuhnya dari wortel.",
  ui_story_5079_50790500_110_dialog_content = "<color=#e8d9bb>Blegh! Blegh!</color>",
  ui_story_5079_50790500_111_dialog_content = "Suara apa itu?",
  ui_story_5079_50790500_112_dialog_content = "Sepertinya ada keributan besar di luar...",
  ui_story_5079_50790500_113_dialog_content = "...",
  ui_story_5079_50790500_114_dialog_content = "...",
  ui_story_5079_50790500_115_dialog_content = "...",
  ui_story_5079_50790500_116_dialog_content = "Kenapa...",
  ui_story_5079_50790500_117_dialog_content = "<size=50>Mengapa semua rasanya seperti wortel sekarang?</size>",
  ui_story_5079_50790601_1_dialog_content = "Jelaskan situasi saat ini.",
  ui_story_5079_50790601_2_dialog_content = "Ada sedikit... atau lebih tepatnya gangguan parah di kota ini...",
  ui_story_5079_50790601_3_dialog_content = "Tiba-tiba, dan untuk alasan yang masih belum diketahui, semua makanan di Folta sekarang rasanya seperti wortel—bahkan batu dan debu pun tidak luput.",
  ui_story_5079_50790601_4_dialog_content = "Apakah kita memiliki petunjuk tentang fenomena ini?",
  ui_story_5079_50790601_5_dialog_content = "Sebagian besar penduduk kota masih dalam keadaan panik, membuatnya sulit untuk mendapatkan informasi yang berarti.",
  ui_story_5079_50790601_6_dialog_content = "Namun, beberapa rumor mulai muncul. Sayangnya... menyebutkannya di sini akan sedikit tidak nyaman.",
  ui_story_5079_50790601_7_dialog_content = "Sudahlah itu, tolong bagikan hasil temuanmu dengan kami.",
  ui_story_5079_50790601_8_dialog_content = "Beberapa orang percaya bahwa ini adalah pekerjaan dari toko wortel. Lagipula, itu adalah satu-satunya toko yang menjual wortel di sini di Folta.",
  ui_story_5079_50790601_9_dialog_content = "Untuk memperburuk keadaan, toko ini sedang tutup dan pemiliknya tidak terlihat di mana-mana.",
  ui_story_5079_50790601_10_dialog_content = "Sejumlah penduduk merasa ini terlalu aneh untuk menjadi kebetulan, jadi mereka membentuk tim pencari dan mencoba mencari pemilik toko dan keluarganya untuk mencari kebenaran di balik semua ini.",
  ui_story_5079_50790601_11_dialog_content = "Lalu tampaknya kita harus menemukan ayah Popo sebelum mereka... Katakan padaku, apakah kita telah menemukan sesuatu yang berkaitan dengan keberadaannya?",
  ui_story_5079_50790601_12_dialog_content = "Belum, Nona. Saya sudah mencoba menghubungi konduktor.",
  ui_story_5079_50790601_13_dialog_content = "Maafkan aku... Tetapi dia masih menolak untuk menerima pesan apapun darimu.",
  ui_story_5079_50790601_14_dialog_content = "Sudah hampir satu abad, dan dia masih mengabaikanku?",
  ui_story_5079_50790601_15_dialog_content = "Dia masih saja menjengkelkan seperti biasanya, sudah kuduga.",
  ui_story_5079_50790601_16_dialog_content = "Maka satu-satunya petunjuk yang mungkin kita miliki sekarang...",
  ui_story_5079_50790601_17_dialog_content = "Hah? Aku tidak tahu apa yang terjadi, tapi sumpah aku tidak melakukan apa-apa!",
  ui_story_5079_50790601_18_dialog_content = "Anda baru saja melihatnya, Nyonya. Bahkan satu gigitan wortel saja sudah terlalu banyak bagiku!",
  ui_story_5079_50790601_19_dialog_content = "Jadi, mengapa saya harus berusaha keras untuk membuat semua makanan di kota ini rasanya seperti mereka?",
  ui_story_5079_50790601_20_dialog_content = "Saya bisa membuktikan ceritanya. Popo bersama saya sepanjang waktu dan tidak memiliki waktu untuk melakukan hal seperti itu.",
  ui_story_5079_50790601_21_dialog_content = "Tenang saja, Popo, aku tidak meragukanmu.",
  ui_story_5079_50790601_22_dialog_content = "Ayahmu, di sisi lain... Maafkan aku, tapi—",
  ui_story_5079_50790601_23_dialog_content = "Ayahku adalah pedagang yang jujur sempurna!",
  ui_story_5079_50790601_24_dialog_content = "Lagi pula, dia sedang mencari saya sekarang karena dia pikir saya kabur dari rumah. Dia tidak akan pernah melakukan sesuatu yang seburuk ini!",
  ui_story_5079_50790601_25_dialog_content = "Namun...",
  ui_story_5079_50790601_26_dialog_content = "Tak usah diributkan lagi. Saya sepenuhnya menyadari situasi ayahnya.",
  ui_story_5079_50790601_27_dialog_content = "Meragukan dia berarti meragukan kebenaran informasi saya sendiri. Apakah kamu memiliki petunjuk lain?",
  ui_story_5079_50790601_28_dialog_content = "Jika dia sepolos yang kamu percayai, maka hanya ada satu kemungkinan lain...",
  ui_story_5079_50790601_29_dialog_content = "Laporan kami menunjukkan bahwa hanya ada satu orang asing yang mengunjungi Folta hari ini dan kedatangannya sebagian besar bertepatan dengan kejadian aneh di kota kami.",
  ui_story_5079_50790601_30_dialog_content = "Beberapa penduduk sangat percaya bahwa orang asing ini memiliki jawaban yang mereka cari.",
  ui_story_5079_50790601_31_dialog_content = "...",
  ui_story_5079_50790601_32_dialog_content = "...",
  ui_story_5079_50790601_33_dialog_content = "Tunggu, kenapa kamu menatapku seperti itu?",
  ui_story_5079_50790601_34_dialog_content = "Benda di belakangmu itu tampaknya mengandung kekuatan yang hebat.",
  ui_story_5079_50790601_35_dialog_content = "Mohon maafkan saya... May Biar aku periksa lebih dekat agar aku bisa May membebaskanmu dari kecurigaan?",
  ui_story_5079_50790601_36_dialog_content = "!",
  ui_story_5079_50790601_37_dialog_content = "Jangan berani-berani mendekati Hunting Stone milikku.",
  ui_story_5079_50790601_38_dialog_content = "Sudah kubilang, aku datang ke Folta untuk membeli bahan-bahan untuk pesta. Bagaimana mungkin membuat segalanya berasa seperti wortel bisa menguntungkan saya sama sekali?",
  ui_story_5079_50790601_39_dialog_content = "Kamu harus memaafkan ketidaksopananku... Tapi kebenaran hanya akan terungkap melalui pemeriksaan yang teliti.",
  ui_story_5079_50790601_40_dialog_content = "Humph, apakah ini yang disebut \"keramahan\" oleh Keluarga Ketchup?",
  ui_story_5079_50790601_41_dialog_content = "Jika demikian, biarkan saya memperingatkan Anda: Saya juga bukan seseorang yang ingin Anda jengkelkan!",
  ui_story_5079_50790700_1_dialog_content = "Situasi menjadi sedikit kacau tadi. Tapi menuduhku tanpa bukti dan bahkan menyerangku? Aku tidak bisa menerimanya lagi.",
  ui_story_5079_50790700_2_dialog_content = "Orang itu tidak menyakitimu, bukan? Hunting Stone?",
  ui_story_5079_50790700_3_dialog_content = "...",
  ui_story_5079_50790700_4_dialog_content = "<color=#e8d9bb>*langkah kaki*</color>",
  ui_story_5079_50790700_5_dialog_content = "Mereka cepat mengejar, bukan? Siap-siap, Hunting Stone!",
  ui_story_5079_50790700_6_dialog_content = "Ahh!",
  ui_story_5079_50790700_7_dialog_content = "Oh, ini hanya Popo. Kamu bisa santai sekarang, Hunting Stone.",
  ui_story_5079_50790700_8_dialog_content = "...",
  ui_story_5079_50790700_9_dialog_content = "Apa... Apa yang telah kau lakukan?",
  ui_story_5079_50790700_10_dialog_content = "Aku tidak bermaksud meninggalkanmu, tapi orang-orang itu—",
  ui_story_5079_50790700_11_dialog_content = "Kamu tadi sangat keren!",
  ui_story_5079_50790700_12_dialog_content = "Ha?",
  ui_story_5079_50790700_13_dialog_content = "Kamu menghadapi seluruh Keluarga Ketchup sendirian! Saya bahkan tidak bisa membayangkan melakukan hal seperti itu!",
  ui_story_5079_50790700_14_dialog_content = "Terutama penasihat itu! Saya selalu ketakutan dengan orang itu!",
  ui_story_5079_50790700_15_dialog_content = "Oh, maksudmu pria yang anehnya sopan dan selalu minta maaf?",
  ui_story_5079_50790700_16_dialog_content = "Dia tidak begitu sopan saat mengancam kami sebelumnya... Tapi aku tidak menyangka kami akan benar-benar bertarung nantinya.",
  ui_story_5079_50790700_17_dialog_content = "Meski begitu, rasanya menyenangkan bisa menempatkan orang aneh yang selalu minta maaf itu pada tempatnya. Saya merasa pernah melakukan hal serupa sebelumnya...",
  ui_story_5079_50790700_18_dialog_content = "Apa yang terjadi dengan diriku hari ini? Rasanya seperti di mana pun aku berbalik, aku terus merasa deja vu...",
  ui_story_5079_50790700_19_dialog_content = "Bisakah saya bertanya sesuatu? Kenapa kamu tidak mencoba menjelaskan dirimu pada mereka?",
  ui_story_5079_50790700_20_dialog_content = "Kami jelas tidak salah di sini, bahkan Keluarga Ketchup pun harus mendengarkan alasan! Kenapa malah memilih berkelahi tanpa arti dengan mereka?",
  ui_story_5079_50790700_21_dialog_content = "Kamu bilang itu tidak ada artinya, menurutmu jujur saja, menjelaskan hal-hal itu akan membuat perbedaan?",
  ui_story_5079_50790700_22_dialog_content = "Aku sudah mencoba melakukan itu sejak aku masih anak-anak... tapi tidak ada yang pernah mendengarkan. Itulah mengapa aku tidak mau repot lagi.",
  ui_story_5079_50790700_23_dialog_content = "T-Tapi... Saya mendengar seseorang mengatakan bahwa Keluarga Ketchup sudah mengeluarkan perintah penangkapanmu!",
  ui_story_5079_50790700_24_dialog_content = "Tangkap?",
  ui_story_5079_50790700_25_dialog_content = "Meskipun kamu terlihat sangat keren saat bertarung melawan Keluarga Ketchup... Semakin keras kamu melawan, semakin mereka akan mencurigaimu.",
  ui_story_5079_50790700_26_dialog_content = "Bagaimana kalau begini? Kenapa kamu tidak memberi tahu mereka bahwa Hunting Stone hanya menyerang karena ingin melindungimu, dan bahwa kamu sebenarnya tidak ingin bertarung?",
  ui_story_5079_50790700_27_dialog_content = "...",
  ui_story_5079_50790700_28_dialog_content = "Memang benar bahwa Hunting Stone memiliki kehendak sendiri, dan kekuatanku berasal darinya...",
  ui_story_5079_50790700_29_dialog_content = "Tapi semua yang baru saja terjadi adalah salahku. Saya tidak akan menyalahkan siapa pun atau apa pun.",
  ui_story_5079_50790700_30_dialog_content = "!",
  ui_story_5079_50790700_31_dialog_content = "Oh... Begitu. Kamu pasti sangat akrab dengan Hunting Stone. Jujur saja, aku sedikit iri.",
  ui_story_5079_50790700_32_dialog_content = "... Teman? Anda tidak bisa lebih salah.",
  ui_story_5079_50790700_33_dialog_content = "Mungkin sedikit membantu dalam pertarungan, tetapi dalam kehidupan sehari-hari, itu hanya membawa masalah yang tidak perlu bagi saya.",
  ui_story_5079_50790700_34_dialog_content = "Siapa yang mau makhluk aneh ini mengikuti mereka sepanjang waktu, atau menyebutnya \"teman\" dalam hal ini?",
  ui_story_5079_50790700_35_dialog_content = "Wow... Itu terdengar seperti teman yang paling setia menurutku! Seseorang yang selalu ada di sisimu dan tidak pernah meninggalkanmu!",
  ui_story_5079_50790700_36_dialog_content = "Oke, sekarang aku sangat cemburu!",
  ui_story_5079_50790700_37_dialog_content = "Tidak pernahkah kamu mendengarkan apa yang orang lain katakan kepada kamu?",
  ui_story_5079_50790700_38_dialog_content = "Ini bahkan juga mengerti kamu! Kapanpun kamu siap untuk bertarung, ini langsung beraksi!",
  ui_story_5079_50790700_39_dialog_content = "Jika kamu tidak menginginkannya, kenapa tidak kau biarkan aku mengambilnya saja?",
  ui_story_5079_50790700_40_dialog_content = "Uh... Atau mungkin tidak? Lagi pula, aku tidak ingin merusak persahabatan kalian!",
  ui_story_5079_50790700_41_dialog_content = "Jika kamu tidak bisa memberikannya padaku, bisakah aku meminjamnya suatu saat? Tolong? Tolong?",
  ui_story_5079_50790700_42_dialog_content = "...",
  ui_story_5079_50790700_43_dialog_content = "...",
  ui_story_5079_50790700_44_dialog_content = "Kamu melihatnya dalam pertempuran barusan... Bukankah kamu takut itu bisa melukaimu?",
  ui_story_5079_50790700_45_dialog_content = "Ha?",
  ui_story_5079_50790700_46_dialog_content = "Lagipula, kita baru saling kenal kurang dari sehari. Mengapa kamu begitu bersedia mempercayaiku?",
  ui_story_5079_50790700_47_dialog_content = "Pernahkah terlintas di pikiranmu bahwa aku menghindari penyelidikan Keluarga Ketchup karena sebenarnya aku bersalah?",
  ui_story_5079_50790700_48_dialog_content = "Yah... Aku rasa itu karena kita sudah bersama selama ini.",
  ui_story_5079_50790700_49_dialog_content = "Saya yakin kamu adalah orang yang baik! Indra keenamku memberitahuku begitu!",
  ui_story_5079_50790700_50_dialog_content = "Itu bukan semuanya, 'kan? Maaf, Popo, tapi kamu tidak terlalu pandai menyembunyikan pikiran dan perasaanmu.",
  ui_story_5079_50790700_51_dialog_content = "Untuk kamu mempercayai saya begitu tanpa syarat, berarti kamu sudah memiliki tersangka lain dalam pikiranmu, bukan?",
  ui_story_5079_50790700_52_dialog_content = "Itu... Itu hanya sebagian alasan, tapi ya!",
  ui_story_5079_50790700_53_dialog_content = "Sebenarnya... Saya rasa mungkin ayahku yang bertanggung jawab atas semua ini.",
  ui_story_5079_50790700_54_dialog_content = "Wortel adalah alasan kami terlibat dalam pertengkaran besar. Mungkin dia mencoba membuatku menyukai wortel dengan membuat segala sesuatu di kota ini rasanya seperti wortel?",
  ui_story_5079_50790700_55_dialog_content = "Tapi apakah dia benar-benar akan sejauh ini hanya untuk membuatku makan wortel? Jika iya, dia benar-benar berlebihan!",
  ui_story_5079_50790700_56_dialog_content = "Berhenti pura-pura. Dari ekspresimu, aku bisa tahu bahwa kamu sebenarnya tidak marah padanya.",
  ui_story_5079_50790700_57_dialog_content = "Kamu sama sekali tidak membenci ayahmu. Kamu khawatir padanya—kamu khawatir dia telah menjadi sasaran kemarahan publik.",
  ui_story_5079_50790700_58_dialog_content = "Apa yang kamu bicarakan? Saya tidak peduli tentang semua itu. Saya hanya merasa sebagian harus disalahkan untuk pertengkaran kita.",
  ui_story_5079_50790700_59_dialog_content = "Karena sifatku, aku selalu membuat ayahku jengkel dan marah...",
  ui_story_5079_50790700_60_dialog_content = "Itulah sebabnya aku merasa seharusnya aku melakukan sesuatu untuknya... Jelas, itu tidak berarti aku akan minta maaf kepadanya atau apa pun!",
  ui_story_5079_50790700_61_dialog_content = "Saran saja: menjadi terlalu keras kepala hanya akan membuat segalanya menjadi rumit.",
  ui_story_5079_50790700_62_dialog_content = "Huh? Tapi kamu juga cukup keras kepala, bukan?",
  ui_story_5079_50790700_63_dialog_content = "Sekarang setelah saya pikirkan, mungkin kamu dan ayahmu juga memiliki kesalahpahaman yang serupa?",
  ui_story_5079_50790700_64_dialog_content = "Kamu bisa belajar satu atau dua hal dariku, tahu! Seperti diam-diam melakukan sesuatu yang baik untuknya...",
  ui_story_5079_50790700_65_dialog_content = "Saya yakin dia pasti suka itu.",
  ui_story_5079_50790700_66_dialog_content = "Sesuatu yang dia sangat sukai, huh? Huh, aku tidak pikir aku bisa mencapai sesuatu seperti itu dalam hidupku.",
  ui_story_5079_50790700_67_dialog_content = "Makan wortel, menyingkirkan Hunting Stone, atau menjadi putri anggun yang selalu dia inginkan... Urgh, mari kita berhenti membicarakan masalahku sendiri.",
  ui_story_5079_50790700_68_dialog_content = "Saat ini, saya bisa lebih atau kurang menjamin... bahwa ayahmu bukanlah penyebab kekacauan ini.",
  ui_story_5079_50790700_69_dialog_content = "Hah? Benarkah? Jadi firasatku sepenuhnya salah? Tunggu, kau bukan cuma mencoba mengalihkan topik, bukan?",
  ui_story_5079_50790700_70_dialog_content = "Masa laluku tidak terlalu penting lagi, tetapi keluargamu adalah sesuatu yang sangat dekat dan berharga bagimu.",
  ui_story_5079_50790700_71_dialog_content = "Jadi, lupakan saja masalahku untuk sekarang. Sedangkan ayahmu, aku cukup yakin aku sudah memahami semuanya—",
  ui_story_5079_50790700_72_dialog_content = "Jika sekarang semua rasanya seperti wortel, itu hanya merugikan kepentingan pedagang wortel satu-satunya di kota ini. Sudah paham maksudnya?",
  ui_story_5079_50790700_73_dialog_content = "K-kurasa begitu! Hmm... Kalau memang begitu...",
  ui_story_5079_50790700_74_dialog_content = "Lalu wortel benar-benar tidak berguna sekarang, karena orang bisa makan apa saja dan masih bisa merasakannya!",
  ui_story_5079_50790700_75_dialog_content = "Bingo. Tidak masuk akal jika ayahmu melakukan sesuatu yang sangat merugikan bisnisnya.",
  ui_story_5079_50790700_76_dialog_content = "Ohhh! Itu... Itu sangat masuk akal! Kamu bukan juga detektif, bukan?",
  ui_story_5079_50790700_77_dialog_content = "Ini hanya pengamatan sederhana, itu saja. Kamu juga cukup baik dalam menganalisis fakta, Popo. Ada yang memberitahuku...",
  ui_story_5079_50790700_78_dialog_content = "Mungkin kita bisa bekerja sama dengan cukup baik.",
  ui_story_5079_50790700_79_dialog_content = "Heeheehee, aku sudah mengetahui itu sejak lama!",
  ui_story_5079_50790700_80_dialog_content = "(Apakah itulah alasan saya begitu bersedia untuk tetap di sini? Karena cara berpikir kita sangat mirip?)",
  ui_story_5079_50790700_81_dialog_content = "(Kepribadian keras kepala kita dan hubungan kita dengan ayah kita juga cukup mirip...)",
  ui_story_5079_50790700_82_dialog_content = "(Bisakah jadi dia adalah salinan tepat dari diriku saat aku masih kecil? Tidak, itu tidak mungkin benar... Aku yakin aku sedikit lebih dewasa darinya.)",
  ui_story_5079_50790700_83_dialog_content = "Lalu... Bisakah kamu membantu saya dengan sesuatu yang lain?",
  ui_story_5079_50790700_84_dialog_content = "Tentu saja! Lagipula, itu yang akan dilakukan oleh orang dewasa... ehem, maksudku ya, ada apa?",
  ui_story_5079_50790700_85_dialog_content = "Aku... Aku rasa aku bisa mencium sumber rasa wortelnya! Seolah-olah itu terhubung denganku entah bagaimana!",
  ui_story_5079_50790700_86_dialog_content = "Atau mungkin karena saya sangat membenci wortel sehingga saya lebih sensitif terhadap mereka daripada orang lain.",
  ui_story_5079_50790700_87_dialog_content = "Aromanya... Sepertinya berasal dari <color=#FFB400>Hutan Cream</color>. Tempat itu jauh dari sini, dan ada gua yang didedikasikan untuk Dewa Makanan di sana.",
  ui_story_5079_50790700_88_dialog_content = "Kamu bisa mencium sesuatu yang berasal dari gua hutan berjarak mil dari sini?",
  ui_story_5079_50790700_89_dialog_content = "Tidak! Tapi dulu ayahku sering mengajakku bermain di gua itu. Jika aku harus menebak, dia pasti naik kereta untuk mencariku di gua itu!",
  ui_story_5079_50790700_90_dialog_content = "Jika itu tempat dia sekarang, dan sesuatu yang menyeramkan benar-benar terjadi di hutan...",
  ui_story_5079_50790700_91_dialog_content = "Kamu tidak perlu terus mencoba menyembunyikannya. Jelas bahwa kamu benar-benar khawatir tentang ayahmu.",
  ui_story_5079_50790700_92_dialog_content = "Baiklah, aku memang khawatir! Dan itulah sebabnya... Aku ingin meminjam Hunting Stone-mu dan pergi menyelamatkannya!",
  ui_story_5079_50790700_93_dialog_content = "Kamu pikir kamu akan baik-baik saja sendiri?",
  ui_story_5079_50790700_94_dialog_content = "Eh...",
  ui_story_5079_50790700_95_dialog_content = "Akui saja, kamu sedang menunggu aku menawarkan bantuan.",
  ui_story_5079_50790700_96_dialog_content = "Kamu satu-satunya yang bisa aku andalkan saat ini... Tapi membantuku juga menguntungkanmu!",
  ui_story_5079_50790700_97_dialog_content = "Oh? Kok bisa?",
  ui_story_5079_50790700_98_dialog_content = "Membantu saya menemukan ayah saya pasti tidak akan menjadi masalah bagi kamu, dan begitu kita menemukannya, saya yakin dia akan melakukan segala yang dia bisa untuk membersihkan nama baikmu.",
  ui_story_5079_50790700_99_dialog_content = "Dan jika kamu berhasil menghilangkan rasa wortel untuk kota ini, mengumpulkan bahan-bahanmu hanya akan semakin mudah, bukan?",
  ui_story_5079_50790700_100_dialog_content = "Sudah kuduga...",
  ui_story_5079_50790700_101_dialog_content = "Hah? Menduga apa?",
  ui_story_5079_50790700_102_dialog_content = "Bukan apa-apa. Hanya saja, terkadang kau membuatku terkesan, itu saja.",
  ui_story_5079_50790700_103_dialog_content = "Aku akan membantumu, tapi bukan karena kamu membujukku atau apa pun. Kebetulan saja pikiran kita sejalan.",
  ui_story_5079_50790700_104_dialog_content = "Benarkah? Benarkah? Maka mungkin saya juga memiliki potensi detektif di dalam diri saya!",
  ui_story_5079_50790700_105_dialog_content = "Ini pasti bakat yang layak dilatih. Mungkin suatu hari nanti aku akan memperkenalkanmu pada beberapa aturan favoritku.",
  ui_story_5079_50790700_106_dialog_content = "Aturan?",
  ui_story_5079_50790700_107_dialog_content = "Tertarik? Akan kuberi tahu semua tentang mereka saat kita punya waktu luang, tapi sekarang...",
  ui_story_5079_50790700_108_dialog_content = "Ayo pergi ke hutan!",
  ui_story_5079_50790700_109_dialog_content = "Baiklah! Ayo pergi!",
  ui_story_5079_50790801_1_dialog_content = "Aduh... Bau di luar sini mengerikan. Pasti berasal dari satu tempat...",
  ui_story_5079_50790801_2_dialog_content = "Mungkinkah ini gua dari Dewa Makanan?",
  ui_story_5079_50790801_3_dialog_content = "Ngomong-ngomong, menurutmu dewa ini terlibat dalam hal ini?",
  ui_story_5079_50790801_4_dialog_content = "Lebih baik tidak membicarakannya. Lagipula, Dewa Makanan adalah dewa yang paling dihormati oleh Folta.",
  ui_story_5079_50790801_5_dialog_content = "Kami membuat persembahan secara rutin, dan sebagai gantinya, Dewa Makanan mengabulkan keinginan tulus kami.",
  ui_story_5079_50790801_6_dialog_content = "Apakah itu sebabnya kamu mencurigai ayahmu sebelumnya? Karena kamu pikir dia mungkin telah pergi ke Dewa Makanan dan berharap agar semua rasanya seperti wortel?",
  ui_story_5079_50790801_7_dialog_content = "Eh...",
  ui_story_5079_50790801_8_dialog_content = "Bisakah Dewa Makanan ini benar-benar membuat keinginan seperti itu menjadi kenyataan?",
  ui_story_5079_50790801_9_dialog_content = "Tentu saja! Keluarga Ketchup menerima Buku Masak Hitam suci mereka dari Dewa Makanan.",
  ui_story_5079_50790801_10_dialog_content = "Keluarga itu telah berkuasa selama beberapa generasi semua berkat pengetahuan yang ditemukan di buku itu.",
  ui_story_5079_50790801_11_dialog_content = "Tiba-tiba ada yang terasa aneh...",
  ui_story_5079_50790801_12_dialog_content = "Jangan bilang ada seseorang yang membawa koper putih berisi bahan-bahan dan tinggal dekat dengan kepala Keluarga Ketchup.",
  ui_story_5079_50790801_13_dialog_content = "A... Aku pikir begitu? Tunggu, apakah ini berarti kamu sudah menyelidiki Keluarga Ketchup?",
  ui_story_5079_50790801_14_dialog_content = "Sama sekali tidak, tapi ada sesuatu tentang seluruh Keluarga Ketchup yang membuatku merasa... bernostalgia?",
  ui_story_5079_50790801_15_dialog_content = "Sekarang, itu tidak penting... Yang penting adalah menemukan cara untuk sampai ke hutan itu.",
  ui_story_5079_50790801_16_dialog_content = "Cara tercepat ke Cream Forest adalah dengan kereta, tapi...",
  ui_story_5079_50790801_17_dialog_content = "Tidak ada tanda-tanda mereka di sini juga? Kalian, cari di area itu.",
  ui_story_5079_50790801_18_dialog_content = "Siap, Pak!",
  ui_story_5079_50790801_19_dialog_content = "Jalan ini penuh dengan orang-orang yang sedang mencarimu sekarang...",
  ui_story_5079_50790801_20_dialog_content = "Urgh, sungguh menyebalkan. Jika misiku tidak begitu penting, aku akan menghajar orang aneh itu sekali lagi.",
  ui_story_5079_50790801_21_dialog_content = "Dengarkan, Popo. Jika mereka menemukanku dan aku tidak bisa menghindari pertarungan, kamu harus mengambil Hunting Stone dan langsung pergi ke hutan.",
  ui_story_5079_50790801_22_dialog_content = "Tidak mungkin, aku tidak bisa meninggalkanmu begitu saja! Kita adalah pasangan yang sempurna sekarang, ingat?",
  ui_story_5079_50790801_23_dialog_content = "Aku bahkan sudah memilihkan nama untuk kita! \"Tim Anti-Mimpi Wortel\"!",
  ui_story_5079_50790801_24_dialog_content = "Itukah yang terbaik yang bisa kamu hasilkan? Tidak bisakah kamu setidaknya mencoba untuk—",
  ui_story_5079_50790801_25_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5079_50790801_26_dialog_content = "Hati-hati, Popo!",
  ui_story_5079_50790801_27_dialog_content = "Ha?",
  ui_story_5079_50790801_28_dialog_content = "!",
  ui_story_5079_50790801_29_dialog_content = "Fiuh... Hampir saja.",
  ui_story_5079_50790801_30_dialog_content = "Nah sekarang... Bisakah seseorang memberi tahu saya mengapa banyak buah dan sayuran terbang di udara?",
  ui_story_5079_50790801_31_dialog_content = "Tetap di belakang Batu Berburu, Popo. Jangan terlalu dekat.",
  ui_story_5079_50790801_32_dialog_content = "O-Oke... Tapi apa yang terjadi di sini?",
  ui_story_5079_50790801_33_dialog_content = "...",
  ui_story_5079_50790801_34_dialog_content = "Berhenti! Apa yang menurutmu sedang kamu lakukan? Apakah kalian tikus tanah atau apa? Kenapa kalian mencoba merusak rasa lezat dari wortel?",
  ui_story_5079_50790801_35_dialog_content = "Kami hanya ingin semua rasanya sesuai dengan yang seharusnya!",
  ui_story_5079_50790801_36_dialog_content = "Cepat, taburkan lebih banyak garam dan soda kue di semua makanan! Semakin banyak semakin baik!",
  ui_story_5079_50790801_37_dialog_content = "Berhenti! Ini harus menjadi langkah selanjutnya alam dalam evolusi. Kami tidak akan membiarkan Anda mengganggu kehendak Dewa Makanan!",
  ui_story_5079_50790801_38_dialog_content = "Selain itu, kalian semua suka wortel, bukan? Kenapa berdiri melawan kami?",
  ui_story_5079_50790801_39_dialog_content = "A... Aku suka wortel dan semuanya, tapi aku tidak mau menghabiskan sisa hidupku hanya untuk makan mereka!",
  ui_story_5079_50790801_40_dialog_content = "Maafkan aku!",
  ui_story_5079_50790801_41_dialog_content = "Berhenti! Hentikan sekarang juga!",
  ui_story_5079_50790801_42_dialog_content = "Untuk dunia yang sempurna dan penuh wortel! Maju!",
  ui_story_5079_50790801_43_dialog_content = "Untuk Folta dan keragaman kuliner yang membanggakan! Taburkan!",
  ui_story_5079_50790801_44_dialog_content = "Wow... Seluruh kota sudah gila, bukan?",
  ui_story_5079_50790801_45_dialog_content = "Begitu banyak bangunan yang sudah hancur. Dengan keadaan seperti ini, Folta tidak akan menjadi kota yang sama lagi...",
  ui_story_5079_50790801_46_dialog_content = "Dan misiku akan seolah-olah gagal. Urgh, sungguh menyebalkan...",
  ui_story_5079_50790801_47_dialog_content = "Tidak ada yang lebih menggangguku selain kekacauan dan ketidakaturan seperti ini.",
  ui_story_5079_50790801_48_dialog_content = "...",
  ui_story_5079_50790801_49_dialog_content = "Lihat! Hunting Stone bergerak!",
  ui_story_5079_50790801_50_dialog_content = "Hei! Jangan menambah masalah bagi kami dengan ikut terlibat dalam pertarungan!",
  ui_story_5079_50790801_51_dialog_content = "Tunggu, sepertinya Hunting Stone mencoba membimbing kita ke arah ini.",
  ui_story_5079_50790801_52_dialog_content = "... Begitukah?",
  ui_story_5079_50790801_53_dialog_content = "Hei, jangan pikir aku akan mengikutimu kemana-mana hanya karena kamu ingin aku melakukannya.",
  ui_story_5079_50790801_54_dialog_content = "...",
  ui_story_5079_50790801_55_dialog_content = "Dan sekarang kamu tidak ingin aku mengejarmu? Jangan berpikir kamu bisa melarikan diri dariku, roda busuk!",
  ui_story_5079_50790801_56_dialog_content = "Ayo, Popo.",
  ui_story_5079_50790801_57_dialog_content = "<size=30>Kenapa dia jadi marah begitu? Aku rasa dia memang masih belum dewasa setelah semua ini...</size>",
  ui_story_5079_50790801_58_dialog_content = "Apa katamu barusan?",
  ui_story_5079_50790801_59_dialog_content = "Tidak ada apa-apa! Aku datang!",
  ui_story_5079_50790801_60_dialog_content = "Kamu ingin kita lewati di sini? Yah, ini adalah stasiun kereta.",
  ui_story_5079_50790801_61_dialog_content = "Kerja bagus, Hunting Stone.",
  ui_story_5079_50790801_62_dialog_content = "!",
  ui_story_5079_50790801_63_dialog_content = "Tapi, jangan terlalu congkak. Jika kamu akhirnya menakuti siapa pun di kereta lagi...",
  ui_story_5079_50790801_64_dialog_content = "Aku tarik kembali pujianku.",
  ui_story_5079_50790801_65_dialog_content = "Cepatlah, maukah kamu? Aku tidak ingin ketinggalan kereta dua kali dalam sehari!",
  ui_story_5079_50790801_66_dialog_content = "Hei, hati-hati...",
  ui_story_5079_50790801_67_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5079_50790801_68_dialog_content = "Yah, setidaknya dia berhasil bertemu dengan seseorang dua kali hari ini...",
  ui_story_5079_50790801_69_dialog_content = "Aduh…",
  ui_story_5079_50790801_70_dialog_content = "Hah? Apakah itu kamu, Popo?",
  ui_story_5079_50790801_71_dialog_content = "Oh, tidak!",
  ui_story_5079_50790801_72_dialog_content = "Setiap orang di Folta telah kehilangan akal mereka karena bisnis wortel ini.",
  ui_story_5079_50790801_73_dialog_content = "Sebagai putri dari satu-satunya pedagang wortel di kota ini, kamu harus lebih berhati-hati di sini.",
  ui_story_5079_50790801_74_dialog_content = "Uh... Oke, tapi...",
  ui_story_5079_50790801_75_dialog_content = "Di sini, saya akan mengantar Anda kembali.",
  ui_story_5079_50790801_76_dialog_content = "T-Tapi, aku harus mengejar kereta.",
  ui_story_5079_50790801_77_dialog_content = "Kereta? Maksudmu yang menuju Hutan Cream? Tunggu sebentar...",
  ui_story_5079_50790801_78_dialog_content = "Siapa orang itu di sebelahmu? Tunggu, roda itu... Aku pernah mendengar tentang itu sebelumnya! Apakah dia bisa jadi...",
  ui_story_5079_50790801_79_dialog_content = "Berhenti berdrama sudah. Ya, ini aku—penyusup jahat dari luar kota. Senang sekarang?",
  ui_story_5079_50790801_80_dialog_content = "Silakan naik kereta, Popo. Mulai sekarang, aku akan mengurusnya.",
  ui_story_5079_50790901_1_dialog_content = "T-Tunggu, berhenti! Kalian berdua!",
  ui_story_5079_50790901_2_dialog_content = "...",
  ui_story_5079_50790901_3_dialog_content = "...",
  ui_story_5079_50790901_4_dialog_content = "Aku kenal kamu! Kamu salah satu pelanggan tetap di toko kami, 'kan?",
  ui_story_5079_50790901_5_dialog_content = "Kamu suka wortel, itulah sebabnya kamu berjuang untuk menjaga agar segalanya tetap seperti sekarang! Benar? Benar?",
  ui_story_5079_50790901_6_dialog_content = "Ya... Aku tahu putri dari pedagang wortel kita yang hebat pasti akan mengerti.",
  ui_story_5079_50790901_7_dialog_content = "Lalu tidak ada alasan bagi kita untuk bertarung! Kamu tahu kenapa Keluarga Ketchup mengejar temanku ini, kan?",
  ui_story_5079_50790901_8_dialog_content = "... Apakah ini berarti rumor itu benar?",
  ui_story_5079_50790901_9_dialog_content = "Tidak tepatnya, tidak. Dia seorang detektif, dan dia sedang membantu saya mencari ayah saya sekarang ini.",
  ui_story_5079_50790901_10_dialog_content = "Ehem... Pactlock Holmes, siap melayani.",
  ui_story_5079_50790901_11_dialog_content = "Saya mengerti, saya mengerti. Apakah Anda seorang detektif sebenarnya atau tidak, kami berhutang budi kepada Anda!",
  ui_story_5079_50790901_12_dialog_content = "Sebenarnya, kami akan merasa terhormat jika Anda mau menjadi Suci Perempuan Wortel di organisasi kami!",
  ui_story_5079_50790901_13_dialog_content = "Tidak, terima kasih, tapi jika kamu benar-benar ingin mengungkapkan rasa terima kasihmu...",
  ui_story_5079_50790901_14_dialog_content = "Saya perlu naik kereta itu, tetapi saya tidak yakin bagaimana keadaan stasiun sekarang. Pikir kau bisa memberi saya perlindungan?",
  ui_story_5079_50790901_15_dialog_content = "Tentu saja! Jika tidak salah, orang yang menjual tiket kereta adalah bagian dari faksi musuh.",
  ui_story_5079_50790901_16_dialog_content = "Aku akan memastikan tidak ada satupun dari mereka yang bisa melihatmu!",
  ui_story_5079_50790901_17_dialog_content = "Di sana, sekarang kesempatanmu! Orang-orangku telah menarik perhatiannya, dan pertarungan seharusnya akan segera pecah...",
  ui_story_5079_50790901_18_dialog_content = "Menuju stasiun secepat mungkin!",
  ui_story_5079_50790901_19_dialog_content = "Terima kasih... Tapi mengapa kamu dan orang-orangmu bersedia berusaha sejauh ini hanya demi wortel?",
  ui_story_5079_50790901_20_dialog_content = "Tentu saja, ini karena kami bahkan tidak bisa mulai menggambarkan cinta kami pada wortel!",
  ui_story_5079_50790901_21_dialog_content = "Renyah dan manis, mereka memiliki tekstur yang luar biasa. Kamu bisa makan seratus wortel tanpa merasa bosan!",
  ui_story_5079_50790901_22_dialog_content = "Mereka juga merupakan sumber energi dan nutrisi yang sangat baik! Mereka dapat mendorong pertumbuhan dan perkembangan tulang, memperbaiki warna kulit, dan bahkan meredakan kelelahan mata!",
  ui_story_5079_50790901_23_dialog_content = "Tapi yang paling penting, sayuran luar biasa ini bisa mengatasi sembelit! Pasti para pembenci wortel sangat bingung dengan hal itu sekarang!",
  ui_story_5079_50790901_24_dialog_content = "... I-Begitukah?",
  ui_story_5079_50790901_25_dialog_content = "<size=30>Saya tidak tahu bahwa wortel memiliki begitu banyak kualitas baik.</size>",
  ui_story_5079_50790901_26_dialog_content = "Tapi kenapa kamu bertanya, Suci Perempuan Wortel? Kecuali... Ah, aku mengerti!",
  ui_story_5079_50790901_27_dialog_content = "Kamu sedang menguji kesetiaan saya pada wortel yang maha kuasa barusan, bukan? Tenang saja, Suci Perempuanku, saya akan selalu berada di sisi kebaikan wortel!",
  ui_story_5079_50790901_28_dialog_content = "Uh... Baiklah. Saya menghargai keputusan Anda.",
  ui_story_5079_50790901_29_dialog_content = "Kita harus pergi, Popo.",
  ui_story_5079_50790901_30_dialog_content = "Tunggu sebentar. Kamu juga akan pergi dengannya, Popo?",
  ui_story_5079_50790901_31_dialog_content = "Ya, tentu saja. Apakah itu masalah?",
  ui_story_5079_50790901_32_dialog_content = "Musuh-musuh kita mungkin memiliki mata di luar kota. Mereka mungkin tidak mengenali Suci Perempuan Carrot, tetapi mereka pasti akan mengenali kamu.",
  ui_story_5079_50790901_33_dialog_content = "Akan sangat berbahaya jika kamu pergi sendirian!",
  ui_story_5079_50790901_34_dialog_content = "Itu benar... Mungkin lebih baik untukmu tinggal di sini, Popo. Saya yakin pelanggan tetap toko Anda akan merawat Anda dengan baik.",
  ui_story_5079_50790901_35_dialog_content = "Tapi... Tapi aku ingin membantumu—",
  ui_story_5079_50790901_36_dialog_content = "Tenanglah, rakyatku dan aku akan melakukan segala yang kami bisa untuk melindungi Putri Popo.",
  ui_story_5079_50790901_37_dialog_content = "P-Putri?",
  ui_story_5079_50790901_38_dialog_content = "Kamu akan baik-baik saja, Popo. Ingat bagaimana kamu ingin meminjam Batu Berburu sebelumnya?",
  ui_story_5079_50790901_39_dialog_content = "Karena sangat menyukaimu, saya yakin dia tidak keberatan untuk tetap di sisimu. Dengan begitu, kamu tidak perlu khawatir, 'kan?",
  ui_story_5079_50790901_40_dialog_content = "Tapi lalu... Bukankah itu akan membuat segalanya menjadi lebih berbahaya untukmu?",
  ui_story_5079_50790901_41_dialog_content = "Saya? Apa kamu bercanda? Saya akan merasa jauh lebih baik tanpa Hunting Stone mengikutiku kemana-mana.",
  ui_story_5079_50790901_42_dialog_content = "Lagipula, kau sudah berteman dengannya sekarang, 'kan? Bahkan, kau bisa memahami perasaannya.",
  ui_story_5079_50790901_43_dialog_content = "Dan sepertinya dia benar-benar ingin tetap bersamamu...",
  ui_story_5079_50790901_44_dialog_content = "?",
  ui_story_5079_50790901_45_dialog_content = "Jika itu orang lain, pasti akan langsung kembali padaku.",
  ui_story_5079_50790901_46_dialog_content = "Apakah itu berarti... Aku istimewa?",
  ui_story_5079_50790901_47_dialog_content = "Sepertinya begitu. Jadi, tetap di sini dan tunggulah aku, oke?",
  ui_story_5079_50790901_48_dialog_content = "O-Baiklah... Aku akan melakukan persis seperti yang kamu minta! Benar kan, Hunting Stone?",
  ui_story_5079_50790901_49_dialog_content = "!",
  ui_story_5079_50790901_50_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790901_51_dialog_content = "Perhatian semua orang, tolong! Saya merasa terhormat untuk memperkenalkan kalian semua kepada Putri Popo, putri dari pedagang wortel terhormat di kota kita!",
  ui_story_5079_50790901_52_dialog_content = "Selamat datang!",
  ui_story_5079_50790901_53_dialog_content = "H-Halo, semuanya.",
  ui_story_5079_50790901_54_dialog_content = "Untuk membuatmu merasa lebih di rumah, aku telah menyiapkan kue spesial hanya untukmu! Silakan nikmati, Tuan Putri Popo!",
  ui_story_5079_50790901_55_dialog_content = "Silakan menikmati!",
  ui_story_5079_50790901_56_dialog_content = "Aku menghabiskan darah, keringat, dan air mata untuk memanggang kue ini untukmu! Aku bahkan menambahkan wortel tumbuk ke dalam krimnya...",
  ui_story_5079_50790901_57_dialog_content = "Tentu saja, saya hanya menggunakan wortel paling segar dan berkualitas tinggi dari toko ayahmu!",
  ui_story_5079_50790901_58_dialog_content = "Meskipun tampak agak berlebihan untuk membuat kue wortel untuk putri seorang pedagang wortel, saya harap kamu tetap menikmatinya.",
  ui_story_5079_50790901_59_dialog_content = "Kami juga berharap demikian!",
  ui_story_5079_50790901_60_dialog_content = "Wah...",
  ui_story_5079_50790901_61_dialog_content = "Silakan, putri.",
  ui_story_5079_50790901_62_dialog_content = "B-Bisakah aku memakannya di tempat yang tenang dan nyaman? Aku tidak terbiasa makan di depan banyak orang...",
  ui_story_5079_50790901_63_dialog_content = "Tentu saja, putri! Tapi jika boleh saya tanya, kenapa wajahmu tampak begitu pucat?",
  ui_story_5079_50790901_64_dialog_content = "Mungkinkah kue wortelku ini tidak sesuai dengan standar Anda?",
  ui_story_5079_50790901_65_dialog_content = "Tidak, bukan itu...",
  ui_story_5079_50790901_66_dialog_content = "Sekarang aku berpikir tentang itu, apakah ada yang pernah melihat putri pedagang wortel makan wortel sebelumnya?",
  ui_story_5079_50790901_67_dialog_content = "Tidak, tapi aku pernah melihatnya berdebat dengan ayahnya, dan sepertinya wortel adalah penyebab pertengkaran mereka...",
  ui_story_5079_50790901_68_dialog_content = "?",
  ui_story_5079_50790901_69_dialog_content = "A... Aku suka wortel! Kamu hanya belum pernah melihatku memakannya, itu saja... L-Lihat? M-Mereka enak...",
  ui_story_5079_50790901_70_dialog_content = "Argh... Blegh...",
  ui_story_5079_50790901_71_dialog_content = "Kamu serius mencubit hidungmu sekarang?",
  ui_story_5079_50790901_72_dialog_content = "K-Kamu tidak mengerti! Ini adalah cara terbaik untuk merasakan rasa wortel—",
  ui_story_5079_50790901_73_dialog_content = "<size=45>Pffffft—</size>",
  ui_story_5079_50790901_74_dialog_content = "...",
  ui_story_5079_50790901_75_dialog_content = "...",
  ui_story_5079_50790901_76_dialog_content = "...",
  ui_story_5079_50790901_77_dialog_content = "Kamu sama sekali tidak suka wortel, bukan? Kamu bukan putri kami, tapi musuh bebuyutan kami!",
  ui_story_5079_50790901_78_dialog_content = "Temanmu pergi ke Hutan Cream untuk mencari ayahmu, 'kan?",
  ui_story_5079_50790901_79_dialog_content = "Apa yang bisa dia lakukan di luar sana? Apakah mungkin dia mencoba menghancurkan surga indah kita yang penuh dengan wortel?",
  ui_story_5079_50790901_80_dialog_content = "Cepat! Kita harus menangkap Popo dan memaksanya untuk membawa kita ke wanita itu!",
  ui_story_5079_50790901_81_dialog_content = "Tidak... J-Jangan mendekat!",
  ui_story_5079_50790901_82_dialog_content = "Kamu akan membantuku, 'kan? Hunting Stone?",
  ui_story_5079_50790901_83_dialog_content = "!",
  ui_story_5079_50791001_1_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50791001_2_dialog_content = "Senang bertemu dengan Anda lagi, Nyonya. Kita telah tiba di Cream Forest, harap hati-hati saat Anda turun dari kereta.",
  ui_story_5079_50791001_3_dialog_content = "Oh... Kita sudah sampai? Itu lebih cepat dari yang saya duga...",
  ui_story_5079_50791001_4_dialog_content = "Situasi menjadi aneh dan membosankan tanpa adanya anak yang mengganggu atau roda yang selalu menempel.",
  ui_story_5079_50791001_5_dialog_content = "Sebenarnya itu adalah perjalanan yang cukup panjang, meskipun kamu menghabiskan sebagian besar waktu itu menatap keluar jendela.",
  ui_story_5079_50791001_6_dialog_content = "Apakah kerusuhan di Folta sumber stres Anda? Dapatkah saya membantu?",
  ui_story_5079_50791001_7_dialog_content = "Jadi kamu tahu apa yang sedang terjadi di kota?",
  ui_story_5079_50791001_8_dialog_content = "Tidak apa-apa, saya memiliki sesuatu yang lebih penting untuk ditanyakan. Apakah kamu melihat pemilik toko wortel akhir-akhir ini?",
  ui_story_5079_50791001_9_dialog_content = "Dari yang saya dengar, dia meninggalkan kota dengan kereta ini lebih awal hari ini.",
  ui_story_5079_50791001_10_dialog_content = "Pedagang wortel? Ya, benar. Dia turun di stasiun ini, dan saya percaya dia menyebutkan akan pergi ke gua Dewa Makanan.",
  ui_story_5079_50791001_11_dialog_content = "Benarkah? Sepertinya Popo benar selama ini.",
  ui_story_5079_50791001_12_dialog_content = "Aku percaya kamu juga memiliki kesan tentang dia.",
  ui_story_5079_50791001_13_dialog_content = "Setelah semua, kamu bertemu dengannya saat pertama kali tiba di Folta. Itu adalah pertemuan yang cukup menghibur, harus kuakui.",
  ui_story_5079_50791001_14_dialog_content = "Aku bertemu dengannya? Kamu maksud penumpang yang sangat rendah hati itu adalah ayah Popo?",
  ui_story_5079_50791001_15_dialog_content = "Urgh, semua kekacauan ini bisa dihindari jika saja aku menghentikannya naik kereta waktu itu...",
  ui_story_5079_50791001_16_dialog_content = "Sepertinya pertanyaan Anda telah dijawab. Harap ingat untuk membawa barang bawaan Anda saat turun dari kereta... Eh, tunggu sebentar.",
  ui_story_5079_50791001_17_dialog_content = "Maaf, tapi apakah kamu akhirnya berhasil menyingkirkan Hunting Stone?",
  ui_story_5079_50791001_18_dialog_content = "Tentu saja Anda tidak meninggalkannya di sudut gelap kota dan membiarkannya menderita dalam kesendirian yang menyedihkan, bukan?",
  ui_story_5079_50791001_19_dialog_content = "Kamu tidak perlu membuatnya terdengar begitu menyedihkan...",
  ui_story_5079_50791001_20_dialog_content = "Saya baru saja menitipkannya pada orang lain untuk sementara waktu.",
  ui_story_5079_50791001_21_dialog_content = "Maafkan aku, tadi aku tidak bisa menahan diri untuk membayangkan adegan tragedi dan kesepian yang sangat besar.",
  ui_story_5079_50791001_22_dialog_content = "Saya percaya tempat yang seharusnya adalah di sampingmu, dan hal yang sama juga berlaku untukmu.",
  ui_story_5079_50791001_23_dialog_content = "Aku benar-benar tidak membutuhkan pendapatmu tentang hubungan kita... Tapi terima kasih atas infonya.",
  ui_story_5079_50791001_24_dialog_content = "Jangan pikirkan itu. Saya senang bisa membantu Anda.",
  ui_story_5079_50791001_25_dialog_content = "Berbicara tentang itu, kepala Keluarga Ketchup juga mencoba menghubungi kamu tentang ayah Popo.",
  ui_story_5079_50791001_26_dialog_content = "Tapi kamu menolak untuk menjawabnya... Awalnya, aku pikir kamu adalah orang yang tidak berhati, tapi ternyata kamu sebenarnya cukup berhati hangat.",
  ui_story_5079_50791001_27_dialog_content = "Jika permintaan itu dari Anda, penumpang terkasih saya, saya akan berusaha sekuat tenaga untuk membantu Anda.",
  ui_story_5079_50791001_28_dialog_content = "Tapi aku menolak untuk berurusan dengan wanita gila itu dalam kapasitas apa pun. Aku lebih memilih menghabiskan seluruh keabadian dalam kesendirian yang dingin daripada berhubungan kembali dengannya!",
  ui_story_5079_50791001_29_dialog_content = "A-Aku mengerti, maaf jika aku membuatmu kesal. Aku akan turun dari kereta segera.",
  ui_story_5079_50791001_30_dialog_content = "Aroma wortel semakin kuat dan kuat...",
  ui_story_5079_50791001_31_dialog_content = "Sumber masalahnya seharusnya ada di sekitar sini di suatu tempat.",
  ui_story_5079_50791001_32_dialog_content = "Graaah!",
  ui_story_5079_50791001_33_dialog_content = "A-Apa?",
  ui_story_5079_50791001_34_dialog_content = "Apa yang dilakukan Eclipsites di tempat seperti ini?",
  ui_story_5079_50791001_35_dialog_content = "Aku tahu ada sesuatu yang aneh tentang bau wortel ini... Apakah kekuatan Dewa Makanan ini somehow terhubung dengan Eclipsite?",
  ui_story_5079_50791001_36_dialog_content = "Jika begitu, Folta berada dalam bahaya yang jauh lebih besar dari yang kita sadari.",
  ui_story_5079_50791001_37_dialog_content = "Aku perlu menghindari mereka untuk sementara dan memeriksa gua ini...",
  ui_story_5079_50791001_38_dialog_content = "Graaah!",
  ui_story_5079_50791001_39_dialog_content = "Tsk, semakin dekat aku ke gua, semakin banyak Eclipsite yang muncul.",
  ui_story_5079_50791001_40_dialog_content = "Baiklah, Hunting Stone, mari kita...",
  ui_story_5079_50791001_41_dialog_content = "Tunggu, Hunting Stone tidak ada bersamaku sekarang... Bisakah aku benar-benar menangani Eclipsite sebanyak ini sendirian?",
  ui_story_5079_50791001_42_dialog_content = "... Heh.",
  ui_story_5079_50791001_43_dialog_content = "Ada apa, Pact? Sejak kapan kamu menjadi lemah ini?",
  ui_story_5079_50791001_44_dialog_content = "Tanpa Hunting Stone, mengalahkan Eclipsites ini seharusnya jadi lebih mudah!",
  ui_story_5079_50791001_45_dialog_content = "Datang dan tangkap kami... Maksudku, aku! Datang dan tangkap aku!",
  ui_story_5079_50791001_46_dialog_content = "<color=#e8d9bb>Mendera!</color>",
  ui_story_5079_50791001_47_dialog_content = "...",
  ui_story_5079_50791001_48_dialog_content = "Graaah!",
  ui_story_5079_50791001_49_dialog_content = "... Mengikat!",
  ui_story_5079_50791001_50_dialog_content = "Graaah!",
  ui_story_5079_50791001_51_dialog_content = "Tsk... Seranganku jauh lebih lambat, dan mereka berhasil melepaskan diri dari ikatanku jauh lebih cepat dari yang kuharapkan.",
  ui_story_5079_50791001_52_dialog_content = "Aku tidak akan kesulitan melawan Eclipsites yang lemah ini jika aku bersama Hunting Stone...",
  ui_story_5079_50791001_53_dialog_content = "Ini tidak mungkin terjadi... Aku benar-benar mulai merindukan roda bodoh itu! Aku benar-benar lelucon...",
  ui_story_5079_50791001_54_dialog_content = "Saya harus mengandalkan kekuatan saya sendiri sekarang...",
  ui_story_5079_50791100_1_dialog_content = "Graah—",
  ui_story_5079_50791100_2_dialog_content = "Fyuh... Mestinya itu tadi yang terakhir dari mereka.",
  ui_story_5079_50791100_3_dialog_content = "Lihat? Luminatics saya masih cukup kuat untuk mengalahkan banyak Eclipsites <color=#FFB400>sendirian</color>.",
  ui_story_5079_50791100_4_dialog_content = "Meski di masa lalu, itu tidak begitu menguras tenagaku.",
  ui_story_5079_50791100_5_dialog_content = "Hunting Stone... Aku tidak membutuhkannya untuk bertarung, tapi memang ada beberapa kegunaannya...",
  ui_story_5079_50791100_6_dialog_content = "Graaah!",
  ui_story_5079_50791100_7_dialog_content = "Ah!",
  ui_story_5079_50791100_8_dialog_content = "Aku lengah! Aku harus—",
  ui_story_5079_50791100_9_dialog_content = "!",
  ui_story_5079_50791100_10_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5079_50791100_11_dialog_content = "Hunting Stone? Siapa yang menyuruhmu kembali padaku? Jangan bilang kamu—",
  ui_story_5079_50791100_12_dialog_content = "Hei! Apakah kamu baik-baik saja?",
  ui_story_5079_50791100_13_dialog_content = "Popo? Heh, tentu saja saya baik-baik saja. Beri saya sedikit waktu untuk membersihkan sisa Eclipsites ini.",
  ui_story_5079_50791100_14_dialog_content = "Cicipi duri-duri indahku!",
  ui_story_5079_50791100_15_dialog_content = "<color=#e8d9bb>Fyuh! Plak!</color>",
  ui_story_5079_50791100_16_dialog_content = "Graaah!",
  ui_story_5079_50791100_17_dialog_content = "Saya juga bisa membantu! Hunting Stone!",
  ui_story_5079_50791100_18_dialog_content = "!",
  ui_story_5079_50791100_19_dialog_content = "Graaah...",
  ui_story_5079_50791100_20_dialog_content = "Kita berhasil! Kita berhasil! Kita telah membasmi semua Eclipsite yang menjijikkan itu bersama-sama!",
  ui_story_5079_50791100_21_dialog_content = "Benar sekali kita lakukan! Kamu luar biasa, Popo. Saya tidak tahu kamu bisa menggunakan Luminatics!",
  ui_story_5079_50791100_22_dialog_content = "Itu karena aku tidak bisa... setidaknya tidak sebelumnya.",
  ui_story_5079_50791100_23_dialog_content = "Tapi aku sangat ketakutan saat melihat Eclipsite itu menyerangmu, dan tiba-tiba kekuatan ini muncul dari dalam diriku!",
  ui_story_5079_50791100_24_dialog_content = "Saya jujur tidak bisa percaya. Saya yakin Ayah akan sangat senang ketika dia mengetahuinya!",
  ui_story_5079_50791100_25_dialog_content = "Y-Ya... Pasti...",
  ui_story_5079_50791100_26_dialog_content = "(Sumber kekuatan Popo sama seperti milikku, dan sepertinya dia memiliki banyak potensi...)",
  ui_story_5079_50791100_27_dialog_content = "(Apakah itulah sebabnya dia bisa memerintah Hunting Stone? Aku pikir itu seharusnya hanya menurut padaku...)",
  ui_story_5079_50791100_28_dialog_content = "Bau wortel berasal dari gua Dewa Makanan! Aku yakin sekarang!",
  ui_story_5079_50791100_29_dialog_content = "Aku juga mendengar suara... Itu menyuruhku untuk mendekat!",
  ui_story_5079_50791100_30_dialog_content = "Suara? Aku pikir kamu hanya bersemangat untuk menemukan ayahmu...",
  ui_story_5079_50791100_31_dialog_content = "Tebak itu berarti kamu lebih peduli padanya daripada yang kamu tunjukkan...",
  ui_story_5079_50791100_32_dialog_content = "Lagipula, bukankah aku sudah menyuruhmu menungguku di kota? Apa yang membuatmu mengejarku?",
  ui_story_5079_50791100_33_dialog_content = "Mengenai itu... Orang-orang gila penggemar wortel itu memaksaku untuk makan kue wortel mereka, dan aku akhirnya memuntahkannya. Saat itulah aku tahu bahwa penyamaranku terbongkar.",
  ui_story_5079_50791100_34_dialog_content = "Jadi saya pergi dengan Hunting Stone, tapi saya tidak menyadari bahwa itu bahkan lebih cepat daripada kereta. Kami sampai di sini dalam waktu yang hampir tidak ada sama sekali... Kamu tidak marah padaku, kan?",
  ui_story_5079_50791100_35_dialog_content = "Tentu saja tidak. Jika ada yang membuatku marah, itu adalah orang dewasa yang mencoba menghukummu dengan sesuatu yang sangat menjijikkan!",
  ui_story_5079_50791100_36_dialog_content = "Benar kan? Benar kan? Aku tidak bisa melahap satu suapan pun! Itulah sebabnya aku tidak punya pilihan selain datang mencarimu.",
  ui_story_5079_50791100_37_dialog_content = "Saya tahu sejak awal—Tim Anti-Wortel harus tetap bersatu tidak peduli apa yang terjadi!",
  ui_story_5079_50791100_38_dialog_content = "<size=30>Tapi hanya ada satu Hunting Stone...</size>",
  ui_story_5079_50791100_39_dialog_content = "Ha?",
  ui_story_5079_50791100_40_dialog_content = "(Popo mungkin belum menyadarinya. Luminatics-nya masih terlalu lemah, jadi dia harus mengandalkan Hunting Stone untuk menggunakannya...)",
  ui_story_5079_50791100_41_dialog_content = "Apa masalahnya, Hunting Stone? Biasanya aku tidak pernah bisa lepas dari kamu, tapi sepertinya kamu cukup dekat dengan tuan barumu sekarang...",
  ui_story_5079_50791100_42_dialog_content = "Karena kamu telah memilih dia daripada saya, kamu sebaiknya merawatnya dengan baik. Mengerti?",
  ui_story_5079_50791100_43_dialog_content = "Kamu tidak perlu mengikutiku lagi, jadi biarkan aku menikmati ketenangan dan kesunyian.",
  ui_story_5079_50791100_44_dialog_content = "...",
  ui_story_5079_50791100_45_dialog_content = "Apa yang kamu bisikkan di sana?",
  ui_story_5079_50791100_46_dialog_content = "Sebagai anggota tim, saya berhak tahu!",
  ui_story_5079_50791100_47_dialog_content = "Jangan khawatir tentang itu. Lagipula, aku punya kabar yang lebih baik untuk dibagikan padamu. Aku berbicara dengan konduktor kereta, dan dia bilang Ayahmu turun di stasiun ini.",
  ui_story_5079_50791100_48_dialog_content = "Dia pasti terlibat dalam insiden gila ini, meski aku tidak benar-benar yakin bagaimana.",
  ui_story_5079_50791100_49_dialog_content = "Bisa jadi ayah benar-benar...",
  ui_story_5079_50791100_50_dialog_content = "Aku akan masuk ke hutan dan memeriksa keadaan. Kamu dan Batu Berburu bisa berjaga di sini.",
  ui_story_5079_50791100_51_dialog_content = "Tidak mungkin! Jika kamu masuk ke hutan, maka aku juga akan ikut!",
  ui_story_5079_50791100_52_dialog_content = "Ada Eclipsites yang bersembunyi di sekitar sini, dan akan ada lebih banyak lagi di hutan. Membiarkan kamu ikut akan terlalu berbahaya.",
  ui_story_5079_50791100_53_dialog_content = "Tapi aku bisa menggunakan Luminatics sekarang! Aku bisa membantu!",
  ui_story_5079_50791100_54_dialog_content = "Kamu baru saja menemukan kekuatanmu hari ini, bukan? Menggunakannya untuk melindungi diri sendiri akan membutuhkan segala yang kamu miliki, dan aku tidak akan punya waktu untuk datang menyelamatkanmu...",
  ui_story_5079_50791100_55_dialog_content = "Aku bisa mengurus diriku sendiri dengan baik. Kita seharusnya saling membantu, seperti yang telah kita sepakati!",
  ui_story_5079_50791100_56_dialog_content = "Lagipula, bukankah aku baru saja menyelamatkanmu dari segerombolan Eclipsites?",
  ui_story_5079_50791100_57_dialog_content = "...",
  ui_story_5079_50791100_58_dialog_content = "(Semua yang bisa kupikirkan sebelumnya adalah menyingkirkan Hunting Stone, tapi setelah melihat betapa dekatnya batu itu dengan Popo, aku...)",
  ui_story_5079_50791100_59_dialog_content = "Katakan saja, kau sama sekali tidak percaya padaku, bukan?",
  ui_story_5079_50791100_60_dialog_content = "Bukan berarti saya tidak percaya padamu. Saya hanya khawatir ayahmu akan kecewa jika melihat Luminatics-mu yang setengah matang beraksi.",
  ui_story_5079_50791100_61_dialog_content = "A-Apa? Tidak mungkin... Ayah selalu bermimpi bahwa suatu hari nanti aku akan belajar bagaimana menggunakan Luminatics!",
  ui_story_5079_50791100_62_dialog_content = "Benarkah? Tetapi jika kamu belajar Luminatics, harapannya hanya akan semakin tinggi dan tinggi. Dia tidak akan berhenti sampai kamu menjadi putri idealnya...",
  ui_story_5079_50791100_63_dialog_content = "Tapi siapa yang tahu kapan dia akan merasa puas? Bahkan, dia mungkin saja...",
  ui_story_5079_50791100_64_dialog_content = "...",
  ui_story_5079_50791100_65_dialog_content = "Uh, tidak apa-apa. Lupakan saja perkataanku tadi...",
  ui_story_5079_50791100_66_dialog_content = "Aku... Aku tidak terlalu bersemangat untuk menunjukkan Luminatics-ku padanya...",
  ui_story_5079_50791100_67_dialog_content = "Tidak masalah bagi saya selama saya tahu dia aman. Membantu Anda dalam misi Anda jauh lebih penting.",
  ui_story_5079_50791100_68_dialog_content = "Selain itu, kita akan sampai lebih cepat jika saya yang memimpin jalan. Percayalah, saya tahu banyak jalan pintas!",
  ui_story_5079_50791100_69_dialog_content = "Pintasan? <size=30>Hunting Stone, pastikan tidak ada Eclipsite yang menghalangi jalan Popo.</size>",
  ui_story_5079_50791100_70_dialog_content = "...",
  ui_story_5079_50791100_71_dialog_content = "Tsk, dia pergi melindunginya tanpa ragu-ragu...",
  ui_story_5079_50791100_72_dialog_content = "Yah, setidaknya menyenangkan dan tenang berjalan sendirian.",
  ui_story_5079_50791100_73_dialog_content = "Selama itu membantu saya menyelesaikan misi saya... Saya rasa saya bisa bertahan untuk saat ini.",
  ui_story_5079_50791100_74_dialog_content = "Nyonya, basis para fanatik wortel di barat Folta sekarang berada di bawah kendali kita.",
  ui_story_5079_50791100_75_dialog_content = "Meskipun membutuhkan banyak bujukan, para pembenci wortel di sisi timur kota juga telah setuju untuk berhenti berbuat kerusuhan.",
  ui_story_5079_50791100_76_dialog_content = "Kedamaian di Folta telah dipulihkan, meski hanya sementara. Namun...",
  ui_story_5079_50791100_77_dialog_content = "Orang asing dan Popo belum ditangkap, benar?",
  ui_story_5079_50791100_78_dialog_content = "Ketidakmampuan saya sendiri yang patut disalahkan... Mohon maafkan saya...",
  ui_story_5079_50791100_79_dialog_content = "Tidak, ini tidak ada hubungannya denganmu. Peristiwa-peristiwa ini telah lama diramalkan oleh Buku Masakan Hitam...",
  ui_story_5079_50791100_80_dialog_content = "\"Mereka yang membencinya akan memeliharanya. Dengan melakukan itu, mereka juga akan mengakhirinya.\"",
  ui_story_5079_50791100_81_dialog_content = "Maafkan ketidaktahuan saya, tapi apa sebenarnya arti dari ramalan ini—",
  ui_story_5079_50791100_82_dialog_content = "Ini berarti bahwa mereka yang paling membenci wortellah yang bertanggung jawab atas bencana ini, dan mereka juga yang akan mengakhiri semuanya.",
  ui_story_5079_50791100_83_dialog_content = "Mereka jelas dua orang, namun mereka juga satu dan sama... Sungguh ramalan yang menarik.",
  ui_story_5079_50791100_84_dialog_content = "Mereka sudah menuju ke gua Dewa Makanan, bukan?",
  ui_story_5079_50791100_85_dialog_content = "Ya, Nona. Haruskah kita mengejar mereka?",
  ui_story_5079_50791100_86_dialog_content = "Heheh, aku takut bukan. Mimpi ini bukan milik kita, yang berarti kita tidak memiliki hak untuk ikut campur.",
  ui_story_5079_50791100_87_dialog_content = "Katakan padaku, apakah kamu suka dongeng?",
  ui_story_5079_50791100_88_dialog_content = "Dongeng? Jika itu keinginanmu, aku bisa membaca lebih banyak lagi...",
  ui_story_5079_50791100_89_dialog_content = "Dunia yang indah selalu menyembunyikan kebenaran yang kejam dan brutal.",
  ui_story_5079_50791100_90_dialog_content = "Namun untuk menghadapi kekejaman ini dan muncul darinya adalah berjalan menuju cahaya.",
  ui_story_5079_50791100_91_dialog_content = "Siklus kontradiksi ini adalah jalan yang mengarah ke Kebenaran.",
  ui_story_5079_50791100_92_dialog_content = "Aku paham.",
  ui_story_5079_50791100_93_dialog_content = "Di mana kereta itu berhenti sekarang?",
  ui_story_5079_50791100_94_dialog_content = "Kereta? Sudah masuk jauh ke dalam Hutan Cream, dan saya khawatir tidak akan kembali ke Folta dalam waktu dekat.",
  ui_story_5079_50791100_95_dialog_content = "Begitukah? Kalau saja aku tahu lebih awal, aku juga akan naik itu.",
  ui_story_5079_50791100_96_dialog_content = "Meski dia tidak berniat untuk bernostalgia tentang masa lalu bersamaku, tidak ada yang tahu kapan kita akan memiliki kesempatan seperti ini lagi...",
  ui_story_5079_50791100_97_dialog_content = "Perselisihanmu dengan konduktor bahkan lebih lama daripada umurku sendiri...",
  ui_story_5079_50791100_98_dialog_content = "Tidak, saya tidak berhak menanyakan hal-hal ini... Mohon maafkan saya...",
  ui_story_5079_50791200_1_dialog_content = "<color=#e8d9bb>*langkah kaki*</color>",
  ui_story_5079_50791200_2_dialog_content = "Langkah kakimu semakin berat. Apakah kamu perlu istirahat?",
  ui_story_5079_50791200_3_dialog_content = "A... Aku baik-baik saja.",
  ui_story_5079_50791200_4_dialog_content = "Jika kamu baik-baik saja, maka jangan mencubit hidungmu saat menjawabku...",
  ui_story_5079_50791200_5_dialog_content = "Pokoknya, kamu sepertinya benar-benar mengenal tempat ini. Kita bahkan berhasil menghindari beberapa gerombolan Eclipsite. Apakah kita hampir sampai?",
  ui_story_5079_50791200_6_dialog_content = "Tentu... Tentu saja aku sangat mengenal tempat ini... Ini adalah pangkalan rahasiaku, bagaimanapun.",
  ui_story_5079_50791200_7_dialog_content = "Ini adalah tempat di mana saya menawarkan semua wortel menjijikkan yang tidak ingin saya makan kepada Dewa Makanan...",
  ui_story_5079_50791200_8_dialog_content = "Tentu saja, aku harus... membersihkan banyak jalan...",
  ui_story_5079_50791200_9_dialog_content = "Bukankah kamu khawatir bahwa Dewa Makanan akan menghukummu karena hanya menawarkan makanan yang tidak ingin kamu makan?",
  ui_story_5079_50791200_10_dialog_content = "Sama sekali tidak! Penawaran saya benar-benar tulus...",
  ui_story_5079_50791200_11_dialog_content = "Aku berdoa dengan tulus kepada Dewa Makanan... untuk menghapus wortel dari setiap resep di dunia!",
  ui_story_5079_50791200_12_dialog_content = "Kamu pasti cukup tulus karena berteriak seperti itu meskipun kamu sangat lemah...",
  ui_story_5079_50791200_13_dialog_content = "Tahu apa? Saya pikir saya pernah melakukan hal serupa ketika saya masih kecil...",
  ui_story_5079_50791200_14_dialog_content = "Sayangnya, itu tidak banyak membantu saya. Sebaiknya kau simpan tenagamu—",
  ui_story_5079_50791200_15_dialog_content = "Hah... Kita di sini—gua Dewa Makanan!",
  ui_story_5079_50791200_16_dialog_content = "*Batuk-batuk* Aku rasa... mungkin aku... alergi terhadap wortel...",
  ui_story_5079_50791200_17_dialog_content = "Saya cukup yakin ini bukan hanya karena wortel...",
  ui_story_5079_50791200_18_dialog_content = "Dengan begitu banyak Eclipsite yang berkumpul di sini, Darkflow menjadi sangat padat. Wajar jika kamu merasa terpengaruh oleh hal itu.",
  ui_story_5079_50791200_19_dialog_content = "Untungnya, gua ini tampaknya tidak terlalu dalam. Saya akan masuk dan melihat-lihat sementara kamu menarik nafas di pintu masuk gua.",
  ui_story_5079_50791200_20_dialog_content = "Hunting Stone, tetap di sini dan lindungi Popo.",
  ui_story_5079_50791200_21_dialog_content = "...",
  ui_story_5079_50791200_22_dialog_content = "Apa ini? Aku pikir kalian berdua adalah teman terbaik, jadi kenapa kalian khawatir tentangku lagi?",
  ui_story_5079_50791200_23_dialog_content = "...",
  ui_story_5079_50791200_24_dialog_content = "Hunting Stone... K-Ku rasa kamu harus pergi bersamanya.",
  ui_story_5079_50791200_25_dialog_content = "Popo! Ini bukan saatnya berlagak berani!",
  ui_story_5079_50791200_26_dialog_content = "A-Aku tidak! Dalam kondisi saat ini, aku tidak bisa mengendalikan Hunting Stone... Meninggalkannya padaku akan sia-sia.",
  ui_story_5079_50791200_27_dialog_content = "Jangan khawatir, saya tahu tempat ini seperti punggung tangan saya. Butuh seratus tahun bagi Eclipsite untuk menemukan saya di salah satu tempat persembunyian saya! Heehee...",
  ui_story_5079_50791200_28_dialog_content = "... Aku mengerti apa yang kamu maksud sekarang. Kamu ingin aku menggunakan Hunting Stone untuk melindungi ayahmu jika dia benar-benar di sana, bukan?",
  ui_story_5079_50791200_29_dialog_content = "Jangan khawatir, aku tidak akan membiarkan apa pun terjadi padanya.",
  ui_story_5079_50791200_30_dialog_content = "Itu bukan yang saya maksud tadi... Tapi...",
  ui_story_5079_50791200_31_dialog_content = "Tolong... Hanya kembali dengan selamat, baik kamu maupun ayahku...",
  ui_story_5079_50791200_32_dialog_content = "Ada perasaan itu lagi... Kenapa gua ini terasa sangat familiar?",
  ui_story_5079_50791200_33_dialog_content = "Ini seperti saat aku bertemu dengan kepala Keluarga Ketchup dan penasihatnya. Tapi perasaan ini...",
  ui_story_5079_50791200_34_dialog_content = "Sungguh sedih dan menyakitkan...",
  ui_story_5079_50791200_35_dialog_content = "!",
  ui_story_5079_50791200_36_dialog_content = "Aku... Aku pernah ke sini sebelumnya, tapi terakhir kali... Apakah karena aku sedang lari?",
  ui_story_5079_50791200_37_dialog_content = "...",
  ui_story_5079_50791200_38_dialog_content = "...",
  ui_story_5079_50791200_39_dialog_content = "*menangis* Kalau saja...",
  ui_story_5079_50791200_40_dialog_content = "Seandainya aku mengetahui Luminatics lebih awal, mungkin...",
  ui_story_5079_50791200_41_dialog_content = "Mungkin ibu tidak akan terbunuh oleh Eclipsite...",
  ui_story_5079_50791200_42_dialog_content = "Tidur, Pact.",
  ui_story_5079_50791200_43_dialog_content = "Tapi... Tapi aku ingin ibu memelukku lagi...",
  ui_story_5079_50791200_44_dialog_content = "Cukup! Ini bukan liburan; kita sedang berjuang untuk hidup kita! Eclipsite di luar sana—",
  ui_story_5079_50791200_45_dialog_content = "...Demi ibumu, kita harus berusaha semampu kita untuk bertahan hidup. Kamu mengerti?",
  ui_story_5079_50791200_46_dialog_content = "Aku... Aku tidak ingin mengerti! Aku hanya ingin ibuku!",
  ui_story_5079_50791200_47_dialog_content = "...",
  ui_story_5079_50791200_48_dialog_content = "Ayah itu yang terburuk... Bagaimana bisa dia menyuruhku melupakan Ibu?",
  ui_story_5079_50791200_49_dialog_content = "Aku berjalan sejauh ini, tapi dia masih belum mencariku...",
  ui_story_5079_50791200_50_dialog_content = "Dia yang terburuk... Bagaimana dia bisa menyuruhku untuk melupakan Ibu?",
  ui_story_5079_50791200_51_dialog_content = "Hah? Aku melihat cahaya di sana...",
  ui_story_5079_50791200_52_dialog_content = "<color=#e8d9bb>*langkah kaki*</color>",
  ui_story_5079_50791200_53_dialog_content = "Apa ini...",
  ui_story_5079_50791200_54_dialog_content = "Seorang idola?",
  ui_story_5079_50791200_55_dialog_content = "Jika memang ada tuhan di luar sana, berikanlah ibuku kembali padaku...",
  ui_story_5079_50791200_56_dialog_content = "Tidak, tunggu... Ibu bilang aku harus hormat saat berdoa kepada dewa-dewa. Aku harus lebih dewasa dalam hal ini...",
  ui_story_5079_50791200_57_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_5079_50791200_58_dialog_content = "Aku berharap semua pertarungan ini berakhir. Aku berharap memiliki kekuatan untuk melindungi keluargaku...",
  ui_story_5079_50791200_59_dialog_content = "Tolong kabulkan permintaanku, dan aku akan mengikutimu dan memujamu sepanjang sisa hidupku...",
  ui_story_5079_50791200_X59_dialog_content = "A-Aku bahkan akan...",
  ui_story_5079_50791200_60_dialog_content = "<color=#e8d9bb>Selama waktu yang lama, gadis kecil itu berlutut di depan patung dalam doa yang sunyi.</color>",
  ui_story_5079_50791200_61_dialog_content = "<color=#e8d9bb>Di dalam kegelapan yang tenang, hatinya yang lelah perlahan terhanyut ke dalam tidur yang dalam.</color>",
  ui_story_5079_50791200_62_dialog_content = "<color=#e8d9bb>Gemerincing, gemerincing—</color>",
  ui_story_5079_50791200_63_dialog_content = "...",
  ui_story_5079_50791200_64_dialog_content = "Maksudmu?",
  ui_story_5079_50791200_65_dialog_content = "Hah? K-Kapan aku tertidur...?",
  ui_story_5079_50791200_66_dialog_content = "Pact? Jadi ini tempat kamu bersembunyi! Apakah kamu tahu berapa lama aku mencari kamu?",
  ui_story_5079_50791200_67_dialog_content = "...",
  ui_story_5079_50791200_68_dialog_content = "!!!",
  ui_story_5079_50791200_69_dialog_content = "Ken-Kenapa kau menatapku seperti itu...?",
  ui_story_5079_50791200_70_dialog_content = "Pact, aku butuh kamu berjalan pelan-pelan mendekatiku tanpa menoleh ke belakang. Cepat!",
  ui_story_5079_50791200_71_dialog_content = "Tanpa menoleh ke belakang? Apakah ada sesuatu di belakangku?",
  ui_story_5079_50791200_72_dialog_content = "...",
  ui_story_5079_50791200_73_dialog_content = "A-Apa...?",
  ui_story_5079_50791200_74_dialog_content = "Apa... ini?",
  ui_story_5079_50791200_75_dialog_content = "Pact, aku butuh kamu berjalan perlahan mendekatiku. Jangan takut, dan jangan menoleh ke belakang...",
  ui_story_5079_50791200_76_dialog_content = "O-Oke... Aku datang...",
  ui_story_5079_50791200_77_dialog_content = "Graaah!",
  ui_story_5079_50791200_78_dialog_content = "Apa?! Di saat-saat yang paling buruk...",
  ui_story_5079_50791200_79_dialog_content = "Cari tempat untuk bersembunyi, Pact! Aku akan menangani monster-monster ini!!!",
  ui_story_5079_50791200_80_dialog_content = "Ayah... Tidak... Kamu tidak akan bisa melawan Eclipsites...",
  ui_story_5079_50791200_81_dialog_content = "Graaah!",
  ui_story_5079_50791200_82_dialog_content = "Tidak... Tidaaaak!!!",
  ui_story_5079_50791200_83_dialog_content = "!",
  ui_story_5079_50791200_84_dialog_content = "Graaah...",
  ui_story_5079_50791200_85_dialog_content = "Hah? Serangan itu barusan... Apakah aku yang melakukannya?",
  ui_story_5079_50791200_86_dialog_content = "Benda ini... Roda aneh ini... Ini adalah senjataku!",
  ui_story_5079_50791200_87_dialog_content = "Aku bisa menggunakan Luminatics, Ayah! Aku... aku bisa melindungimu sekarang!",
  ui_story_5079_50791200_88_dialog_content = "Kita tidak perlu bersembunyi lagi! ... Ayah? Kenapa kamu terlihat begitu kesal?",
  ui_story_5079_50791200_89_dialog_content = "...",
  ui_story_5079_50791200_90_dialog_content = "Oke...",
  ui_story_5079_50791200_91_dialog_content = "Jadi, selama ini kamu adalah Dewa Makanan?",
  ui_story_5079_50791200_92_dialog_content = "Tolong kabulkan permintaanku, dan aku akan mengikutimu dan memujamu sepanjang sisa hidupku...",
  ui_story_5079_50791200_93_dialog_content = "Sepertinya aku tak akan pernah bebas dari belenggumu, ya?",
  ui_story_5079_50791200_94_dialog_content = "...",
  ui_story_5079_50791200_95_dialog_content = "Hunting Stone?",
  ui_story_5079_50791200_96_dialog_content = "...",
  ui_story_5079_50791200_97_dialog_content = "Hei, apa yang kamu lakukan? Aku tidak menyuruhmu pergi ke sana...",
  ui_story_5079_50791200_98_dialog_content = "!",
  ui_story_5079_50791200_99_dialog_content = "Mereka melebur jadi satu?",
  ui_story_5079_50791200_100_dialog_content = "Tidak... Ini hanya kembali ke bentuk aslinya.",
  ui_story_5079_50791200_101_dialog_content = "Ini adalah rumah Hunting Stone. Tempat di mana ia seharusnya berada...",
  ui_story_5079_50791200_102_dialog_content = "Sejak awal, itu bukan mengikutiku. Selama ini, aku yang menjaganya dari rumahnya...",
  ui_story_5079_50791200_103_dialog_content = "!",
  ui_story_5079_50791200_104_dialog_content = "Ayolah, bisa tidak? Kamu hanya di rumah, itu saja... Tidak perlu terlalu bersemangat.",
  ui_story_5079_50791200_105_dialog_content = "Atau mungkin itu aku... Mungkin aku saja yang tidak mampu merasakan perasaan itu.",
  ui_story_5079_50791200_106_dialog_content = "Lagipula, aku tidak punya rumah untuk kembali lagi...",
  ui_story_5079_50791200_107_dialog_content = "Aku memang tidak pernah menginginkanmu di sekitarku. Dengan cara ini, semua orang mendapatkan apa yang mereka inginkan.",
  ui_story_5079_50791200_108_dialog_content = "Sekarang aku akan mencari ayah Popo, jadi...",
  ui_story_5079_50791200_109_dialog_content = "!",
  ui_story_5079_50791200_110_dialog_content = "Ikut saja kalau mau, tapi jika kamu memutuskan untuk tinggal di sini...",
  ui_story_5079_50791200_111_dialog_content = "Maka ini adalah selamat tinggal.",
  ui_story_5079_50791200_112_dialog_content = "Ini juga akan baik... Kamu mendengarku?",
  ui_story_5079_50791200_113_dialog_content = "!",
  ui_story_5079_50791200_114_dialog_content = "Berhenti berpura-pura... Kamu membuatnya terlihat seperti keputusan yang sulit, tapi kamu sama sekali tidak bergerak, 'kan?",
  ui_story_5079_50791200_115_dialog_content = "Aku benar-benar akan pergi! Lihat? Aku sedang berjalan pergi...",
  ui_story_5079_50791200_116_dialog_content = "!",
  ui_story_5079_50791200_117_dialog_content = "Baik. Saya lihat kamu sudah membuat keputusan.",
  ui_story_5079_50791200_118_dialog_content = "Selamat tinggal, Hunting Stone.",
  ui_story_5079_50791301_1_dialog_content = "<color=#e8d9bb>*langkah kaki*</color>",
  ui_story_5079_50791301_2_dialog_content = "Berengsek itu, benar-benar tinggal di belakang... Pasti enak punya tempat yang bisa disebut rumah.",
  ui_story_5079_50791301_3_dialog_content = "Bisakah keinginanku terpenuhi begitu mudahnya? Rasanya terlalu bagus untuk menjadi kenyataan, dan itu menggangguku.",
  ui_story_5079_50791301_4_dialog_content = "Apa sebenarnya benda itu? Aku masih belum tahu...",
  ui_story_5079_50791301_5_dialog_content = "Ah, tapi itu tidak penting sekarang! Yang terpenting adalah aku sudah mendapatkan keinginanku, bukan?",
  ui_story_5079_50791301_6_dialog_content = "...",
  ui_story_5079_50791301_7_dialog_content = "Anda disana!",
  ui_story_5079_50791301_8_dialog_content = "Hei! Apakah kamu baik-baik saja?",
  ui_story_5079_50791301_9_dialog_content = "Aduh...",
  ui_story_5079_50791301_10_dialog_content = "Bagus, lukamu tampaknya tidak terlalu serius. Ayo, bangun!",
  ui_story_5079_50791301_11_dialog_content = "Hei, hei! Sekarang bukan waktunya tidur siang... Putrimu sedang menunggumu di luar!",
  ui_story_5079_50791301_12_dialog_content = "P-Putriku...",
  ui_story_5079_50791301_13_dialog_content = "Benar! Kamu datang ke sini untuk mencari Popo, bukan?",
  ui_story_5079_50791301_14_dialog_content = "P-Popo?",
  ui_story_5079_50791301_15_dialog_content = "Popo, apakah itu benar-benar kamu? Oh, syukurlah... Aku sangat senang kamu aman!",
  ui_story_5079_50791301_16_dialog_content = "Aku salah, Popo... Aku terlalu keras padamu sebelumnya. Bagaimana mungkin aku tidak menginginkanmu?",
  ui_story_5079_50791301_17_dialog_content = "Terlalu sulit? Argh... Kepalaku...",
  ui_story_5079_50791301_18_dialog_content = "Lihat, Popo! Ini adalah wortel terbaik yang pernah saya hasilkan dalam hidup saya! Salah satu pelanggan tetap kami bersikeras untuk saya menjualnya kepadanya, tetapi saya menolaknya...",
  ui_story_5079_50791301_19_dialog_content = "*menarik nafas* Popo masih menolak untuk makan wortelnya. Sungguh gadis kecil yang keras kepala.",
  ui_story_5079_50791301_20_dialog_content = "Kurasa aku harus membelikannya permen kali ini... Tapi aku tidak akan begitu murah hati lain kali dia menolak makanannya...",
  ui_story_5079_50791301_21_dialog_content = "Popo akhirnya belajar cara menggunakan Luminatics, tapi... Saya hanya berharap dia bisa sedikit lebih beradab.",
  ui_story_5079_50791301_22_dialog_content = "Saya tidak bisa mengajarinya apa-apa... Saya ini ayah yang tidak berguna...",
  ui_story_5079_50791301_23_dialog_content = "Seandainya ada seorang Aurorian yang mulia yang bisa mengajarnya, tetapi saya tidak mengenal siapa pun seperti itu sama sekali...",
  ui_story_5079_50791301_24_dialog_content = "Gaunmu lagi-lagi penuh dengan lubang! Kenapa kamu tidak bisa membuang benda jelek ini saja?",
  ui_story_5079_50791301_25_dialog_content = "A... Aku hanya ingin memiliki kehidupan normal dengan putriku yang normal! Apakah itu terlalu banyak untuk diminta?",
  ui_story_5079_50791301_26_dialog_content = "Pikir! Pasti ada cara untuk membuat hal ini hilang! Aku... Aku...",
  ui_story_5079_50791301_27_dialog_content = "Lupakan saja... Selama hidupku, aku tak akan pernah memiliki toko mewah...",
  ui_story_5079_50791301_28_dialog_content = "Tapi setidaknya, kita harus hidup dengan baik... Aku akan menemukan penataan yang cocok hanya untukmu.",
  ui_story_5079_50791301_29_dialog_content = "Bagaimana menurutmu, Popo?",
  ui_story_5079_50791301_30_dialog_content = "Ingin aku menerima pengaturanmu? Tidak mungkin! Terutama setelah kau bilang aku tak punya harapan dalam suratmu...",
  ui_story_5079_50791301_31_dialog_content = "!",
  ui_story_5079_50791301_32_dialog_content = "Tunggu... Apa yang baru saja aku lihat? Kamu... Ayahnya Popo...",
  ui_story_5079_50791301_33_dialog_content = "Maaf, tapi aku bukan putrimu. Anda harus menyimpan kata-kata itu untuknya, bukan untukku.",
  ui_story_5079_50791301_34_dialog_content = "Saya... Saya hanya detektif yang membantu Popo menemukanmu. Katakan padaku, apakah kamu memiliki ide apa yang sedang terjadi di Folta, atau apa yang menyebabkannya?",
  ui_story_5079_50791301_35_dialog_content = "Hah? Ada sesuatu yang terjadi di Folta?",
  ui_story_5079_50791301_36_dialog_content = "Aku tidak tahu apa yang kamu bicarakan. Apa yang terjadi di kota kita? Tunggu...",
  ui_story_5079_50791301_37_dialog_content = "Bukankah kamu... wanita muda yang aku lihat di kereta pagi ini?",
  ui_story_5079_50791301_38_dialog_content = "Mohon maafkan saya yang salah mengira Anda sebagai putri saya! Saya tidak bermaksud menyinggung, Nona!",
  ui_story_5079_50791301_39_dialog_content = "Kamu bilang bahwa kamu telah membantunya? Seorang wanita bangsawan yang beradab seperti dirimu?",
  ui_story_5079_50791301_40_dialog_content = "Saya tahu dari penampilan Anda yang berwibawa bahwa Anda adalah orang yang mulia dan berkelas tinggi!",
  ui_story_5079_50791301_41_dialog_content = "Tebak ayahku berbohong ketika dia mengatakan bahwa orang yang berpakaian rapi berperilaku lebih baik daripada orang lain!",
  ui_story_5079_50791301_42_dialog_content = "Sepertinya Popo masih ingat dengan jelas kata-kata ayahnya...",
  ui_story_5079_50791301_43_dialog_content = "Tapi saya hampir tidak berpikir bahwa karakter seseorang ada hubungannya dengan pakaian mereka.",
  ui_story_5079_50791301_44_dialog_content = "Ada banyak orang yang tampak bermartabat tetapi melakukan hal-hal memalukan di belakang layar, sama seperti ada orang yang membantu orang kurang mampu meskipun mereka sendiri mengenakan pakaian compang-camping.",
  ui_story_5079_50791301_45_dialog_content = "Ya... Saya percaya kamu benar.",
  ui_story_5079_50791301_46_dialog_content = "Dan dengan catatan itu, terlalu banyak memuji bukanlah sikap sopan. Jika ada, itu hanya membuat orang semakin tidak menyukai Anda...",
  ui_story_5079_50791301_47_dialog_content = "Aku... aku sangat minta maaf...",
  ui_story_5079_50791301_48_dialog_content = "Argh... Sudahlah. Seharusnya aku tidak mengajari kalian sopan santun sekarang...",
  ui_story_5079_50791301_49_dialog_content = "Meskipun kamu tidak tahu apa yang terjadi di kota, kamu pasti punya ide tentang apa yang menjadi sumber bau wortel di gua ini, kan?",
  ui_story_5079_50791301_50_dialog_content = "Jika kita tidak bisa menyelesaikan ini, toko wortelmu akan ditutup selamanya.",
  ui_story_5079_50791301_51_dialog_content = "Bau wortel... Ah! Apakah ini ada hubungannya dengan sesuatu yang menyerangku?",
  ui_story_5079_50791301_52_dialog_content = "Apa \"itu\"?",
  ui_story_5079_50791301_53_dialog_content = "Kamu mungkin tidak percaya padaku... tapi aku rasa aku pingsan karena monster wortel raksasa.",
  ui_story_5079_50791301_54_dialog_content = "Monster wortel? Mungkinkah ini semacam Eclipsite yang belum ditemukan?",
  ui_story_5079_50791301_55_dialog_content = "A-Aku tidak yakin, tapi... ini mungkin semua salahku...",
  ui_story_5079_50791301_56_dialog_content = "Bagaimanapun, putriku Popo kabur dari rumah karena aku, dan aku tidak bisa menemukannya di mana pun...",
  ui_story_5079_50791301_57_dialog_content = "Jadi, saya mulai mencari jawaban dari kepercayaan rakyat, dan saya menghabiskan sejumlah besar uang untuk sesuatu yang disebut \"penghormatan tertinggi.\"",
  ui_story_5079_50791301_58_dialog_content = "Saya ingin menawarkannya kepada Dewa Makanan dan memohon kepada dewa untuk menemukan putri saya.",
  ui_story_5079_50791301_59_dialog_content = "\"Sejumlah besar uang\"? Saya tidak tahu bahwa kamu begitu peduli pada Popo...",
  ui_story_5079_50791301_60_dialog_content = "Tentu saja! Dia putriku, sekaligus satu-satunya keluarga yang tersisa untukku di dunia ini!",
  ui_story_5079_50791301_61_dialog_content = "Satu-satunya keluarga yang tersisa untukmu... Sepertinya kamu benar-benar serius, jadi bagaimana bisa semuanya berakhir seperti ini?",
  ui_story_5079_50791301_62_dialog_content = "Saya... Saya tidak tahu bahwa penghormatan tertinggi akan diserap oleh wortel yang menyamar sebagai idola!",
  ui_story_5079_50791301_63_dialog_content = "Pada saat itu, ia berubah menjadi monster raksasa dan bersumpah untuk menghancurkan semua yang membenci wortel.",
  ui_story_5079_50791301_64_dialog_content = "Aku tidak bisa mengingat apa yang terjadi setelah itu...",
  ui_story_5079_50791301_65_dialog_content = "Bisakah kamu jelaskan \"penghormatan tertinggi\" ini kepada saya?",
  ui_story_5079_50791301_66_dialog_content = "Itu adalah... sebuah objek berbentuk berlian yang bercahaya...",
  ui_story_5079_50791301_67_dialog_content = "Tunggu sebentar... Itu terdengar seperti Seed! Sesuatu yang bisa mengubah Aurorian menjadi Eclipsite!",
  ui_story_5079_50791301_68_dialog_content = "Itulah yang menjelaskan mengapa aroma wortel ini menarik semua Eclipsite di luar!",
  ui_story_5079_50791301_69_dialog_content = "Jika kamu benar-benar mencintai putrimu, kamu harus berusaha lebih keras untuk akrab dengannya, dan jangan menggunakan metode gila ini saat sesuatu berjalan salah!",
  ui_story_5079_50791301_70_dialog_content = "Apa yang akan kamu lakukan jika konsekuensinya tidak bisa dibalikkan? Karena itu mungkin menjadi kemungkinan sekarang!",
  ui_story_5079_50791301_71_dialog_content = "Popo adalah gadis yang baik... Meskipun kalian selalu bertengkar, dia selalu memikirkanmu...",
  ui_story_5079_50791301_72_dialog_content = "Aku... Aku tahu dia anak yang baik. Aku tahu itu lebih baik dari siapa pun.",
  ui_story_5079_50791301_73_dialog_content = "Tapi sikap seorang anak perlu dibentuk sejak dini, dan kamu tidak bisa memuji mereka untuk segala yang mereka lakukan. Saya hanya—",
  ui_story_5079_50791301_74_dialog_content = "Kamu hanya apa? Itu tidak lebih dari pemikiran sepihak dan berharap!",
  ui_story_5079_50791301_75_dialog_content = "Pernahkah kamu benar-benar mendengarkan perasaannya tentang ini?",
  ui_story_5079_50791301_76_dialog_content = "Kamu suka wortel, jadi kamu pikir anak kecilmu juga harus menyukainya.",
  ui_story_5079_50791301_77_dialog_content = "Kamu ingin dia belajar Luminatics, jadi dia tidak punya pilihan selain belajar itu.",
  ui_story_5079_50791301_78_dialog_content = "Dan sekarang dia bisa menggunakan Luminatics, aku yakin kamu berharap Luminatics-nya sekuat dan seanggun milik bangsawan Lumopolis! \"Cinta\" ini milikmu—",
  ui_story_5079_50791301_79_dialog_content = "Tidakkah menurutmu ini terlalu berat untuk dia tanggung?",
  ui_story_5079_50791301_80_dialog_content = "Aku... Tunggu, Popo bisa menggunakan Luminatics sekarang?",
  ui_story_5079_50791301_81_dialog_content = "...",
  ui_story_5079_50791301_82_dialog_content = "... Lupakan apa yang baru saja aku katakan. Aku tidak mencoba untuk mengubah apapun di sini, tapi aku hanya berharap kamu akan berusaha untuk lebih layak mendapatkan cinta Popo.",
  ui_story_5079_50791301_83_dialog_content = "Ya, dia belajar cara menggunakan Luminatics... dan semua ini karena Eclipsites yang kamu bawa ke sini.",
  ui_story_5079_50791301_84_dialog_content = "Meski begitu... Biasanya, Seed hanya diserap oleh Aurorian. Bagaimana sebuah wortel bisa menggunakannya untuk menjadi Eclipsite?",
  ui_story_5079_50791301_85_dialog_content = "Juga, saya tidak ingat melihat monster wortel dalam perjalanan ke sini... Tunggu sebentar...",
  ui_story_5079_50791301_86_dialog_content = "...",
  ui_story_5079_50791301_87_dialog_content = "Bukankah ini pecahan dari patung yang saya lihat sebelumnya? Mengapa di sini?",
  ui_story_5079_50791301_88_dialog_content = "Oh tidak! Jangan bilang idola itu adalah...",
  ui_story_5079_50791301_89_dialog_content = "Aku... Aku rasa aku bisa mencium sumber rasa wortelnya! Seolah-olah itu terhubung denganku entah bagaimana!",
  ui_story_5079_50791301_90_dialog_content = "Bau wortel berasal dari gua Dewa Makanan! Aku yakin sekarang!",
  ui_story_5079_50791301_91_dialog_content = "Aku juga mendengar suara... Itu menyuruhku untuk mendekat!",
  ui_story_5079_50791301_92_dialog_content = "Popo dalam masalah!",
  ui_story_5079_50791301_93_dialog_content = "Ya?",
  ui_story_5079_50791301_94_dialog_content = "Dia sedang menunggu tepat di luar gua! Kita harus kembali padanya!",
  ui_story_5079_50791301_95_dialog_content = "Graaah!",
  ui_story_5079_50791301_96_dialog_content = "Aku tidak punya waktu untuk membuang-buang waktu padamu, sekarang minggir!",
  ui_story_5079_50791401_1_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5079_50791401_2_dialog_content = "Graah...",
  ui_story_5079_50791401_3_dialog_content = "Itu tadi yang terakhir. Kita seharusnya—",
  ui_story_5079_50791401_4_dialog_content = "...",
  ui_story_5079_50791401_5_dialog_content = "Hei! Kami tidak tahu apa yang menunggu kita di luar sana! Kamu tidak bisa menggunakan Luminatics, jadi berdirilah di belakangku!",
  ui_story_5079_50791401_6_dialog_content = "Popo! Popo, di mana kamu?",
  ui_story_5079_50791401_7_dialog_content = "Tsk, dia sama buruknya dalam mendengarkan seperti Popo. Kurasa mereka memang mirip...",
  ui_story_5079_50791401_8_dialog_content = "<size=45>Popo—</size>",
  ui_story_5079_50791401_9_dialog_content = "Hah? Apakah aku baru saja mendengar suara ayah?",
  ui_story_5079_50791401_10_dialog_content = "<size=45>Ayah! Aku di sini!</size>",
  ui_story_5079_50791401_11_dialog_content = "Tetap di sana, Popo! Aku akan datang menjemputmu!",
  ui_story_5079_50791401_12_dialog_content = "Berhenti! Aku mendengar sesuatu bergerak...",
  ui_story_5079_50791401_13_dialog_content = "Klak... Klak, klak, klak—",
  ui_story_5079_50791401_14_dialog_content = "Duar!",
  ui_story_5079_50791401_15_dialog_content = "po...",
  ui_story_5079_50791401_16_dialog_content = "Popopo!",
  ui_story_5079_50791401_17_dialog_content = "Aku tahu itu! Monster wortel menyamar sebagai idola di luar!",
  ui_story_5079_50791401_18_dialog_content = "Sampah tak tahu malu... Sudah berpura-pura menjadi Dewa Makanan dan mengambil persembahan orang untuk dirinya sendiri!",
  ui_story_5079_50791401_19_dialog_content = "Po... Popo!",
  ui_story_5079_50791401_20_dialog_content = "Tunggu, kemana itu pergi? Hei! Lawanmu di sini!",
  ui_story_5079_50791401_21_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5079_50791401_22_dialog_content = "Ini benar-benar mengabaikan seranganku! Hai! Berhenti di sana!",
  ui_story_5079_50791401_23_dialog_content = "Popopo!",
  ui_story_5079_50791401_24_dialog_content = "M-Mundur... Jangan mendekat!",
  ui_story_5079_50791401_25_dialog_content = "T-Terimalah ini!",
  ui_story_5079_50791401_26_dialog_content = "<color=#e8d9bb>Plak—</color>",
  ui_story_5079_50791401_27_dialog_content = "Po? Popopo...",
  ui_story_5079_50791401_28_dialog_content = "Luminatics Popo... Aku tidak percaya akhirnya aku bisa melihat kekuatan putriku sendiri...",
  ui_story_5079_50791401_29_dialog_content = "Apakah ini benar-benar saatnya untuk terpaku dalam kekaguman? Pergi cari tempat aman untuk bersembunyi!",
  ui_story_5079_50791401_30_dialog_content = "Tapi putriku...",
  ui_story_5079_50791401_31_dialog_content = "Serahkan dia padaku!",
  ui_story_5079_50791401_32_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5079_50791401_33_dialog_content = "Popopo... Seranganmu tak berguna melawanku! Aku tidak tertarik padamu...",
  ui_story_5079_50791401_34_dialog_content = "...",
  ui_story_5079_50791401_35_dialog_content = "Tapi kamu, Popo... Meski dengan nama yang indah sekalipun, kamu masih saja membenci wortel!",
  ui_story_5079_50791401_36_dialog_content = "Kebencianmu pada mereka membangkitkan kekuatanku!",
  ui_story_5079_50791401_37_dialog_content = "Aku benar. Benda ini benar-benar mengejar Popo!",
  ui_story_5079_50791401_38_dialog_content = "Hunting Stone! Tunggu, itu bukan—",
  ui_story_5079_50791401_39_dialog_content = "Popopo! Apakah kamu merujuk pada ini, mungkin?",
  ui_story_5079_50791401_40_dialog_content = "!",
  ui_story_5079_50791401_41_dialog_content = "Hunting Stone... Kembalikan itu padaku!",
  ui_story_5079_50791401_42_dialog_content = "Kamu roda yang tak berguna! Apakah kamu benar-benar akan membiarkan monster ini memanfaatkanmu seperti itu? Kemarilah sekarang juga...",
  ui_story_5079_50791401_43_dialog_content = "Aduh...",
  ui_story_5079_50791401_44_dialog_content = "Popopo!",
  ui_story_5079_50791401_45_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5079_50791401_46_dialog_content = "Hunting Stone... Apakah dia tidak lagi mendengarkanku?",
  ui_story_5079_50791401_47_dialog_content = "Saya sangat berterima kasih untuk senjata yang kamu berikan padaku.",
  ui_story_5079_50791401_48_dialog_content = "Tapi yang paling aku hargai adalah kamu, Popo...",
  ui_story_5079_50791401_49_dialog_content = "Yang aku butuhkan hanyalah satu gigitan lagi, satu potongan kebencian yang lezat, dan aku bisa menguasai setiap potongan makanan di dunia ini!",
  ui_story_5079_50791401_50_dialog_content = "Segera saya akan memberkati tidak hanya Folta, tetapi seluruh Astra dengan rasa yang renyah dan tak tertahankan dari wortel!",
  ui_story_5079_50791401_51_dialog_content = "Popopo!",
  ui_story_5079_50791401_52_dialog_content = "Tidak... Kamu tidak bisa! Dunia tidak bisa berakhir seperti itu...",
  ui_story_5079_50791401_53_dialog_content = "\"Kau tidak bisa,\" katamu? Popopo... Aku tidak setuju! Lagipula, aku tidak akan menjadi sekuat ini jika kau tidak menelantarkanku di sini!",
  ui_story_5079_50791401_54_dialog_content = "Po... Po...",
  ui_story_5079_50791401_55_dialog_content = "Bagaimana... Bagaimana bisa kamu meninggalkan wortel kecil yang lucu ini sendirian di sini?",
  ui_story_5079_50791401_56_dialog_content = "Gelap... Sangat gelap... Tidak ada nutrisi... Tidak ada tenaga...",
  ui_story_5079_50791401_57_dialog_content = "Tuhan Makanan Yang Maha Kuasa, saya ingin hidup di dunia tanpa wortel!",
  ui_story_5079_50791401_58_dialog_content = "Mengapa kita semua harus memakan sesuatu yang begitu menjijikkan sampai-sampai seharusnya tidak ada?",
  ui_story_5079_50791401_59_dialog_content = "Aku mohon padamu! Tolong hapus wortel dari setiap resep yang dikenal di dunia!",
  ui_story_5079_50791401_60_dialog_content = "Aku... seharusnya tidak... pernah muncul di dunia ini...",
  ui_story_5079_50791401_61_dialog_content = "Dibenci, ditinggalkan, tak dibutuhkan...",
  ui_story_5079_50791401_62_dialog_content = "O Dewa Makanan yang perkasa, tolong beri berkat kepada keluarga kami dengan damai dan keamanan...",
  ui_story_5079_50791401_63_dialog_content = "Dengarlah permohonanku, Dewa Makanan yang baik! Tolong buat gadis itu jatuh cinta padaku!",
  ui_story_5079_50791401_64_dialog_content = "Harap terima persembahanku, Dewa Makanan...",
  ui_story_5079_50791401_65_dialog_content = "Dewa Makanan, Dewa Makanan... Itu hanya patung, bukan? Kenapa setiap orang terus memintanya untuk mengabulkan permintaan mereka?",
  ui_story_5079_50791401_66_dialog_content = "Mereka berdoa dan memohon, tetapi tidak ada yang terjadi... Itu tidak pantas mendapatkan pemujaan mereka...",
  ui_story_5079_50791401_67_dialog_content = "Tapi aku melakukannya... Karena aku nyata! Aku masih hidup!",
  ui_story_5079_50791401_68_dialog_content = "Perhatikan aku! Lihat aku! Kagumi aku! Aku lebih baik dari patung itu... karena aku bisa mewujudkan impianmu!",
  ui_story_5079_50791401_69_dialog_content = "...",
  ui_story_5079_50791401_70_dialog_content = "Popopo!",
  ui_story_5079_50791401_71_dialog_content = "Lagipula, Dewa Makanan tidak akan pernah menjawab doamu. Sebagai gantinya—",
  ui_story_5079_50791401_72_dialog_content = "Saya akan menikmati tawaran murah hati Anda!",
  ui_story_5079_50791401_73_dialog_content = "O Dewa Makanan, terimalah wortel ini sebagai persembahanku. Satu cicipan dan kamu akan tahu persis mengapa aku sangat membencinya.",
  ui_story_5079_50791401_74_dialog_content = "Ya, Popo... Teruslah membenci mereka! Teruslah membenci aku! Itu hanya membuatku semakin kuat!",
  ui_story_5079_50791401_75_dialog_content = "Wahai Dewa Makanan, bisakah Anda membuat suami yang menjengkelkan ini menghilang?",
  ui_story_5079_50791401_76_dialog_content = "Ya, ya! Dengan senang hati akan kukabulkan permintaan penuh kebencian yang lezat ini!",
  ui_story_5079_50791401_77_dialog_content = "... Mohon terima penghormatan tertinggi ini sebagai tukarannya menemukan putri saya...",
  ui_story_5079_50791401_78_dialog_content = "Ya... Ya! Apa kau tahu sudah berapa lama aku menunggu saat ini?",
  ui_story_5079_50791401_79_dialog_content = "…Hah?",
  ui_story_5079_50791401_80_dialog_content = "Po... Popopo!",
  ui_story_5079_50791401_81_dialog_content = "...",
  ui_story_5079_50791401_82_dialog_content = "Jadi, semua ini terjadi karena aku?",
  ui_story_5079_50791401_83_dialog_content = "Monster wortel ini... itu adalah wortel yang saya tinggalkan di sini sudah lama.",
  ui_story_5079_50791401_84_dialog_content = "Memang, dan sekarang saatnya untuk membayar Anda kembali secara penuh!",
  ui_story_5079_50791401_85_dialog_content = "Ahhh—",
  ui_story_5079_50791401_86_dialog_content = "Popo!",
  ui_story_5079_50791401_87_dialog_content = "Monster wortel menggunakan kekuatan Hunting Stone untuk menumbuhkan duri di sulurnya!",
  ui_story_5079_50791401_88_dialog_content = "Tsk... Jika Hunting Stone tidak menjadi senjatanya, wortel bodoh itu tidak akan menjadi sekuat ini!",
  ui_story_5079_50791401_89_dialog_content = "Sekarang bukan waktunya kamu membuat segalanya menjadi lebih sulit untukku, brengsek!",
  ui_story_5079_50791401_90_dialog_content = "Lepaskan... Lepaskan anak perempuanku!",
  ui_story_5079_50791401_91_dialog_content = "Ha?",
  ui_story_5079_50791401_92_dialog_content = "Tunggu, apa yang kamu pikirkan sedang kamu lakukan? Kamu bahkan tidak bisa menggunakan Luminatics...",
  ui_story_5079_50791401_93_dialog_content = "Jika aku tidak bisa menggunakan Luminatics, aku akan menggunakan batu dan tongkat untuk bertarung.",
  ui_story_5079_50791401_94_dialog_content = "Meski tanpa itu, aku masih punya tinjuku!",
  ui_story_5079_50791401_95_dialog_content = "Kamu ini sepertinya meminta untuk dibunuh!",
  ui_story_5079_50791401_96_dialog_content = "*batuk* Monster itu memiliki gadis kecilku. Meskipun itu akan merenggut nyawaku, aku harus menyelamatkannya!",
  ui_story_5079_50791401_97_dialog_content = "Lepaskan dia!",
  ui_story_5079_50791401_98_dialog_content = "Aku sudah bilang padamu untuk menyerahkan dia padaku... Urgh...",
  ui_story_5079_50791401_99_dialog_content = "Kepalaku... Mengapa ini harus terjadi sekarang...",
  ui_story_5079_50791401_100_dialog_content = "Siapa kamu? Menjauhlah dari putriku!",
  ui_story_5079_50791401_101_dialog_content = "Lepaskan dia sekarang juga, atau kau akan menyesal!",
  ui_story_5079_50791401_102_dialog_content = "Menjauhlah darinya sekarang juga, atau kau akan menyesal!",
  ui_story_5079_50791401_103_dialog_content = "Berhenti, biarkan aku...",
  ui_story_5079_50791401_104_dialog_content = "Popopo!",
  ui_story_5079_50791401_105_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5079_50791401_106_dialog_content = "Argh... Itu saja kemampuanmu? Ayo hadapi aku, monster!",
  ui_story_5079_50791401_107_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5079_50791401_108_dialog_content = "Aku belum selesai... Lepaskan dia!",
  ui_story_5079_50791401_109_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5079_50791401_110_dialog_content = "Ini... Ini belum berakhir...",
  ui_story_5079_50791401_111_dialog_content = "Cepat, Popo... Aku akan mencabut duri-duri itu untukmu...",
  ui_story_5079_50791401_112_dialog_content = "<color=#e8d9bb>Tusuk—</color>",
  ui_story_5079_50791401_113_dialog_content = "Ayah... Tanganmu terlalu banyak berdarah! Dengan keadaan seperti ini, kamu akan—",
  ui_story_5079_50791401_114_dialog_content = "Jangan khawatir tentang aku! Pergilah, ayah! Ini... semua salahku juga...",
  ui_story_5079_50791401_115_dialog_content = "Itulah mengapa saya harus—",
  ui_story_5079_50791401_116_dialog_content = "Cukup sudah! Aku yang membeli upeti terkutuk itu... Andai saja aku lebih pengertian...",
  ui_story_5079_50791401_117_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5079_50791401_118_dialog_content = "Urgh... Akhirnya mau melepaskan? C-Cepat, Popo...",
  ui_story_5079_50791401_119_dialog_content = "Ayah...",
  ui_story_5079_50791401_120_dialog_content = "Aku butuh kamu untuk berbalik dan berjalan menuju pintu masuk gua... Jangan takut, dan jangan menoleh ke belakang...",
  ui_story_5079_50791401_121_dialog_content = "Pact, aku butuh kamu berjalan perlahan mendekatiku. Jangan takut, dan jangan menoleh ke belakang...",
  ui_story_5079_50791401_122_dialog_content = "B-Buruan...",
  ui_story_5079_50791401_123_dialog_content = "B-Ayah?",
  ui_story_5079_50791401_124_dialog_content = "Kali ini, aku tidak berdoa kepada siapa pun atau apa pun...",
  ui_story_5079_50791401_125_dialog_content = "Aku akan menyelamatkan keluargaku dengan kedua tanganku sendiri!",
  ui_story_5079_50791501_1_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5079_50791501_2_dialog_content = "po...",
  ui_story_5079_50791501_3_dialog_content = "*Terengah-engah* Akhirnya...",
  ui_story_5079_50791501_4_dialog_content = "Masih bisa bergerak, Popo? Kamu harus... cepat...",
  ui_story_5079_50791501_5_dialog_content = "Monster wortel itu mengejarmu. Jika ia berhasil menyerap kebencianmu, kita tidak akan memiliki kesempatan melawannya...",
  ui_story_5079_50791501_6_dialog_content = "Tapi... Tapi ayahku, dia...",
  ui_story_5079_50791501_7_dialog_content = "Setelah aku mengalahkan makhluk itu, aku akan membawa Ayahmu padamu.",
  ui_story_5079_50791501_8_dialog_content = "Tapi sekarang Anda harus keluar dari sini, mengerti? Ini akan menjadi tantangan terbesar Anda sejauh ini!",
  ui_story_5079_50791501_9_dialog_content = "Aku... Aku bisa melakukannya!",
  ui_story_5079_50791501_10_dialog_content = "Tidak! Tidak ada yang bisa melarikan diri dari saya!",
  ui_story_5079_50791501_11_dialog_content = "Lawanmu ada di sini!",
  ui_story_5079_50791501_12_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5079_50791501_13_dialog_content = "po...",
  ui_story_5079_50791501_14_dialog_content = "Tsk, masih tidak ada kerusakan ya? Rasanya seperti...",
  ui_story_5079_50791501_15_dialog_content = "Popopo... Sepertinya kamu kehilangan sesuatu, ya?",
  ui_story_5079_50791501_16_dialog_content = "Kalau tidak salah, kamu hampir menghabiskan seluruh kekuatanmu, bukan?",
  ui_story_5079_50791501_17_dialog_content = "Apa yang bisa kamu lakukan tanpa senjata ini?",
  ui_story_5079_50791501_18_dialog_content = "Tsk... Jangan remehkan aku, monster!",
  ui_story_5079_50791501_19_dialog_content = "<color=#e8d9bb>Wuush! Plak—</color>",
  ui_story_5079_50791501_20_dialog_content = "...",
  ui_story_5079_50791501_21_dialog_content = "Sudah mencapai batasmu? Sungguh mengecewakan!",
  ui_story_5079_50791501_22_dialog_content = "Dengan senjata yang kamu berikan ini... Aku baru saja memulai!",
  ui_story_5079_50791501_23_dialog_content = "Argh!",
  ui_story_5079_50791501_24_dialog_content = "Jadi ini kekuatan Hunting Stone... Heh, ini pertama kalinya... aku merasakannya sendiri...",
  ui_story_5079_50791501_25_dialog_content = "Sepertinya aku harus membuktikan kekuatanku pada kamu juga...",
  ui_story_5079_50791501_26_dialog_content = "<color=#e8d9bb>Wuush! Plak—</color>",
  ui_story_5079_50791501_27_dialog_content = "*batuk* Kamu tidak memberiku kelonggaran hari ini, ya?",
  ui_story_5079_50791501_28_dialog_content = "Apakah ini rasa dendam yang kau rasakan padaku, Hunting Stone? Heheh...",
  ui_story_5079_50791501_29_dialog_content = "Aku pantas mendapatkannya, kusangka.",
  ui_story_5079_50791501_30_dialog_content = "Aku pikir kamu menolak untuk pergi bersamaku, tapi ternyata selama ini kamu berada di bawah kendali monster wortel ini...",
  ui_story_5079_50791501_31_dialog_content = "Selama ini kau telah membantuku, tapi aku menganggap enteng kebaikanmu dan terus-menerus mengeluh tentang ingin menghilangkanmu...",
  ui_story_5079_50791501_32_dialog_content = "Saya terus meyakinkan diri sendiri bahwa ini yang saya inginkan... Saya menjebak diri saya dalam kebohongan yang keras kepala.",
  ui_story_5079_50791501_33_dialog_content = "Dan karena itu... Aku menyerahkanmu kepada musuh.",
  ui_story_5079_50791501_34_dialog_content = "<color=#e8d9bb>Wuush! Plak—</color>",
  ui_story_5079_50791501_35_dialog_content = "Tsk, aku tidak tahu harus berbuat apa lagi...",
  ui_story_5079_50791501_36_dialog_content = "Popopo! Rasakan sengatan menghancurkan dari tentakelku yang berkekuatan!",
  ui_story_5079_50791501_37_dialog_content = "Aaahhhh!",
  ui_story_5079_50791501_38_dialog_content = "...",
  ui_story_5079_50791501_39_dialog_content = "Argh... Aku baik-baik saja. Lagi pula, ini bukan kali pertama... aku diikat oleh Hunting Stone.",
  ui_story_5079_50791501_40_dialog_content = "Baguslah Popo tidak ada di sini untuk melihat ini, atau dia akan melemparkan lebih banyak lagi hinaan padaku...",
  ui_story_5079_50791501_41_dialog_content = "Dia juga tidak di sini untuk menyelamatkanku kali ini...",
  ui_story_5079_50791501_42_dialog_content = "Hanya satu-satunya yang bisa membantuku sekarang...",
  ui_story_5079_50791501_43_dialog_content = "...",
  ui_story_5079_50791501_44_dialog_content = "Semua ini terasa sangat familiar...",
  ui_story_5079_50791501_45_dialog_content = "... Urgh.",
  ui_story_5079_50791501_46_dialog_content = "Ya, berjuang dan menderita... Itu hanya akan membuat ikatanmu semakin erat!",
  ui_story_5079_50791501_47_dialog_content = "Aku... Aku tidak perlu kamu memberitahuku itu... Tapi...",
  ui_story_5079_50791501_48_dialog_content = "A-Aku tidak ingin kalah... Hunting Stone.",
  ui_story_5079_50791501_49_dialog_content = "Aku tidak ingin kalah... hak untuk memiliki kamu di sisiku...",
  ui_story_5079_50791501_50_dialog_content = "...",
  ui_story_5079_50791501_51_dialog_content = "Kau tidak rindu menggelinding di wajahku saat aku tidur?",
  ui_story_5079_50791501_52_dialog_content = "Atau menakut-nakuti orang pada saat yang paling tidak tepat?",
  ui_story_5079_50791501_53_dialog_content = "Kamu tidak merindukan saat tanpa sengaja membuat lubang di gaun ku, atau bahkan melakukannya dengan sengaja?",
  ui_story_5079_50791501_55_dialog_content = "...",
  ui_story_5079_50791501_56_dialog_content = "Aku... milik... Pact...",
  ui_story_5079_50791501_57_dialog_content = "Tapi... tolong... ingat...",
  ui_story_5079_50791501_58_dialog_content = "Kekuatanku... semua datang...",
  ui_story_5079_50791501_59_dialog_content = "Dari... kamu!",
  ui_story_5079_50791501_60_dialog_content = "Hunting Stone... Kamu bisa berbicara?",
  ui_story_5079_50791501_61_dialog_content = "Apa gambaran-gambaran ini yang sedang aku lihat?",
  ui_story_5079_50791501_62_dialog_content = "Apakah ini... kenangan terawalku dengan Hunting Stone?",
  ui_story_5079_50791501_63_dialog_content = "Aduh... Kekuatan ini... Sungguh sakit sekali.",
  ui_story_5079_50791501_64_dialog_content = "Tidak... Tidak seperti ini! Aku ingin menggunakan kekuatanku untuk melawan Eclipsite...",
  ui_story_5079_50791501_65_dialog_content = "Jangan sampai kehilangan kendali di tempat ini...",
  ui_story_5079_50791501_66_dialog_content = "Gemerincing, gemerincing...",
  ui_story_5079_50791501_67_dialog_content = "Hah? Apakah kekuatanku... menghancurkan patung itu?",
  ui_story_5079_50791501_68_dialog_content = "Tidak... Itu masih di sana. Kamu, di sisi lain... Apakah itu meninggalkanmu?",
  ui_story_5079_50791501_69_dialog_content = "Sama seperti dewa yang meninggalkan kami di Old Town dan membiarkan kami mati di tangan Eclipsite...",
  ui_story_5079_50791501_70_dialog_content = "Aku kehilangan ibuku dan rumahku... Sejauh yang kita tahu, ayah dan aku mungkin akan dipisahkan oleh Eclipsite besok.",
  ui_story_5079_50791501_71_dialog_content = "Dan kamu... Kamu harus menghabiskan sisa hidupmu di tanah yang dingin, menatap patung yang pernah menjadi milikmu...",
  ui_story_5079_50791501_72_dialog_content = "Apakah itu sakit? Bisakah kamu beritahu aku... kenapa kita harus hidup dengan rasa sakit seperti ini?",
  ui_story_5079_50791501_73_dialog_content = "Bukan... Bukan begitu...",
  ui_story_5079_50791501_74_dialog_content = "Kau dan aku... Kita tidak sama... jadi berhenti pura-pura begitu malang.",
  ui_story_5079_50791501_75_dialog_content = "Patungmu ada di sana, jadi kamu masih punya tempat yang bisa disebut rumah... Tak apa, gunakan saja kekuatanku untuk kembali ke tempatmu yang seharusnya...",
  ui_story_5079_50791501_76_dialog_content = "<color=#e8d9bb>Gadis itu mengambil potongan patung yang rusak seolah-olah itu adalah bara terakhir di dunia malam yang abadi.</color>",
  ui_story_5079_50791501_77_dialog_content = "<color=#e8d9bb>Dengan keinginan yang kecil namun penuh keyakinan, dia menumpahkan seluruh kekuatannya ke dalamnya...</color>",
  ui_story_5079_50791501_78_dialog_content = "...",
  ui_story_5079_50791501_79_dialog_content = "Sekarang pergi. Pulanglah...",
  ui_story_5079_50791501_80_dialog_content = "...",
  ui_story_5079_50791501_81_dialog_content = "Apakah kamu bilang... kamu ingin tinggal denganku? Apakah kamu... benar-benar akan melakukan itu?",
  ui_story_5079_50791501_82_dialog_content = "Kekuatanku... Rasanya jauh lebih tenang sekarang. Apakah kamu membantuku memikul sebagian besar beban?",
  ui_story_5079_50791501_83_dialog_content = "Sekarang aku merasa sangat hangat dan nyaman... Terima kasih... Terima kasih banyak...",
  ui_story_5079_50791501_84_dialog_content = "A-Aku... Aku yang meminta Hunting Stone untuk tinggal bersamaku?",
  ui_story_5079_50791501_85_dialog_content = "Aku adalah orang yang memberikan kekuatanku...",
  ui_story_5079_50791501_86_dialog_content = "Ya... Kekuatan ini... Semuanya milikmu.",
  ui_story_5079_50791501_87_dialog_content = "Kamu sangat takut mengecewakan ayahmu... sehingga kamu menolak untuk percaya pada kekuatanmu sendiri.",
  ui_story_5079_50791501_88_dialog_content = "Untuk alasan itu, kau meyakinkan dirimu sendiri bahwa kekuatan ini berasal dariku...",
  ui_story_5079_50791501_89_dialog_content = "Aku tidak selemah yang kamu pikirkan... Aku hanya lupa, itu saja.",
  ui_story_5079_50791501_90_dialog_content = "Mungkin, tetapi di suatu tempat jauh di dalam hatimu, kamu selalu ingat.",
  ui_story_5079_50791501_91_dialog_content = "Bukan karena kamu tidak percaya diri dengan kemampuanmu, sebenarnya, kamu hanya ingin ada seseorang yang tetap di sisimu tidak peduli apa yang terjadi...",
  ui_story_5079_50791501_92_dialog_content = "Jadi, saya melakukan persis seperti itu. Saya adalah teman diam Anda — atau setidaknya saya ingin Anda merasa begitu tentang saya.",
  ui_story_5079_50791501_93_dialog_content = "Seorang teman yang pendiam seharusnya tetap angkat bicara ketika situasi membutuhkannya.",
  ui_story_5079_50791501_94_dialog_content = "Seandainya kamu memberitahuku lebih awal bahwa kamu bisa bicara. Aku...",
  ui_story_5079_50791501_95_dialog_content = "Mungkin aku bukan orang yang paling langsung dalam hal ini... tapi aku masih ingin tahu bagaimana perasaanmu kadang-kadang!",
  ui_story_5079_50791501_96_dialog_content = "Ini karena kamu sangat jujur tadi yang membuat aku akhirnya memilih untuk berbicara...",
  ui_story_5079_50791501_97_dialog_content = "Aku masih ingat betapa baiknya kamu padaku malam itu... Aku telah menunggu saat di mana kamu akhirnya bisa menerimaku.",
  ui_story_5079_50791501_98_dialog_content = "Itulah sebabnya saya bisa berdiri di sampingmu dan membantumu lagi!",
  ui_story_5079_50791501_99_dialog_content = "Tentang kekuatanmu, aku akan mengembalikan semuanya kepadamu!",
  ui_story_5079_50791501_100_dialog_content = "Aku tahu kekuatan dan kebaikanmu lebih baik dari siapa pun, Pact.",
  ui_story_5079_50791501_101_dialog_content = "Sekarang atasi rasa sakit dari masa lalu Anda dan kalahkan monster wortel itu!",
  ui_story_5079_50791501_102_dialog_content = "Humph, kau tidak perlu mengembalikannya padaku...",
  ui_story_5079_50791501_103_dialog_content = "Setelah semua, ini telah menjadi <color=#FFB400>kita</color> selama ini, bukan?",
  ui_story_5079_50791501_104_dialog_content = "<color=#e8d9bb>Wuuss! Crack!</color>",
  ui_story_5079_50791501_105_dialog_content = "Huh, ikatan ini hanyalah permainan anak-anak dibandingkan dengan apa yang sebenarnya bisa kita lakukan!",
  ui_story_5079_50791501_106_dialog_content = "Mengapa senjata ini tidak mau menurutiku?",
  ui_story_5079_50791501_107_dialog_content = "Aku masih ingin menikmati penderitaanmu sedikit lebih lama...",
  ui_story_5079_50791501_108_dialog_content = "Tapi sepertinya... waktu kita telah habis. Sebarkanlah, aroma wortel lezatku!",
  ui_story_5079_50791501_109_dialog_content = "Graaaaaah—",
  ui_story_5079_50791501_110_dialog_content = "Apa ini, lelucon? Kau pikir anak-anak kecil ini cukup untuk menghentikanku? Heh... Berarti kau tidak lebih kuat dari mereka, ya?",
  ui_story_5079_50791501_111_dialog_content = "Gorengan kecil, gorengan kecil!",
  ui_story_5079_50791501_112_dialog_content = "S-Ssst!",
  ui_story_5079_50791501_113_dialog_content = "Selama hal ini berada di bawah kendaliku, kamu tidak memiliki kekuatan di sini!",
  ui_story_5079_50791501_114_dialog_content = "Saya, di sisi lain, hanya perlu menyerap kebencian Popo... Minion! Belikan tuanmu lebih banyak waktu!",
  ui_story_5079_50791501_115_dialog_content = "Graaaaaah—",
  ui_story_5079_50791501_116_dialog_content = "Melarikan diri dengan Hunting Stone, ya? Kesalahan besar...",
  ui_story_5079_50791501_117_dialog_content = "Selama hati kita menjadi satu, jarak apa pun antara kita hanya akan membuat ikatan kita semakin kuat.",
  ui_story_5079_50791501_118_dialog_content = "Aku tidak akan membiarkanmu menyakiti Popo...",
  ui_story_5079_50791501_119_dialog_content = "Dan aku tidak akan membiarkan orang lain kabur dengan Hunting Stone-ku!",
  ui_story_5079_50791601_1_dialog_content = "<color=#e8d9bb>Apa, apa, apa!</color>",
  ui_story_5079_50791601_2_dialog_content = "Graaah...",
  ui_story_5079_50791601_3_dialog_content = "Minggir, kalian lemah!",
  ui_story_5079_50791601_4_dialog_content = "Ini tidak mungkin! Bagaimana bisa kau menyusulku dengan cepat sekali?",
  ui_story_5079_50791601_5_dialog_content = "<color=#e8d9bb>Swuuss—</color>",
  ui_story_5079_50791601_6_dialog_content = "Jauhkan tentakel kotormu dari Popo, monster kau!",
  ui_story_5079_50791601_7_dialog_content = "Itu... Itu kamu...",
  ui_story_5079_50791601_8_dialog_content = "Maaf, aku terlambat. Jangan khawatir, kamu sekarang aman...",
  ui_story_5079_50791601_9_dialog_content = "Aku... Aku tahu kau akan datang untuk menyelamatkanku. Aku tidak pernah ragu... tidak sedetik pun...",
  ui_story_5079_50791601_10_dialog_content = "Maafkan karena ketidakbergunaanku membuatku ditangkap lagi. Apakah ayahku—",
  ui_story_5079_50791601_11_dialog_content = "Seperti yang aku katakan, kamu tidak perlu khawatir lagi... Serahkan saja semuanya padaku.",
  ui_story_5079_50791601_12_dialog_content = "Jangan... Jangan berani-beraninya menatapku seolah-olah aku ini sampah belaka!",
  ui_story_5079_50791601_13_dialog_content = "Aku belum menunjukkan kekuatan penuhku padamu!",
  ui_story_5079_50791601_14_dialog_content = "Begitukah? Bagus. Saya juga tidak keberatan melihatnya sendiri.",
  ui_story_5079_50791601_15_dialog_content = "Aku siap untuk membiarkanmu hidup jika kamu hanya mengembalikan Batu Berburu milikku... tapi tidak lagi sekarang.",
  ui_story_5079_50791601_16_dialog_content = "Karena kamu bersikeras seperti ini, izinkan aku untuk menunjukkan kekuatan penuhku juga!",
  ui_story_5079_50791602_1_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5079_50791602_2_dialog_content = "Tidak mungkin! Tentakelku... Aduh... Bagaimana bisa kamu...",
  ui_story_5079_50791602_3_dialog_content = "!",
  ui_story_5079_50791602_4_dialog_content = "Tidak... Jangan pergi!",
  ui_story_5079_50791602_5_dialog_content = "Sudah berakhir untukmu!",
  ui_story_5079_50791602_6_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5079_50791602_7_dialog_content = "Tidaaak!",
  ui_story_5079_50791602_8_dialog_content = "!",
  ui_story_5079_50791602_9_dialog_content = "Hah? Apa yang membuatmu begitu senang? Sudahlah.",
  ui_story_5079_50791602_10_dialog_content = "Seharusnya kamu juga senang, Pact?",
  ui_story_5079_50791602_11_dialog_content = "\"Aku tidak akan membiarkan orang lain membawa lari Hunting Stone-KU!\" Itu yang kamu katakan, kan?",
  ui_story_5079_50791602_12_dialog_content = "?",
  ui_story_5079_50791602_13_dialog_content = "Kamu... Kamu pasti salah dengar! Aku tidak mengatakan hal seperti itu!",
  ui_story_5079_50791602_14_dialog_content = "Apa pun yang kamu pikir kamu dengar, lupakan sekarang juga!",
  ui_story_5079_50791602_15_dialog_content = "Baiklah...",
  ui_story_5079_50791602_16_dialog_content = "Tapi sepertinya akhirnya kamu menyadari bahwa kamu tidak memerlukan saya untuk mengendalikan kekuatanmu.",
  ui_story_5079_50791602_17_dialog_content = "Jadi kenapa repot-repot membawaku kembali? Aku bisa berhenti mengikutimu jika kau benar-benar menginginkannya...",
  ui_story_5079_50791602_18_dialog_content = "Ha?",
  ui_story_5079_50791602_19_dialog_content = "Satu-satunya alasan segalanya menjadi seburuk ini adalah karena saya menyerahkanmu kepada monster wortel bodoh itu.",
  ui_story_5079_50791602_20_dialog_content = "Jika sebuah Eclipsite berhasil menangkapmu, siapa tahu apa jenis masalah yang akan ditimbulkannya!",
  ui_story_5079_50791602_21_dialog_content = "...",
  ui_story_5079_50791602_22_dialog_content = "Selera Anda dalam memilih tuan yang akan datang juga cukup buruk. Maksud saya, wortel? Sungguh? Kamu tidak bisa hanya memilih apa saja yang ada di sekitar!",
  ui_story_5079_50791602_23_dialog_content = "Satu-satunya orang yang layak menjadi tuanmu adalah aku—wanita agung dan mulia, Lady Pact!",
  ui_story_5079_50791602_24_dialog_content = "Paham?",
  ui_story_5079_50791602_25_dialog_content = "...",
  ui_story_5079_50791602_26_dialog_content = "Kamu sedang menggodaku, bukan? Berhenti berpura-pura tidak bisa bicara!",
  ui_story_5079_50791602_27_dialog_content = "Aku bukan, hanya saja... kamu benar-benar terlihat seperti bangsawan sekarang...",
  ui_story_5079_50791602_28_dialog_content = "Ah...",
  ui_story_5079_50791602_29_dialog_content = "<size=30>Saya juga menerima pujian seperti \"cantik\" dan \"menggemaskan,\" lho...</size>",
  ui_story_5079_50791602_30_dialog_content = "Aku belum kalah!",
  ui_story_5079_50791602_31_dialog_content = "Aku... Aku akan menciptakan... dunia yang sempurna untuk semua wortel! Tempat di mana tidak ada yang akan meremehkan aku...",
  ui_story_5079_50791602_32_dialog_content = "Dunia di mana aku diinginkan, diterima... dan diizinkan untuk hidup!",
  ui_story_5079_50791602_33_dialog_content = "Setelah segala yang terjadi, kau masih terjebak dalam rasa dendammu?",
  ui_story_5079_50791602_34_dialog_content = "Kita harus mengeluarkanmu dari situ—",
  ui_story_5079_50791602_35_dialog_content = "T-<size=45>Tunggu!</size>",
  ui_story_5079_50791602_36_dialog_content = "?",
  ui_story_5079_50791602_37_dialog_content = "Maaf! Seharusnya aku tidak meninggalkanmu di sini atau mengatakan semua hal buruk itu...",
  ui_story_5079_50791602_38_dialog_content = "Kata-kataku menyakitimu, bukan?",
  ui_story_5079_50791602_39_dialog_content = "Berat, bukan? Menghabiskan semua hari di sini sendirian...",
  ui_story_5079_50791602_40_dialog_content = "Tak ada orang untuk diajak bicara, tak ada yang membutuhkanmu... Saya mengerti bagaimana rasanya...",
  ui_story_5079_50791602_41_dialog_content = "Tapi jika kamu bersedia memberi saya kesempatan lagi...",
  ui_story_5079_50791602_42_dialog_content = "Bisakah kita... Bisakah kita menjadi teman?",
  ui_story_5079_50791602_43_dialog_content = "...",
  ui_story_5079_50791602_44_dialog_content = "Aku ingin menanammu di tempat yang paling cerah dan paling subur di kebun kita.",
  ui_story_5079_50791602_45_dialog_content = "Saya ingin kamu mengambil semua nutrisi yang dibutuhkan untuk tumbuh besar dan kuat dan menjadi wortel yang akan disukai semua orang untuk dimakan!",
  ui_story_5079_50791602_46_dialog_content = "Uh, Popo? Menawarkan untuk memakannya bukanlah hal yang paling menenangkan untuk dikatakan... Bukankah kamu lebih suka jika dia memiliki kehidupan yang panjang dan sehat?",
  ui_story_5079_50791602_47_dialog_content = "<color=#e8d9bb>Puf!</color>",
  ui_story_5079_50791602_48_dialog_content = "Po... Popo—",
  ui_story_5079_50791602_49_dialog_content = "Apakah ini berarti... kamu memaafkanku?",
  ui_story_5079_50791602_50_dialog_content = "Popo!",
  ui_story_5079_50791602_51_dialog_content = "Tahu kan, wortel juga bisa cukup imut...",
  ui_story_5079_50791602_52_dialog_content = "Bagaimana menurutmu? Haruskah kita mencoba wortel lagi?",
  ui_story_5079_50791602_53_dialog_content = "Uh... Aku rasa aku butuh sedikit lebih banyak waktu untuk memikirkan itu.",
  ui_story_5079_50791602_54_dialog_content = "(Jadi, ide hidup yang baik menurutnya adalah dimakan oleh seseorang yang disukainya...)",
  ui_story_5079_50791602_55_dialog_content = "(Yah, selama itu yang memberikannya kepuasan...)",
  ui_story_5079_50791602_56_dialog_content = "... Popo?",
  ui_story_5079_50791602_57_dialog_content = "Ayah? Ahh! Coba untuk tidak bergerak! Kamu penuh dengan luka...",
  ui_story_5079_50791602_58_dialog_content = "Saya hampir tidak merasakan apa-apa... Melihat kamu hidup dan sehat, itu semua yang saya butuhkan...",
  ui_story_5079_50791602_59_dialog_content = "Ini semua salahku, Popo. Aku seharusnya tidak memerintahmu terlalu banyak... atau memaksakan ide-ideku padamu...",
  ui_story_5079_50791602_60_dialog_content = "Saya terlalu terobsesi untuk memberikan kita kehidupan keluarga yang \"ideal\".",
  ui_story_5079_50791602_61_dialog_content = "Dan aku menaruh beban ambisiku di pundakmu.",
  ui_story_5079_50791602_62_dialog_content = "Setelah semua, hidupku tidak pernah berarti banyak. Aku tidak pernah melakukan apa-apa selain menderita kehilangan demi kehilangan. Bahkan aku...",
  ui_story_5079_50791602_63_dialog_content = "Bahkan aku kehilangan cinta dalam hidupku, ibumu... Semua ini karena aku tidak bisa melindunginya...",
  ui_story_5079_50791602_64_dialog_content = "Ayah... Selama ini, kau menyembunyikan rasa sakitmu atas kematian ibuku...",
  ui_story_5079_50791602_65_dialog_content = "Dan kali ini, aku gagal melindungimu...",
  ui_story_5079_50791602_66_dialog_content = "Ketika kamu kabur dari rumah, ada sesuatu yang terus mengganggu pikiranku—apa sebenarnya yang telah aku berikan untuk keluargaku?",
  ui_story_5079_50791602_67_dialog_content = "Apakah itu tidak lebih dari sekedar kenangan yang menyakitkan?",
  ui_story_5079_50791602_68_dialog_content = "Yang aku inginkan hanyalah menjadi keluarga pedagang kaya suatu hari nanti dan makan di meja yang sama dengan para bangsawan Lumopolis.",
  ui_story_5079_50791602_69_dialog_content = "Untuk menyaksikanmu tumbuh dan menjadi bintang yang bersinar yang menarik perhatian semua orang, termasuk para bangsawan...",
  ui_story_5079_50791602_70_dialog_content = "Aku begitu dibutakan oleh mimpiku sehingga aku tidak pernah menghargai makanan sederhana kita di toko kecil kita atau memperhatikan cara kamu tersenyum saat makan makanan favoritmu...",
  ui_story_5079_50791602_71_dialog_content = "Menggenggam momen-momen itu adalah arti dari hidup! Untuk benar-benar bahagia!",
  ui_story_5079_50791602_72_dialog_content = "Aku—",
  ui_story_5079_50791602_73_dialog_content = "Aku... Aku juga ingin Ayah bahagia! Itulah mengapa aku akan terus melakukan yang terbaik!",
  ui_story_5079_50791602_74_dialog_content = "Aku akan lebih mendengarkanmu dan berhenti membuat banyak masalah untukmu! Asalkan...",
  ui_story_5079_50791602_75_dialog_content = "Selama kita bersama! Aku akan bahagia selamanya selama aku bersamamu, Ayah!",
  ui_story_5079_50791602_76_dialog_content = "<size=30>Jujur saja... Bukankah sebaiknya kamu pulang sebelum membicarakan semua hal menyedihkan ini?</size>",
  ui_story_5079_50791602_77_dialog_content = "<size=30>Aku hampir saja mengatakan sesuatu juga... Ini sangat canggung.</size>",
  ui_story_5079_50791602_78_dialog_content = "Hah? Apa yang ada di sudut mata saya?",
  ui_story_5079_50791602_79_dialog_content = "Apakah sedang hujan? Bagus, itu seharusnya bisa menghilangkan bau wortel...",
  ui_story_5079_50791602_80_dialog_content = "*Tersedu* Berhenti menangis, kamu bodoh!",
  ui_story_5079_50791602_81_dialog_content = "Ah... Lebih baik aku tidak merusak pakaianku karena air mata ini.",
  ui_story_5079_50791602_82_dialog_content = "Pada akhirnya—",
  ui_story_5079_50791602_83_dialog_content = "Kamu mewujudkan mimpi ayahmu pada akhirnya, 'kan?",
  ui_story_5079_50791602_84_dialog_content = "Ah!",
  ui_story_5079_50791602_85_dialog_content = "Sebelum melakukan jenis bisnis apa pun, membuat diri Anda terlihat bermartabat dan menarik adalah hal paling penting yang bisa Anda lakukan.",
  ui_story_5079_50791602_86_dialog_content = "Hanya dengan melakukan hal tersebut, pelanggan kaya akan memberikan waktu dan dukungan mereka kepada Anda.",
  ui_story_5079_50791602_87_dialog_content = "Kamu... Kapan kamu menyadarinya?",
  ui_story_5079_50791602_88_dialog_content = "Ketika kamu tanpa sengaja memanggilnya \"ayah\" sebelumnya, itu menjadi terlalu jelas.",
  ui_story_5079_50791602_89_dialog_content = "Sepertinya kamu telah menemukan jawabannya, Pact.",
  ui_story_5079_50791602_90_dialog_content = "Jangan berpikir kamu pintar atau apa... Aku hanya salah bicara, itu saja...",
  ui_story_5079_50791602_91_dialog_content = "Dan berhentilah melihatku! Tidak ada yang boleh melihatku saat aku menangis!",
  ui_story_5079_50791602_92_dialog_content = "Hei! Jangan pergi!",
  ui_story_5079_50791602_93_dialog_content = "Hah? Oh, tidak...",
  ui_story_5079_50791602_94_dialog_content = "<color=#e8d9bb>Memukul—</color>",
  ui_story_5079_50791602_95_dialog_content = "...",
  ui_story_5079_50791602_96_dialog_content = "Itu kedua kalinya kamu menabrakku seperti itu, Popo.",
  ui_story_5079_50791602_97_dialog_content = "Aku tidak peduli! Kamu tidak bisa pergi dulu! Kamu tidak bisa! Aku... Aku masih belum berterima kasih dengan benar!",
  ui_story_5079_50791602_98_dialog_content = "Aku tidak bilang aku akan pergi, aku hanya... <size=30>tidak ingin kalian berdua melihatku seperti ini.</size>",
  ui_story_5079_50791602_99_dialog_content = "Lagipula, kamu tidak perlu berterima kasih atas apapun... Aku hanya melakukan apa yang seharusnya kulakukan.",
  ui_story_5079_50791602_100_dialog_content = "Ya, benar! Kamu hanya tidak mau mengakui bahwa kamu adalah orang yang baik! Tapi sekarang aku tahu kamu adalah salah satu orang terbaik di luar sana!",
  ui_story_5079_50791602_101_dialog_content = "Terima kasih telah membantu saya berbaikan dengan ayah saya, dan terima kasih...",
  ui_story_5079_50791602_102_dialog_content = "Karena telah menunjukkan padaku... bahwa aku sangat dicintai!",
  ui_story_5079_50791602_103_dialog_content = "Aku... aku akan berusaha sebaik mungkin!",
  ui_story_5079_50791602_104_dialog_content = "Mulai sekarang, aku akan bekerja keras untuk menjadi orang yang kuat dan baik, seperti dirimu!",
  ui_story_5079_50791602_105_dialog_content = "Aku? Heh... Aku tidak pantas disebut sebagai panutan.",
  ui_story_5079_50791602_106_dialog_content = "Terus bergerak maju dan kamu akan baik-baik saja, Popo.",
  ui_story_5079_50791602_107_dialog_content = "Terus bergerak maju, ikuti kata hatimu, dan jangan pernah menoleh ke belakang.",
  ui_story_5079_50791602_108_dialog_content = "Lakukan itu, dan Anda akan bertemu dengan berbagai jenis orang yang luar biasa—orang yang menghargai Anda, orang yang tertawa bersama Anda, dan orang yang mengisi Anda dengan kehangatan sepanjang perjalanan Anda.",
  ui_story_5079_50791602_109_dialog_content = "Jika kamu pernah tersesat, cukup angkat kepalamu...",
  ui_story_5079_50791602_110_dialog_content = "Pandanglah langit yang penuh bintang dengan seksama, dan kau akan menemukan jawaban yang kau butuhkan, seperti yang telah aku lakukan.",
  ui_story_5079_50791602_111_dialog_content = "Karena...",
  ui_story_5079_50791602_112_dialog_content = "Saya adalah kamu, Popo.",
  ui_story_5079_50791602_113_dialog_content = "Tunggu... Apakah kamu adalah diriku di masa depan?",
  ui_story_5079_50791602_114_dialog_content = "Saya benar-benar berharap saya bisa menjadi sehebat Anda suatu hari nanti!",
  ui_story_5079_50791602_115_dialog_content = "Kamu pasti akan, percayalah padaku.",
  ui_story_5079_50791602_116_dialog_content = "Ah, ayah memintaku untuk pulang sekarang...",
  ui_story_5079_50791602_117_dialog_content = "Tidak peduli ke mana kamu pergi, jangan lupakan aku, ya?",
  ui_story_5079_50791602_118_dialog_content = "Popo...",
  ui_story_5079_50791602_119_dialog_content = "Setelah aku mengingat sesuatu, aku tidak akan pernah melupakannya.",
  ui_story_5079_50791602_120_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50791602_121_dialog_content = "Saatnya bagi kita untuk pergi.",
  ui_story_5079_50791602_122_dialog_content = "Ya, kamu benar, tapi aku benar-benar ingin tahu...",
  ui_story_5079_50791602_123_dialog_content = "Di masa depan, apakah dia akan memiliki masa kecil yang lebih bahagia daripada saya di sini di Folta?",
  ui_story_5079_50791602_124_dialog_content = "Bisakah dia tersenyum untuk semua waktu di mana aku tidak bisa?",
  ui_story_5079_50791602_125_dialog_content = "Tidakkah dia pernah harus merasakan kemarahan atau kesedihan yang sama seperti yang pernah kurasakan?",
  ui_story_5079_50791602_126_dialog_content = "Apakah dia... akan mampu menjalani hidupnya tanpa menghadapi masa kecil yang menyakitkan?",
  ui_story_5079_50791602_127_dialog_content = "... Aku yakin dia akan baik-baik saja. Lagipula, kamu sudah menyembuhkan begitu banyak orang lain, termasuk dirimu sendiri.",
  ui_story_5079_50791602_128_dialog_content = "Ingat, kamu adalah Lady Pact yang baik hati dan mulia.",
  ui_story_5079_50791602_129_dialog_content = "Kamu menemukan jalannya sudah lama sekali. Persis seperti yang kamu katakan—",
  ui_story_5079_50791602_130_dialog_content = "\"Terus bergerak maju, ikuti kata hatimu, dan jangan pernah menoleh ke belakang.\"",
  ui_story_5079_50791602_131_dialog_content = "Masa depan Popo penuh dengan begitu banyak kemungkinan yang luar biasa, dan begitu pula milikmu!",
  ui_story_5079_50791602_132_dialog_content = "Seperti yang saya duga, kau hanya bicara saat waktunya memberikan pidato besar, dan setelah itu tidak ada yang bisa menghentikanmu.",
  ui_story_5079_50791602_133_dialog_content = "Jangan terlalu sentimental. Masalahku tidak terselesaikan hanya karena kamu mengatakan beberapa kata baik.",
  ui_story_5079_50791602_134_dialog_content = "Sekarang jika aku pikirkan, kau benar-benar mengingatkanku pada Hunting Stone-ku kadang-kadang, PlayerName.",
  ui_story_5079_50791602_135_dialog_content = "Hah? Kapan kamu menyadarinya?",
  ui_story_5079_50791602_136_dialog_content = "Tidak sulit. Yang perlu saya lakukan hanyalah menggabungkan pertunjukan kecilmu dan kebiasaanmu memberikan pidato semangat.",
  ui_story_5079_50791602_137_dialog_content = "Ini adalah hikmah yang saya dapatkan dari aturan-aturan tersebut. Apakah kamu ingin saya menjelaskannya untukmu?",
  ui_story_5079_50791602_138_dialog_content = "...",
  ui_story_5079_50791602_139_dialog_content = "Sudah kubilang: berhenti berpura-pura tidak bisa bicara! Itu membuat suasana menjadi canggung!",
  ui_story_5079_50791602_140_dialog_content = "A... Aku sebenarnya setuju denganmu dalam banyak hal!",
  ui_story_5079_50791602_141_dialog_content = "Masih banyak kata yang belum kukatakan... dan hal-hal yang belum selesai!",
  ui_story_5079_50791602_142_dialog_content = "Mari kembali ke dunia nyata... tempat kita benar-benar hidup.",
  ui_story_5079_50791602_143_dialog_content = "Aku sudah memutuskan untuk memberimu sebuah misi... satu-satunya misi yang hanya bisa kamu selesaikan.",
  ui_story_5079_50791602_144_dialog_content = "Dan sebelum kamu bertanya, tidak ada cara untuk menolaknya... J-Jadi tolong luangkan waktu untuk itu!"
}
return config
